insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0204$t$, $t$Bogota Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Bogota Building Department (Construction Code and Zoning Official)","Contact: Arthur Sopelsa, Construction Code and Zoning Official (Building Department staff contact: Crissy Tedesco) · 201-342-1736 x224 · ctedesco@bogotanj.gov","Apply: Fees go up when the request comes in late: base fee more than 20 business days before the change of occupant, double at 10 to 20 days, triple at under 10 days.","How to apply: Print and fill in the Borough's Certificate of Continued Occupancy (CCO) Permit Application (Building Department page or Forms page) and file it with the Building Department at the Bogota Municipal Building, 375 Larch Avenue, Bogota, NJ 07603, with the fee. Apply more than 20 business days before closing to pay the base fee. Office hours: Monday, Wednesday and Thursday 9:00am to 5:15pm, Tuesday 11:00am to 7:00pm, Friday 9:00am to 12:00pm.","Valid for: A temporary certificate of occupancy (90 day maximum, not extendable) is available at half the fee plus a 120% bond for unfinished work.","Borough CCO application, which is also the smoke detector, carbon monoxide and fire extinguisher certification form","Access to the dwelling unit, basement, attic and common areas for the inspection","New buyer or tenant names and the number of dwelling units must be listed on the application","Fire extinguisher (form still lists it)","Also: Late-request surcharge: CCO fees double if the request comes 10 to 20 days before the change of occupant and triple if under 10 days."]$j$::jsonb, $j$[{"label":"CCO, one-family dwelling (sale or rental), request received more than 20 business days before the change of occupant","amount":"$100.00"},{"label":"CCO, two-family dwelling (sale or rental), request received more than 20 business days before the change of occupant","amount":"$150.00"},{"label":"CCO request received 10 to 20 days before the change of occupant","amount":"$200.00 one-family, $300.00 two-family (double the base fee)"},{"label":"CCO request received less than 10 days before the change of occupant","amount":"$300.00 one-family, $450.00 two-family (triple the base fee)"}]$j$::jsonb, $t$https://www.bogotanj.gov/_files/ugd/8d609e_050480fbed154e0fbcaa41c19bd4b2e9.pdf$t$, $t$https://www.bogotanj.gov/bldgdept$t$, $j$[{"url":"https://www.bogotanj.gov/forms","label":"Official source (bogotanj.gov)"},{"url":"https://www.bogotanj.gov/bldgdept","label":"Official source (bogotanj.gov)"},{"url":"https://www.bogotanj.gov/_files/ugd/8d609e_050480fbed154e0fbcaa41c19bd4b2e9.pdf","label":"Official source (bogotanj.gov)"},{"url":"https://ecode360.com/34713647","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$(CCO) Permit Application$t$, $t$58691d8ad86d9a1a9ed3891e133df7f34db4dc2d19a8bccf840a4ec1c35d71b2$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":20,"q_ok":11,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0204.json$t$, true),
  ($t$0204$t$, $t$Bogota Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Bogota Building Department (smoke detector compliance on the CCO form); fire code enforcing agency: Bogota Bureau of Fire Prevention (town fire bureau)","Contact: Daniel Klima, Fire Marshal (Fire Official) · 201-646-0801 · dklima@bogotanj.gov","Apply: Same as the CCO: base fee more than 20 business days before the change of occupant, double at 10 to 20 days, triple at under 10 days.","How to apply: File the Borough's CCO / smoke detector, carbon monoxide and fire extinguisher certification application with the Building Department at 375 Larch Avenue. Questions about alarm rules can go to the Fire Prevention Bureau at 31 Fairview Avenue (Monday to Friday, 8:00am to 2:30pm).","Fire official in the NJ state directory, updated 5/14/2026: Daniel Klima · (201) 342-1736 · dklima@bogotaonline.org","Smoke detectors and carbon monoxide alarms checked on the Borough's combined smoke detector / carbon monoxide / fire extinguisher certification (the CCO application)","Access to the dwelling unit, basement, attic and common areas","Fire extinguisher (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certification on the CCO, one-family (same fee as the CCO, not an extra charge)","amount":"$100.00"},{"label":"Smoke/CO certification on the CCO, two-family (same fee as the CCO, not an extra charge)","amount":"$150.00"}]$j$::jsonb, $t$https://www.bogotanj.gov/_files/ugd/8d609e_050480fbed154e0fbcaa41c19bd4b2e9.pdf$t$, $t$https://www.bogotanj.gov/fire-prevention$t$, $j$[{"url":"https://www.bogotanj.gov/_files/ugd/8d609e_050480fbed154e0fbcaa41c19bd4b2e9.pdf","label":"Official source (bogotanj.gov)"},{"url":"https://www.bogotanj.gov/fire-prevention","label":"Official source (bogotanj.gov)"},{"url":"https://ecode360.com/34716012","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/34713647","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$SMOKE DETECTOR - CARBON MONOXIDE - FIRE EXTINGUISHER CERTIFICATION$t$, $t$7dc7f67428dae8ea19bf1e8bbc61d5c7b8903c33230b2be6654681ec31e4b180$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":20,"q_ok":11,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0204.json$t$, true),
  ($t$0250$t$, $t$Ridgefield Park Village$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (CCO) for Sale of 1 or 2 Family Dwelling$t$, $j$["Issued by: Village of Ridgefield Park Building Department (Housing Inspector under the Construction Official)","Contact: Michael Landolfi, Construction Official · 201-641-4950 Ext. 4","Apply: File at least 12 days before closing (a higher fee applies after that). The application is reviewed and the certificate issued within 10 days.","How to apply: Fill out the new combined Certificate of Compliance application for sale or rental of a 1 or 2 family home, condo or co-op (Building Department Forms & Applications page; posted September 2026), get the Tax/Finance office to sign that taxes are current, and file it with the fee at the Building Department, 234 Main Street, Room 209, at least 12 days before closing. Office hours Monday through Friday, 8:30 am to 4:30 pm. The same inspection covers smoke alarms, CO alarms and the extinguisher.","Valid for: Not transferable; if the change of occupancy does not happen within six months, a new application, inspection and certificate are needed.","Inspection confirms the home is legally occupied under the Village Zoning Code (1 family or 2 family)","Smoke alarms on each level and within 10 feet of each sleeping area (UL 217; battery or AC)","CO alarms (UL 2034, NFPA 720) in the immediate vicinity of sleeping rooms in homes with fuel-burning appliances or attached garages","Fire extinguisher in the kitchen of 1 and 2 family homes, 2A:10B:C, no more than 10 pounds, within 10 feet of the kitchen, top no more than 5 feet above the floor (code and form still list it)","Inspector also notes finished attic or basement, attic bathroom, basement kitchen or bath, exterior locks on bedroom doors, property maintenance (cut grass, shrubs, hedges) and a 4-inch house number visible from the street","Notarized acknowledgment signed by the owner/new owner (and tenant) that attics in two-story 1-2 family homes and basements may not be used as bedrooms or habitable space","Tax/Finance office sign-off that taxes are current, and an open permits check, before the certificate of resale is released (page 2 of the new application)","Lead-Based Paint Hazards addendum for homes built before 1978 (aimed at rentals under P.L.2021, c.182)","Also: Attic and basement occupancy affidavit: Buyers (and any tenants) sign a notarized acknowledgment that attics in two-story 1-2 family homes may not be habitable space and basements may not be bedrooms.","Also: Rental registration letter: New owners return a Fire Prevention letter saying whether they will rent the home; non-owner-occupied 1-2 family homes must register with the Bureau of Fire Prevention (rental-only).","Also: Taxes current and open permits: The new application has a page the Tax/Finance office signs to confirm taxes are current before the certificate of resale is released, plus an open permits check.","Also: Lead-based paint addendum (pre-1978): The packet includes a Lead-Based Paint Hazards addendum for homes built before 1978, under the state rental lead law (P.L.2021, c.182). If the Village inspector does the LPH inspection the form says the fee is $250/unit, in addition to the certificate fee. This is a rental requirement; ask whether it applies to an owner-occupied sale."]$j$::jsonb, $j$[{"label":"Certificate of compliance, sale of a 1 family dwelling (fee on the September 2026 Village application)","amount":"$125"},{"label":"Certificate of compliance, sale of a 2 family dwelling (fee on the September 2026 Village application)","amount":"$200"},{"label":"Village Code §153-8: application at least 12 days before the change of occupancy (older code amount; the new form shows higher fees)","amount":"$75"},{"label":"Village Code §153-8: application fewer than 12 days before the change of occupancy (older code amount)","amount":"$95"},{"label":"Village Code §153-8: reinspection","amount":"$25"}]$j$::jsonb, $t$https://www.ridgefieldpark.org/DocumentCenter/View/2082/Certificate-of-Compliance-for-sale-or-rental-of-1-or-2-family-condo-or-co-op-application$t$, $t$https://www.ridgefieldpark.org/199/Building-Department$t$, $j$[{"url":"https://ecode360.com/13318092","label":"Official source (ecode360.com)"},{"url":"https://www.ridgefieldpark.org/196/Fire-Prevention","label":"Official source (ridgefieldpark.org)"},{"url":"https://www.ridgefieldpark.org/202/Forms-Applications","label":"Official source (ridgefieldpark.org)"},{"url":"https://www.ridgefieldpark.org/199/Building-Department","label":"Official source (ridgefieldpark.org)"},{"url":"https://www.ridgefieldpark.org/DocumentCenter/View/2082/Certificate-of-Compliance-for-sale-or-rental-of-1-or-2-family-condo-or-co-op-application","label":"Official source (ridgefieldpark.org)"}]$j$::jsonb, $t$A certificate of compliance shall be required in all changes of occupancy in all residential dwelling units.$t$, $t$3ae320a061290d3863686e5ac96c59c2789abd35d353392649344214757b3200$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":18,"q_ok":9,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0250.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0250.json$t$, true),
  ($t$0250$t$, $t$Ridgefield Park Village$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Village of Ridgefield Park Building Department (Certificate of Compliance covers smoke/CO; Bureau of Fire Prevention is the fire code agency) (town fire bureau)","Contact: 201-641-4950 Ext. 4","Apply: File at least 12 days before closing for the lower fee. Certificate valid six months for the stated change of occupancy.","How to apply: The smoke alarm, CO alarm and extinguisher check is part of the Building Department's Certificate of Compliance inspection; there is no separate fire application for a 1-2 family sale. File the Certificate of Compliance application at 234 Main Street, Room 209.","Fire official in the NJ state directory (town), updated 2/19/2026: Peter A Danzo · (201) 440-2570 · pdanzo@ridgefieldpark.org","Smoke alarms on each level and within 10 feet of each sleeping area (NFPA 74 placement, UL 217; battery or AC powered)","CO alarms (UL 2034, NFPA 720; battery, hardwired or plug-in) in the immediate vicinity of all sleeping rooms, no more than 10 feet away, in homes with fuel-burning appliances or attached garages","Fire extinguisher 2A:10B:C, no more than 10 pounds, manufacturer's bracket, within 10 feet of the kitchen, top no more than 5 feet above the floor; serviced and tagged within 12 months or a recent purchase receipt (code and form still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of compliance (same certificate as the resale CCO, not an extra charge), sale of a 1 family dwelling (fee on the September 2026 Village application)","amount":"$125"},{"label":"Certificate of compliance (same certificate as the resale CCO, not an extra charge), sale of a 2 family dwelling (fee on the September 2026 Village application)","amount":"$200"},{"label":"Village Code §153-8: application at least 12 days before the change of occupancy (older code amount; the new form shows higher fees)","amount":"$75"},{"label":"Village Code §153-8: application fewer than 12 days before the change of occupancy (older code amount)","amount":"$95"},{"label":"Village Code §153-8: reinspection","amount":"$25"}]$j$::jsonb, $t$https://www.ridgefieldpark.org/DocumentCenter/View/2082/Certificate-of-Compliance-for-sale-or-rental-of-1-or-2-family-condo-or-co-op-application$t$, $t$https://www.ridgefieldpark.org/196/Fire-Prevention$t$, $j$[{"url":"https://www.ridgefieldpark.org/196/Fire-Prevention","label":"Official source (ridgefieldpark.org)"},{"url":"https://ecode360.com/13318092","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.ridgefieldpark.org/DocumentCenter/View/2082/Certificate-of-Compliance-for-sale-or-rental-of-1-or-2-family-condo-or-co-op-application","label":"Official source (ridgefieldpark.org)"}]$j$::jsonb, $t$Existing Buildings - Before any change of occupancy may take place, a Certificate of Smoke Detector and CO Detector Compliance shall be obtained from the Village Building Department.$t$, $t$79ae12e5845fe401842228c2137d72f35df67e2bd13cd9b65869138b25b6bdca$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":18,"q_ok":9,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0250.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0250.json$t$, true),
  ($t$0319$t$, $t$Maple Shade Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Certificate of Inspection / Certificate of Continued Occupancy), Housing Code Chapter 155$t$, $j$["Issued by: Maple Shade Township Housing Inspection (Land Use / Community Development; Housing Inspector or Code Enforcement Officer)","Contact: Kyle Wagner, Director of Community Development (Zoning Officer / Planning Administration) · 856-779-9610 ext. 151 · zoning@mapleshade.com","Apply: No lead time published. Violations found at the first inspection must be fixed and re-inspected within 90 days (extendable once to 120 days if asked before day 90), or a new application and fee are needed.","How to apply: Fill out the Application for Residential Certificate of Occupancy (property, block and lot, seller, buyer, agent, rooms per floor, access contact), signed by owner and buyer, and submit it with the $125.00 fee by cash or check to Maple Shade Township Housing Inspection, 200 Stiles Avenue, Maple Shade, NJ 08052 (fax 856-779-2524, email Zoning@MapleShade.com). For an as-is sale where the buyer will not move in until repairs are done, use the Transfer of Title application instead ($75, one battery smoke detector per level); the buyer must then apply for the full CO within 120 days.","Valid for: Valid until the next sale, transfer or change of occupancy; not transferable to a new owner except between spouses or family members.","House numbers visible from the street, 4 inches high, contrasting color","Sidewalks, driveways and curbs without raised cracks over 1/2 inch or damage","Roof sound; signs of leaks need a licensed roofer's certification","Gutters and downspouts draining away from the building; front and rear exterior lights","Handrail on front steps with more than 3 risers; guardrails on decks and porches over 30 inches with balusters under 4 inches apart","Peeling paint scraped and painted; rotted wood, loose siding and broken glass repaired; screens on all windows","Yard cut and cleared; trash and recycling cans stored out of view from the street","10-year sealed battery smoke detector on every level and in every bedroom, none more than 10 years old; CO detectors within 10 feet of all sleeping areas","2A:10B:C fire extinguisher mounted in the kitchen area per NJ fire code","Graspable handrails on all stairs including basement; guards on open sides","Outlets, switches and fixtures working with covers; GFCI at kitchen counters, within 6 feet of sinks, bathrooms and washer","Windows open, close, lock and stay up; exterior door locks not keyed from inside; no infestation","Fireplaces and chimneys certified by a licensed contractor; termite damage needs an exterminator's certificate","Basement: water heater relief pipe within 6 inches of floor, emergency heater switch, sump pump to the outside (not the sewer), 60 amp minimum service with labeled breakers, hard-piped dryer vent, abandoned oil tanks removed with a permit","Stove anti-tip device; bedrooms need proper egress, and no basement bedrooms without egress; work done without permits must be permitted","Also: Work done without permits: Permits are needed for new wiring, plumbing, electrical service or panel, heater, A/C, water heater and similar work. A buyer of a home with unpermitted improvements takes on getting and closing those permits.","Also: As-is (rehab / fixer upper) sales: The home must stay vacant until permits and CO approvals are done. A Certificate for Transfer of Property Title ($75, valid 120 days) allows the closing; the full CO application must be filed before it expires."]$j$::jsonb, $j$[{"label":"Residential CO, initial inspection and first re-inspection","amount":"$125"},{"label":"Each later re-inspection","amount":"$65"},{"label":"Residential CO application fee on the form (cash or check)","amount":"$125.00"},{"label":"As-is sale where no one will move in: Certificate for Transfer of Property Title (smoke detector inspection only; valid 120 days)","amount":"$75"}]$j$::jsonb, $t$https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf$t$, $t$https://mapleshade.com/certificate-of-occupancy/$t$, $j$[{"url":"https://mapleshade.com/certificate-of-occupancy/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2025/12/ORDINANCE-2025-18.pdf","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/03/Maple-Shade-Township-Housing-Inspection-Checklist.pdf","label":"Official source (mapleshade.com)"}]$j$::jsonb, $t$Effective immediately, properties within the Township of Maple Shade are required to obtain a Certificate of Occupancy Inspection & Approvals prior to: The Sale of a Property whether Residential or Commercial.$t$, $t$6a67ac571d49fd5e7231456bafd9ac4835f8103c260d08b149a4d98ee08a9941$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0319.json$t$, true),
  ($t$0319$t$, $t$Maple Shade Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bureau of Fire Prevention (serving Maple Shade and Moorestown); the Resale Smoke Alarm Application was replaced by the Township's Residential CO Form (town fire bureau)","Contact: Matthew Orsini, Fire Official · (856) 779-9610 ext. 179 · firemarshal@mapleshade.com","Apply: Not published.","How to apply: Use the Township's Residential CO Form (it replaced the Resale Smoke Alarm Application) and submit it with the fee to Maple Shade Township Housing Inspection, 200 Stiles Avenue (Zoning@MapleShade.com). For an as-is sale with no occupancy, use the Transfer of Title form. The shared Bureau of Fire Prevention site links Maple Shade's 'Residential Smoke Inspection for Change of Occupancy' to the Township's Certificate of Occupancy page. Fire safety questions can go to the Fire Official (ext. 179) or the Bureau office at 225 N Lenola Rd, Moorestown, 856-234-1222 (8:00 am to 4:00 pm).","Fire official in the NJ state directory (town), updated 9/10/2025: Matthew Orsini · (856) 779-9610 · firemarshal@mapleshade.com","Smoke detectors: 10-year sealed battery units, one on each level and one in each bedroom; no detector more than 10 years old (Township checklist, March 2026)","Carbon monoxide detectors within 10 feet of all sleeping areas","Fire extinguisher still listed on the March 2026 Township checklist: 2A:10B:C, mounted per NJ fire code in the kitchen area","For an as-is Transfer of Title sale (no one moving in): at least one battery smoke detector on each level, inspected before the transfer certificate is issued","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"No separate smoke certificate fee; the resale smoke/CO check is now part of the Residential CO application","amount":"$125.00"},{"label":"As-is Transfer of Title (vacant sale) with smoke detector inspection","amount":"$75.00"}]$j$::jsonb, $t$https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf$t$, $t$https://mapleshade.com/new-fire-official/$t$, $j$[{"url":"https://mapleshade.com/new-fire-official/","label":"Official source (mapleshade.com)"},{"url":"https://fireprevention31.org/forms-%26-applications","label":"Official source (fireprevention31.org)"},{"url":"https://fireprevention31.org/contact","label":"Official source (fireprevention31.org)"},{"url":"https://mapleshade.com/land-use-community-development/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/03/Transfer-of-Title-Form.pdf","label":"Official source (mapleshade.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf","label":"Official source (mapleshade.com)"}]$j$::jsonb, $t$The “Resale Smoke Alarm Application” has been replaced with the “Residential CO Form”.$t$, $t$a50c079d2f11e477c9ca78cb54ca351d4a9e1f76dca196bd9e5afc164001cef9$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0319.json$t$, true),
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Sale or Resale of Property$t$, $j$["Issued by: Borough of Audubon (requests handled by the Administrative Assistant to the Superintendent of Public Works; interior fire inspection by the Fire Marshal, exterior property inspection by the Borough)","Contact: Kristen Melvin, Administrative Assistant to the Superintendent of Public Works · 856-547-1240 option 3, or 856-547-0710 ext. 110 · k.melvin@audubonnj.com","Apply: Give at least 15 business days' notice before settlement; inspections and responses typically take 7 to 10 business days","How to apply: Only the seller or the seller's representative (attorney, agent or property manager) may request; buyers and buyers' agents cannot. Send the 2026 CO application (or an email with the seller name, property address, closing date and whether there is a sump pump) to Kristen Melvin at k.melvin@audubonnj.com. Pay two separate payments ($50 exterior and $25 fire) by check or money order payable to Borough of Audubon, or exact cash. No credit, debit or online payments. Payments can be mailed, brought in person, or left in the black vestibule lockbox marked Attention: CO. Call the Construction Office first ((856) 547-6312, n.bicking@audubonnj.com) to make sure all permits are closed.","Valid for: 90 days from the date of issuance","Two inspections must both pass: an interior fire inspection and an exterior property inspection","Sidewalks, walkways, driveways, driveway aprons, steps and pavers must be safe, free of cracks, raised or uneven surfaces, deterioration and trip hazards","Ramping a raised sidewalk joint is not an acceptable repair (grind the joint down or replace the block)","Smoke and CO detectors must be UL listed, have a 10-year sealed battery, and be no more than 10 years old","Hardwired smoke alarms cannot be replaced with battery units; hardwired units must be interconnected and working","Smoke detector on every level (basement, each floor, and an attic that is finished, used as living space or has ceiling fans) and in every bedroom","Working smoke and CO detector within 10 feet of all bedrooms (combination units allowed)","House numbers at least 4 inches tall, contrasting, visible from the street","No double-cylinder (keyed both sides) deadbolts on exit doors; exits must open from inside without a key","Sump pumps, roof drains and other discharges may not be connected to the sanitary sewer","All liens and property maintenance charges resolved and all construction permits closed before the CO is issued","Also: Open construction permits must be closed: Sellers must contact the Construction Office to make sure all permits are closed before applying: (856) 547-6312, n.bicking@audubonnj.com.","Also: Liens and property maintenance charges: All liens and outstanding property maintenance charges must be resolved before the CO is issued.","Also: Sump pump / drainage disclosure: The request must state whether there is a sump pump; sump pumps and roof drains may not discharge into the sanitary sewer."]$j$::jsonb, $j$[{"label":"Exterior property inspection","amount":"$50"},{"label":"Exterior inspection, per 2026 application form (exact cash, check or money order)","amount":"$50.00"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info$t$, $j$[{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/e9dda18d-4497-4c03-868c-72c15b7fdb3b","label":"Official source (audubonnj.com)"}]$j$::jsonb, $t$A Certificate of Occupancy (CO) is required for the sale or resale of all residential and non-residential properties in the Borough of Audubon, whether occupied or vacant.$t$, $t$b1732248f806050bbf36d671a5490c48e92354845ceec3cf6a639ae0cd99e4b9$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Audubon Fire Marshal's Office (Audubon Borough Fire Prevention) (town fire bureau)","Contact: Ernest F Busch, Fire Official (per NJ DCA fire directory) · 856-547-0710 ext. 117","Apply: Requested with the resale CO; give at least 15 business days' notice before settlement","How to apply: Requested together with the resale CO through Kristen Melvin (k.melvin@audubonnj.com, 856-547-1240 ext. 110). Pay the $25 fire fee as its own check, money order or exact cash, separate from the $50 exterior fee.","Fire official in the NJ state directory (town), updated n/a: Ernest F Busch · (856) 546-5399 · ebusch@haddonfield-nj.gov","Smoke and CO alarms must be UL listed with a 10-year sealed battery and no more than 10 years old","Hardwired smoke alarms may not be replaced with battery-only units and must be interconnected","Smoke alarm on every level including basement and a finished or used attic, plus one in every bedroom","Smoke and CO alarm within 10 feet of all bedrooms (combination units allowed)","House numbers at least 4 inches tall and visible from the street","No double-cylinder deadbolts on exit doors","Fire inspections are Thursday mornings only; someone must meet the Fire Marshal or provide a lockbox code","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Interior fire inspection (resale)","amount":"$25"},{"label":"Fire inspection, information sheet","amount":"$25"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info$t$, $j$[{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/683dc676-1b13-445c-9e63-e74ff15a5309","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$State law requires a fire inspection before any sale, and failure to comply may result in state fines.$t$, $t$acbc9bb9603568e34946a1f9346f59f341f3951cc927a58e8185137a831b81ba$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0403$t$, $t$Barrington Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Inspection on Residential Home Resales (resale CO)$t$, $j$["Issued by: Barrington Construction Department","Contact: Phil Azzari, Construction Official and Building Sub-Code Official · 856-547-0706 · constructionofficial@barringtonboro.com","Apply: Apply 14 or more business days before settlement for the lowest fee","How to apply: Download and fill out the Application and Checklist for Continued Certificate of Inspection on Residential Home Resales and submit it to the Construction Department at the Borough Municipal Building, 229 Trenton Avenue (856-547-0706; Monday to Thursday 8:30 a.m. to 4:00 p.m., Friday 8:30 a.m. to 12:00 p.m.). Also call Public Works (Mike Ciocco, 856-547-2486) to schedule the sump pump inspection and the Regional Fire Prevention Alliance (856-547-0991) for the smoke and CO inspection.","House number visible from the street, at least 4 inches tall","Sidewalks safe, no raised or deteriorated concrete","Deteriorated asphalt driveway aprons must be replaced with concrete","Handrails on steps with 3 or more steps (both sides if over 30 inches above grade); spindles no more than 4 inches apart","Porches without perimeter railings must get railings","Peeling or chipping exterior paint scraped and repainted; unpainted surfaces painted","Broken window panes repaired","Open splices or improperly installed exterior electrical fixtures corrected","Gutters and downspouts connected and in place","Any other hazardous condition the inspector finds must be corrected","Separate sump pump inspection by the Superintendent of Public Works","Separate smoke and CO detector inspection by the Regional Fire Prevention Alliance (additional fee)","Also: Sump pump inspection: Performed by the Superintendent of Public Works; call Mike Ciocco at 856-547-2486. The Borough page says its fee is included in the $100 resale inspection."]$j$::jsonb, $j$[{"label":"Resale CO, request received 14+ business days before settlement","amount":"$100.00"},{"label":"Resale CO, request received 13 to 6 business days before settlement","amount":"$150.00"},{"label":"Resale CO, request received 5 business days or less before settlement","amount":"$200.00"},{"label":"Each re-inspection","amount":"$50.00"}]$j$::jsonb, $t$http://barringtonboro.com/wp-content/uploads/2026/05/CO-Application-1-fillable.pdf$t$, $t$https://barringtonboro.com/borough-services/construction/$t$, $j$[{"url":"https://barringtonboro.com/borough-services/construction/","label":"Official source (barringtonboro.com)"},{"url":"http://barringtonboro.com/wp-content/uploads/2026/05/CO-Application-1-fillable.pdf","label":"Official source (barringtonboro.com)"}]$j$::jsonb, $t$The Certificate of Inspection program for residential re-sales has resumed. The new CO inspection application form and explanations are now available here.$t$, $t$1e2989b5511701b7f8bdedaf3655ca59163204d0b917913904308fc1d176227b$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0403.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0403.json$t$, true),
  ($t$0403$t$, $t$Barrington Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Barrington) (town fire bureau)","Contact: Nick D'Alonzo, Fire Official (fireofficial@barringtonboro.com) · 856-547-0991 · firealliance@barringtonboro.com","Apply: Apply 14 or more business days before the change of occupant for the lowest fee; weekends, holidays and the settlement date do not count","How to apply: Fill out the Alliance smoke detector certification application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox at 205 Haines Avenue, Barrington. Include a check or money order payable to 'Regional Fire Prevention Alliance'. Fees are non-refundable. Walk-in office hours are Tuesday to Friday 8 a.m. to 2 p.m.; inspections are scheduled Monday to Friday 9 a.m. to 2 p.m.","Fire official in the NJ state directory (town), updated 9/7/2022: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; undated alarms must be replaced","Each level needs either a hardwired alarm or a 10-year sealed battery alarm; hardwired alarms must be interconnected","CO alarm within 10 feet of all sleeping areas if the home has a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Monitored low-voltage fire alarm systems must be tested by an alarm contractor before the inspection, with a copy of the certification for the inspector","House numbers: Arabic numerals at least 3 inches tall, contrasting, at least 60 inches above ground, visible from the street","Secondary power source label (wording like 'CAUTION MULTIPLE SOURCES OF POWER', not handwritten) within 18 inches of the main electrical panel and meter when the home has a generator, solar panels or battery storage","Person over 18 must meet the inspector at the start of the time block","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 14+ business days before change of occupant","amount":"$66.00"},{"label":"Smoke/CO certificate, 8 to 13 business days before change of occupant","amount":"$74.00"},{"label":"Smoke/CO certificate, 4 to 7 business days before change of occupant","amount":"$106.00"},{"label":"Smoke/CO certificate, 3 business days or less before change of occupant","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$http://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"http://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$1d042c5375bbfcd0e79f233fae99671c243de77fb9be7d5ea83610def4fd25dc$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0403.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0403.json$t$, true),
  ($t$0404$t$, $t$Bellmawr Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Resale or Change of Ownership)$t$, $j$["Issued by: Bellmawr Construction/Zoning/Code Enforcement Office","Contact: Greg Conti, Certificates of Occupancy, Housing & Rental (also Mike McDonough, Certificates of Occupancy, Housing & Rental… · 856-933-1286 · ConstructionOffice@Bellmawr.com","Apply: Must be obtained before settlement; the office calls to schedule the inspection once the application is approved (no number of days published; the code says inspection within five working days of the application)","How to apply: Fill out the Application for Certificate of Occupancy for Residential (check 'Single Family Dwelling RESALE') and bring or mail it (addressed 'Attn: Construction') to the Construction Office, 21 E. Browning Road, Bellmawr, with exact cash or a check payable to Borough of Bellmawr. All taxes, grass cuts, liens and open permits must be paid or closed before the application is accepted. The office calls to schedule the inspection once approved. Inspections are by lockbox or a 2 to 3 pm or 3 to 4 pm window. After passing, email to request the certificate or pick it up from the bin outside the Construction Office.","Valid for: 30 days from issuance","House number visible from the street, at least 4 inches tall","Steps without trip-hazard cracks; open wood risers closed so a 4 inch ball cannot pass","Cracked sidewalk or walkway blocks with a change in elevation must be replaced","Guardrails (36 inch minimum) where porches, landings or stairs are over 30 inches above grade; handrail on steps with 4 or more risers","Yard free of high grass, weeds, debris and bamboo (unless contained per Borough code)","Grading slopes away from the foundation; gutters, downspouts and splash blocks in place","Sump pump crock must have a pump, check valve, proper outlet, and discharge outside (never to the sanitary sewer)","No signs of pests; if found, a licensed pest control certification is needed","Bathroom window or exhaust fan; GFCI protection on existing bathroom, kitchen counter, garage and exterior outlets","Electrical covers, fixtures and panel secure and labeled; A/C disconnect at the outdoor unit","Bedroom windows open easily for escape; no double-keyed deadbolts","Water heater with proper relief valve and discharge pipe to 2 to 6 inches above the floor; no leaks","Heating system working","Smoke alarms on each floor including basement (10-year sealed battery); CO alarms near bedrooms if there is a gas or oil appliance","ABC fire extinguisher no larger than 10 lbs within 10 feet of the kitchen (form still lists it)","Work done without permits and open permits must be resolved","Also: Taxes, grass cutting charges and liens paid first: All charges (taxes, grass, liens, etc.) must be paid before the CO application is accepted, even if they would be paid at settlement. Call 856-933-1313.","Also: Open permits and vacant property fees: Any vacant property fees and open permits must be closed out before any certificate is issued."]$j$::jsonb, $j$[{"label":"Resale CO inspection (cash or check only)","amount":"$100"},{"label":"Second inspection","amount":"No charge"},{"label":"Third inspection (re-inspection)","amount":"$75"},{"label":"Fourth or later re-inspection, each","amount":"$100"}]$j$::jsonb, $t$https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF$t$, $t$https://www.bellmawr.com/172/Certificates-of-Occupancy$t$, $j$[{"url":"https://www.bellmawr.com/172/Certificates-of-Occupancy","label":"Official source (bellmawr.com)"},{"url":"https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF","label":"Official source (bellmawr.com)"},{"url":"https://ecode360.com/29125219","label":"Official source (ecode360.com)"},{"url":"https://www.bellmawr.com/DocumentCenter/View/141/Certificate-of-Occupancy-Checklist-For-Residential-Resales-and-Rentals-PDF","label":"Official source (bellmawr.com)"}]$j$::jsonb, $t$Must be obtained prior to settlement.$t$, $t$ad308312a9c769f9e839673e9416f2cb465b07e11c0613c18065351cee6a822e$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":4,"fee_bad":0,"fee_unchecked":5,"quotes":12,"q_ok":8,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0404.json$t$, true),
  ($t$0404$t$, $t$Bellmawr Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bellmawr Fire Department, Bureau of Fire Prevention (Fire Marshal's Office) (town fire bureau)","Contact: Rob Fowler, Fire Marshal · 856-933-1313 ext. 1239 · rfowler@bellmawr.com","Apply: Schedule at least 10 days ahead for the lowest fee","How to apply: Fill out page 1 of the Bureau of Fire Prevention Certification of Smoke Detector and Carbon Monoxide Alarm Compliance application and return it with a check or money order payable to Borough of Bellmawr (no refunds). Pay separately from the CO fee. Office: 21 E. Browning Road; Fire Marshal's Office 856-933-1313 ext. 1239.","Fire official in the NJ state directory (town), updated 5/26/2026: Robert T Fowler · (856) 933-1313 · rfowler@bellmawr.com","Smoke alarms must match the rules in effect when the house was built (hardwired and interconnected in newer homes); hardwired alarms cannot be replaced with battery units","Smoke alarms no more than 10 years from date of manufacture; 10-year sealed battery where battery alarms are used","Smoke alarm within 10 feet of every bedroom door; basement alarm within 10 feet of the stair opening","Alarms mounted with proper hardware; nails, tacks, tape or Velcro not accepted; 3 feet from fan blades and HVAC vents","CO alarm outside sleeping areas, no more than 10 feet from any bedroom","Monitored alarm systems in homes built 1977 or later must be kept working","Secondary power source label within 18 inches of the main electrical panel and meter (generator, solar panels, battery storage)","Fire extinguisher no longer required for the smoke/CO certificate as of February 2025 (per Fire Department form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, appointment scheduled at least 10 days ahead","amount":"$70.00"},{"label":"Smoke/CO certificate, scheduled less than 10 but more than 4 days ahead","amount":"$100.00"},{"label":"Smoke/CO certificate, scheduled less than 4 days ahead","amount":"$140.00"},{"label":"Reinspection","amount":"$50.00"},{"label":"No-show for appointment","amount":"$50.00"}]$j$::jsonb, $t$https://www.bellmawr.com/DocumentCenter/View/1562/Smoke-DetectorCarbon-Monoxcide-Alarm-Application-PDF$t$, $t$https://bellmawrfire.com/homepage/fire-marshals-office/$t$, $j$[{"url":"https://www.bellmawr.com/DocumentCenter/View/1562/Smoke-DetectorCarbon-Monoxcide-Alarm-Application-PDF","label":"Official source (bellmawr.com)"},{"url":"https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF","label":"Official source (bellmawr.com)"},{"url":"https://bellmawrfire.com/homepage/fire-marshals-office/","label":"Official source (bellmawrfire.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification of Smoke Detector & Carbon Monoxide Alarm Compliance$t$, $t$52f26be1a0ef881ebb70530709f3c108684828ab38982c2d6c078e802d0838fb$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":4,"fee_bad":0,"fee_unchecked":5,"quotes":12,"q_ok":8,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0404.json$t$, true),
  ($t$0405$t$, $t$Berlin Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Berlin Construction Department (Borough Housing Inspector under the code)","Contact: Al Hallworth, Construction Official / Building Inspector (Technical Assistant: Donna Plute) · 856-767-7777 ext. 316 · construction@berlinnj.org","How to apply: Fill out the Inspection Application for Certificate of Continued Occupancy (check 'House Sale') from the Borough Forms page and submit it to the Construction Department, 59 S. White Horse Pike, Berlin. The Tax Collector must certify that taxes are current and there are no liens. Inspection requests can be emailed to construction@berlinnj.org. Note that the Construction page itself still links an older (2015) version of the same application without fees; use the 2025 form from the Forms page and confirm the fee.","All utilities on for the inspection; lockbox code if vacant","Trash and debris cleared inside and out","Walkways level and free of trip hazards","4 inch contrasting house number visible from the street","Graspable handrail on steps with more than four risers; guardrails on both sides of open stairs","Windows and doors operable, no cracked or broken glass","No pest or rodent infestation","Egress window or door in every bedroom; no bedrooms in basements","Bathroom window or exhaust fan","Dryer vent hard piped to the outside","Water heater discharge pipe ending 2 to 6 inches above the floor","Mechanical equipment kept clear of combustible materials","Smoke detectors working on every level, under 10 years old, 10-year sealed battery if battery powered, hardwired units interconnected and not swapped for battery units; any fire alarm system tested by a certified technician with a copy of the report","CO detector within 10 feet of each bedroom","Wood and metal surfaces free of deterioration or rust; walls intact; gutters and downspouts clean and working","Pools, fences, garages and decks safe; pool gates self-closing and self-latching","Wood-burning fireplace or stove needs a certificate showing it is in good working order","Thumb-latch turn-style interior door locks","All open permits closed with final inspections; unpermitted work must be documented (UCC Bulletin 06-1) before the CCO is issued","Also: Tax Collector certification: The CCO application includes a Tax Collector sign-off that taxes are current and there are no liens.","Also: Open permits closed: All open permits must be closed with final passing inspections before a CCO is issued.","Also: Wood-burning fireplace or stove certificate: A certificate showing any wood-burning fireplace or stove is in good working order is needed for the CCO."]$j$::jsonb, $j$[{"label":"Initial CCO inspection (application form)","amount":"$100"},{"label":"Re-inspection (application form)","amount":"$50"},{"label":"Initial inspection under Borough Code 256-25 as amended by Ord. 2025-12 (includes the CO or CCO and initial registration)","amount":"$200"}]$j$::jsonb, $t$https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Application.pdf$t$, $t$https://www.berlinnj.org/construction/$t$, $j$[{"url":"https://ecode360.com/26834143","label":"Official source (ecode360.com)"},{"url":"https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Application.pdf","label":"Official source (berlinnj.org)"},{"url":"https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Inspection-Checklist.pdf","label":"Official source (berlinnj.org)"},{"url":"https://www.berlinnj.org/construction/","label":"Official source (berlinnj.org)"},{"url":"https://berlinnj.org/berlinnj/AGENDA%20%202020-07-09.pdf","label":"Official source (berlinnj.org)"}]$j$::jsonb, $t$No person shall occupy a dwelling or dwelling unit as an owner, residential tenant or lessee unless the owner or the owner's agent shall have first obtained a certificate of occupancy or certificate of continued occupancy issued by the Borough Housing Inspector for the specific dwelling or dwelling unit.$t$, $t$fe2ab3640da912cefa374331cdcf9d8c5cdc7c88d38d392de8bb7d3df9a3b862$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":11,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0405.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0405.json$t$, true),
  ($t$0405$t$, $t$Berlin Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Berlin Borough Bureau of Fire Prevention (town fire bureau)","Contact: William Behnke, Fire Official (inspectors Joseph Cornforth and Dennis Rosenbaum) · 856-767-7777 ext. 308 · fm211@berlinnj.org","Apply: Allow two to three weeks before settlement; more than 10 business days for the lowest fee","How to apply: Fill out the Application for Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance and mail it with a check payable to 'Borough of Berlin' to Berlin Bureau of Fire Prevention, PO Box 226, Berlin, NJ 08009. The property must be ready for inspection. Questions: 856-767-6839.","Fire official in the NJ state directory, updated 5/19/2026: William Behnke · (856) 767-7777 · fm211@berlinnj.org","Battery smoke detectors must be 10-year sealed battery units (Bureau notice, 'Effective Immediately', July 2026)","Smoke alarms on each level and outside each separate sleeping area","Hardwired smoke alarms from original construction or rehabilitation may not be replaced with battery alarms","CO alarms in the immediate vicinity of the sleeping areas if the home has a fuel-burning device or attached garage","If the home has a monitored alarm system, notify the alarm company before the test and have the codes available at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSDCMAC, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"CSDCMAC, request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"CSDCMAC, request received fewer than 4 business days before change of occupant","amount":"$161.00"},{"label":"Additional fee if more than two visits are needed","amount":"$45.00"}]$j$::jsonb, $t$https://www.berlinnj.org/CSDCMAC%20app.pdf$t$, $t$https://www.berlinnj.org/bureau-of-fire-prevention/$t$, $j$[{"url":"https://www.berlinnj.org/CSDCMAC%20app.pdf","label":"Official source (berlinnj.org)"},{"url":"https://ecode360.com/8947329","label":"Official source (ecode360.com)"},{"url":"https://www.berlinnj.org/wp-content/uploads/2026/07/Battery-Smoke-Detector.pdf","label":"Official source (berlinnj.org)"},{"url":"https://www.berlinnj.org/bureau-of-fire-prevention/","label":"Official source (berlinnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Please try to allow a two to three week notice prior to settlement.$t$, $t$1e40397fe08dd00d40160a71e1ea941665a74b061c43ea0324b85c5bebe41545$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":11,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0405.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0405.json$t$, true),
  ($t$0407$t$, $t$Brooklawn Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy / Housing Inspection (Residential Dwelling Resale)$t$, $j$["Issued by: Borough of Brooklawn Construction/Zoning/Code Enforcement (Construction Code Official)","Contact: Melissa Perry, Construction Secretary (schedules all inspections); Construction Official: Mark Laggy · 856-456-0750 ext. 105 · mperry@brooklawn-nj.com","Apply: Application and fee must be received before an inspection is scheduled. Inspections are by appointment on Tuesday and Thursday, 10:00 am to 12:00 pm. The Borough code says the inspection is made within 5 working days of the written application.","How to apply: Fill out the Application for Continued Certificate of Occupancy/Housing Inspection (check 'Residential Dwelling RESALE') and bring or mail it with the fee (cash or check payable to Borough of Brooklawn; mail to 'Attn: Construction') to 301 Christiana St., Brooklawn, NJ 08030. Then call the office to schedule the inspection. The report can be mailed, picked up or emailed.","Inspection of the dwelling by the Construction Code Official or his representative for fitness for habitation and compliance with Borough ordinances (Housing Standards, Chapter 98)","Smoke detector within 10 feet of each sleeping area (Borough code), plus the state smoke and carbon monoxide alarm rules checked before any certificate is issued","Exterior housing code and exterior property area inspection on the sale of residential property (Chapter 114); repairs due within 30 days of notice","Inspection checklist is said to be attached to the application but is not posted online","Also: Exterior inspection on sale: Borough code Section 114-3 requires an exterior housing code and exterior property area inspection on the sale or resale of residential property, with repairs within 30 days of notice. The code lists a $30 fee paid once to the Administrative Office of Code Enforcement; it is not clear whether this is now part of the $100.00 resale CO.","Also: Water final reading: The CO application includes a water final reading request: $25.00, by check payable to Borough of Brooklawn, cash or money order. The form adds 'If settlement date is within 3 days from the date of application, the fee is $100.00'; it does not say whether that applies to the water reading or to the CO."]$j$::jsonb, $j$[{"label":"Residential dwelling resale CO","amount":"$100.00"},{"label":"CO re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://brooklawn-nj.com/wp-content/uploads/2023/07/CO-APP000.pdf$t$, $t$https://brooklawn-nj.com/departments/construction/$t$, $j$[{"url":"https://ecode360.com/9408563","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9408696","label":"Official source (ecode360.com)"},{"url":"https://brooklawn-nj.com/wp-content/uploads/2023/07/CO-APP000.pdf","label":"Official source (brooklawn-nj.com)"},{"url":"https://brooklawn-nj.com/frequently-used-forms","label":"Official source (brooklawn-nj.com)"},{"url":"https://brooklawn-nj.com/departments/construction/","label":"Official source (brooklawn-nj.com)"}]$j$::jsonb, $t$No owner, agent, broker or person shall sell, rent or lease or allow any person or persons to occupy or live in, as an owner, tenant or otherwise, any dwelling unit or apartment unless a certificate of occupancy certifying that the dwelling unit or apartment is fit for human habitation and that the dwelling unit or apartment is in compliance with all other ordinances of the Borough of Brooklawn shall have first been obtained from the Construction Code Official or his representative.$t$, $t$6c272a23b02f26c820cef1fdd5af021880df227474b63513407513a51a8c97f8$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":4,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0407.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0407.json$t$, true),
  ($t$0407$t$, $t$Brooklawn Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Brooklawn Construction Office (smoke detector compliance listed under the Borough construction office; fire code agency is the Brooklawn Bureau of Fire Prevention) (town fire bureau)","Contact: Timothy O'Donnell, Fire Official (NJ DCA fire directory) · 856-456-0750","How to apply: No separate smoke/CO certificate form or fee is posted. The state fire directory lists smoke detector compliance under the Brooklawn Borough construction office at 301 Christiana St., (856) 456-0750, and the Borough code says that where a municipal CO inspection exists, the CO is not issued until the home meets the smoke and CO alarm rules. Ask the construction office whether the resale CO inspection covers the smoke/CO certificate or whether a separate application and fee are needed.","Fire official in the NJ state directory, updated 3/19/2026: Timothy O'Donnell · (856) 456-0750","Smoke and carbon monoxide alarms meeting N.J.A.C. 5:70-4.19 for any 1 or 2 family home being sold (Borough code Section 84-10)","Carbon monoxide alarm meeting UL 2034 unless the home has no fuel-burning appliance and no attached garage","Borough housing code: at least one smoke detector within 10 feet of each sleeping area","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://brooklawn-nj.com/departments/construction/$t$, $j$[{"url":"https://ecode360.com/9408194","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9408180","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any Use Group R-3 or R-4 structure is sold, leased or otherwise made subject to a change or occupancy for residential purposes, the owner shall obtain a certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC), evidencing compliance with N.J.A.C. 5:70-4.19, from the appropriate enforcing agency.$t$, $t$02e1d27f07fdcff34934ef0d315018111ef8a73a247ed20e55b7cf460baa8623$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":4,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0407.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0407.json$t$, true),
  ($t$0408$t$, $t$Camden City$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Camden Resale Occupancy Certificate (C.R.O.C.); formerly Certificate of Continued Occupancy (C.C.O.)$t$, $j$["Issued by: City of Camden Construction & Building Bureau (Department of Code Enforcement)","Contact: James Rizzo, Construction Official · 856-757-7032 · JaRizzo@camdennj.gov","Apply: Zoning approval must be obtained first; no set number of days published","How to apply: First apply for a zoning permit (Zoning, City Hall Room 224, 856-757-7214). After zoning approval, submit the application to the Building Bureau, City Hall Room 403, 520 Market Street (856-757-7032). The seller is responsible for applying; the buyer may apply as the seller's agent with written permission, and the certificate is issued to the buyer. Building Bureau visits are by appointment only (call the day before) and permit applications and inspection requests go by email. The posted form is still the 2022 CCO application; no separate C.R.O.C. form was found.","Valid for: Application is good for 6 months","Zoning permit and zoning approval before the application is accepted","Building, electrical, plumbing and fire inspections by the Building Bureau","All open building permits must be closed before the inspection","General inspection of the visible parts of the building for Uniform Construction Code violations","Separate smoke/CO certificate from the Fire Marshal (the $200 fee does not include the fire safety fee)","Also: Zoning approval first: A zoning permit and approval are required before the Building Bureau accepts the CCO/C.R.O.C. application. Zoning: City Hall Room 224, 856-757-7214.","Also: Open permits closed: All existing open building permits must be closed out before the CCO inspection; no certificate is issued while permits are open."]$j$::jsonb, $j$[{"label":"C.R.O.C. application","amount":"$200.00"},{"label":"Name change on the certificate","amount":"$37.00"},{"label":"Penalty if the buyer closes without the certificate (up to)","amount":"$2,000.00"}]$j$::jsonb, $t$https://www.camdennj.gov/wp-content/uploads/2022/05/BB-CCO-App.pdf$t$, $t$https://www.camdennj.gov/construction-building-bureau/$t$, $j$[{"url":"https://www.camdennj.gov/faq-items/what-is-a-c-r-o-c/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/building-bureau-faqs/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/construction-building-bureau/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/wp-content/uploads/2022/05/BB-CCO-App.pdf","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/wp-content/uploads/2026/09/Construction-Employees-v2.pdf","label":"Official source (camdennj.gov)"},{"url":"https://ecode360.com/28217842","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The City of Camden requires that a Camden Resale Occupancy Certificate shall be applied for and issued prior to the sale or conveyance of any property within the city.$t$, $t$bd4a92043b65d8995a01b9e65302eac42362eaead180ea6c78c2bb244cc967e4$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":7,"fee_bad":0,"fee_unchecked":1,"quotes":17,"q_ok":13,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0408.json$t$, true),
  ($t$0408$t$, $t$Camden City$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Camden Fire Department, Office of the Fire Marshal (town fire bureau)","Contact: Joseph Tull, Chief Fire Marshal (Fire Official); resale requests go to Raymond Barker · 856-757-7531 · RaBarker@camdennj.gov","Apply: Submit the request 3 to 4 weeks before settlement; 8 or more calendar days ahead for the lowest fee. Certificates are valid for 90 days.","How to apply: Fill out the Residential Inspection Request Form and email it to Raymond Barker (RaBarker@camdennj.gov) or call 856-757-7531. Pay by check or money order payable to 'Uniform Fire Safety Act' (UFSA) before the inspection, or mail it in advance to Camden Fire Department, Office of the Fire Marshal, 4 N. 3rd Street, Camden, NJ 08102. Cash is not accepted. Inspections are between 9:00 am and 3:00 pm.","Fire official in the NJ state directory, updated 5/22/2026: Joseph Tull, Sr. · (856) 757-7531 · JoTull@camdennj.gov","10-year sealed battery smoke alarm on every level, or hardwired where required; hardwired alarms cannot be replaced with battery units","Smoke alarm on the ceiling in every bedroom","Basement alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarm within 10 feet of all bedroom doors","Hardwired smoke alarms and CO alarms must be less than 10 years old and working","CO alarm in the hallway within 10 feet of all bedrooms; not in switched outlets or outlets at floor molding","Fire extinguisher within 10 feet of the kitchen in the path of exit, mounted on a bracket, minimum rating 2A-10B:C, under 10 pounds (form still lists it)","House numbers at least 4 inches, contrasting, fixed to the house and visible from the street (numbers on a light post or mailbox not accepted)","Monitored low-voltage fire alarm systems must be tested by an alarm contractor, with the certification given to the inspector","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 8 or more calendar days before settlement","amount":"$64.00"},{"label":"Request received with less notice (published as 'seven (7) calendar days or more')","amount":"$115.00"},{"label":"Request received 3 calendar days or less before settlement","amount":"$162.00"},{"label":"Re-inspection","amount":"$35.00"},{"label":"Senior discount (sellers 62 and over, off the first inspection fee, proof of age required)","amount":"$30.00"}]$j$::jsonb, $t$https://www.camdennj.gov/wp-content/uploads/2025/07/New-Residitial-request-from-2025V2.pdf$t$, $t$https://www.camdennj.gov/fire-marshal/$t$, $j$[{"url":"https://www.camdennj.gov/wp-content/uploads/2024/08/Residential-Resale-Requirements.pdf","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/wp-content/uploads/2025/07/New-Residitial-request-from-2025V2.pdf","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/fire-marshal/","label":"Official source (camdennj.gov)"},{"url":"https://ecode360.com/28217020","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Residential Resale Requirements for One & Two Family Dwellings$t$, $t$ea7dcd52aa0aa6013bff274d0a8011f3115d147cb1b41b5faaf4be5c2a76f7cf$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":7,"fee_bad":0,"fee_unchecked":1,"quotes":17,"q_ok":13,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0408.json$t$, true),
  ($t$0409$t$, $t$Cherry Hill Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Residential Resale Inspection$t$, $j$["Issued by: Cherry Hill Township Community Development, Property Maintenance Department","Contact: 856-834-3364","Apply: No minimum lead time published. Inspections occur within 7 business days of receipt of application and fee.","How to apply: Apply online (the office approves first, then SDL Portal emails a payment request), or download the paper application and mail it or drop it off with a check or money order payable to Cherry Hill Township at 820 Mercer Street, Room 202, Cherry Hill, NJ 08002. The fee must be paid before the inspection. No refunds once paid.","Exterior-only inspection by the Property Maintenance Officer; no one needs to be home","Sidewalks, walkways, stairs and driveways in good repair, including sidewalk up to the curb line","Fences, detached garages and other accessory structures structurally sound","Dead or dying trees and hazardous limbs removed or trimmed","Weeds and grass under 10 inches","Property clean and sanitary","Grading and drainage: no ponding, no runoff onto neighbors","Sump pump and roof drain discharge not affecting neighbors or the roadway","Exhaust vents","No ground surface hazards such as holes or broken walks","No unregistered, uninsured or disassembled vehicles stored on the property","Also: Two separate inspections: The Property Maintenance CCO is in addition to the Cherry Hill Fire Department smoke alarm inspection."]$j$::jsonb, $j$[{"label":"CCO exterior inspection","amount":"$100"}]$j$::jsonb, $t$https://chnj.gov/1107/Online-CCO-Application$t$, $t$https://chnj.gov/893/Residential-Resale-Inspections$t$, $j$[{"url":"https://chnj.gov/893/Residential-Resale-Inspections","label":"Official source (chnj.gov)"},{"url":"https://chnj.gov/DocumentCenter/View/2486","label":"Official source (chnj.gov)"}]$j$::jsonb, $t$Cherry Hill homeowners are required to obtain a Certificate of Continued Occupancy prior to the resale of any single-family residential property in Cherry Hill.$t$, $t$5d2e10ed810a981966e9868d4f6bc44efa8133e5a1e23c2acb2d5aeebf8f6e3a$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":13,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0409.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0409.json$t$, true),
  ($t$0409$t$, $t$Cherry Hill Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cherry Hill Fire Department (Cherry Hill Fire District #13) (fire district)","Contact: Joseph V Cornforth, Fire Official (NJ DCA fire directory) · 856-429-7441 · sdi@chfd.org","Apply: Submit the request 3 to 4 weeks before the settlement date. Certificates are valid for 90 days.","How to apply: Submit the online Residential Inspection Request Form (not for re-inspections or rentals). Pay at the time of inspection by credit card, check or money order payable to CHFD; no cash. The certificate is issued at the inspection if the home passes and payment is received. Temporary certificates are not issued.","Fire official in the NJ state directory (fire district), updated 1/23/2026: Joseph V Cornforth · (856) 795-1340 · jcornforth@chfd.org","10-year sealed battery smoke alarm on every level, in every bedroom (on the ceiling), and within 10 feet of all bedroom doors; hardwired alarms cannot be swapped for battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","Smoke and CO alarms must be less than 10 years old and working","CO alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently on the house and visible from the street (mailbox or light post numbers not accepted)","Homes with a secondary power source (solar, generator, battery storage) need a permanent, non-handwritten label at the main electrical panel and the electric meter, such as 'Caution: Multiple Sources of Power'","Homes with a low-voltage fire alarm system must have it tested by an alarm contractor before the inspection and show the certification to the inspector","The township page says fire extinguishers are no longer required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 8 or more calendar days before settlement","amount":"$100.00"},{"label":"Request received 4 to 7 calendar days before settlement (sheet says 'seven (7) calendar days prior')","amount":"$115.00"},{"label":"Request received 3 calendar days or less before settlement","amount":"$162.00"},{"label":"Re-inspection","amount":"$35.00"},{"label":"Senior discount, sellers 62 and over (off the initial fee, proof of age required)","amount":"$30.00"}]$j$::jsonb, $t$https://chnj.gov/forms.aspx?FID=107$t$, $t$https://chnj.gov/232/Smoke-Carbon-Monoxide-Alarm-Compliance$t$, $j$[{"url":"https://chnj.gov/232/Smoke-Carbon-Monoxide-Alarm-Compliance","label":"Official source (chnj.gov)"},{"url":"https://chnj.gov/DocumentCenter/View/400/Residential-Resale-Inspection-Requirements","label":"Official source (chnj.gov)"},{"url":"https://ecode360.com/34645946","label":"Official source (ecode360.com)"},{"url":"https://chnj.gov/ArchiveCenter/ViewFile/Item/2779","label":"Official source (chnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$When selling a one or two family home in Cherry Hill, you must obtain a Certificate of Smoke Alarm and Carbon Monoxide Detector Compliance CSACMAPFEC 5:70-2.3 (a) prior to the settlement.$t$, $t$53162018e471182e1a62d8a10b763bf731cdf82759fc13d9f736da881a2b3d29$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":13,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0409.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0409.json$t$, true),
  ($t$0411$t$, $t$Clementon Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) for a Residential Resale$t$, $j$["Issued by: Borough of Clementon Code Enforcement Office","Contact: Nick Sapio, Code Enforcement Officer/Zoning Officer · 856-783-0284 ext. 127 · CodeEnforcePnZ@clementon-nj.com","How to apply: Download the CCO Application for a Residential Resale (linked as 'RESALE CO INSPECTION FORM' on the Code Enforcement page), fill it out (seller, buyer, closing date, contacts) and submit it to Code Enforcement, Borough of Clementon, 101 Gibbsboro Road, Clementon, NJ 08021, with the fee (the form records a money order or check number).","House number at least 4 inches high, visible from the street","Steps and walkways without trip hazards; cracked sidewalk blocks with a height change replaced","Guardrails where a porch, landing or stairs is over 30 inches above grade; handrail on steps with 4 or more risers","Yard free of high grass, weeds, dead trees, debris and hazards","Gutters and downspouts attached and clear, with splash blocks or diverters","Basement/crawl space openings and exterior doors secure and weatherproof; sump pump discharge outside, not into the sanitary sewer","No signs of pests (otherwise a licensed pest control certification is needed)","Bathroom window or exhaust fan; GFI protection on existing bathroom, kitchen counter, garage and exterior outlets","Cover plates on all switches and outlets; electrical panel secure, labeled, no open breaker slots; A/C disconnect at the outdoor unit","Windows intact; bedroom windows open and close for emergency escape","Water heater relief valve with discharge pipe ending 2 to 6 inches above the floor; tight flue connections","No plumbing leaks; fixtures and toilets secure","Heating system working","Work done without permits will be cited; open permits must be closed out","Also: Open permits must be closed: Any permits without final inspections or a Certificate of Approval must be closed out; contact the borough beforehand to ask if the address has anything open. Work done without permits will be cited."]$j$::jsonb, $j$[{"label":"1 and 2 family house or condo ($60 / $120; form does not say which applies to which, likely $60 for one unit and $120 for two)","amount":"$60/$120"},{"label":"3 and 4 family house, per unit","amount":"$60 per unit"},{"label":"Reinspection","amount":"$30"}]$j$::jsonb, $t$https://clementon-nj.com/wp-content/uploads/2025/03/certificate_of_occupancy.pdf$t$, $t$https://clementon-nj.com/code-enforcement/$t$, $j$[{"url":"https://clementon-nj.com/code-enforcement/","label":"Official source (clementon-nj.com)"},{"url":"https://clementon-nj.com/wp-content/uploads/2021/04/RESALE-CO-INSPECTION-FORM.pdf","label":"Official source (clementon-nj.com)"},{"url":"https://clementon-nj.com/wp-content/uploads/2025/03/certificate_of_occupancy.pdf","label":"Official source (clementon-nj.com)"}]$j$::jsonb, $t$Certificate required for sales and rentals$t$, $t$94034231ed6d07e2ee9fdc8f90c1a4b88184a725f4f1deb39078914b2b095dc5$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":7,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0411.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0411.json$t$, true),
  ($t$0411$t$, $t$Clementon Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Clementon Bureau of Fire Safety (town fire bureau)","Contact: John Zuggi, Fire Marshal (Fire Inspector: Timothy Shannon, tshannon@clementon-nj.com) · 856-783-0284 ext. 123 · jzuggi@clementon-nj.com","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Download the Smoke Alarm, CO Alarm & Secondary Power Source Certificate Application from the Fire Safety page, fill it out (closing date, bedrooms, year built, lockbox code) and return it with the fee to the Bureau of Fire Safety at Borough Hall, 101 Gibbsboro Road, Clementon. Call ext. 123 with questions.","Fire official in the NJ state directory (town), updated 8/5/2026: John J Zuggi · (856) 783-0284 · jzuggi@clementon-nj.com","Working smoke alarm installed per NFPA 74 and N.J.A.C. 5:70-4.19, listed to ANSI/UL 217, following the Borough's requirement chart","All single-station smoke alarms must be 10-year sealed battery alarms (effective January 1, 2019); AC-powered alarms from original construction cannot be replaced with battery alarms","Working carbon monoxide alarm outside each separate sleeping area, in the immediate vicinity of the bedrooms","Homes with a secondary power source (generator, solar panels, battery storage) need a Secondary Power Source Identification Label within 18 inches of the main electrical panel and electric meter (ANSI Z535.4)","Visible address in numbers or letters at least 3 inches high, contrasting color, on the street side","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before change of occupant","amount":"$60"},{"label":"Request received 4 to 10 business days before","amount":"$100"},{"label":"Request received 2 to 4 business days before","amount":"$161"},{"label":"Same day of settlement and/or one day","amount":"$200"},{"label":"Re-inspection after a failed initial inspection","amount":"$35"}]$j$::jsonb, $t$https://clementon-nj.com/wp-content/uploads/2023/09/Fire-Safety.pdf$t$, $t$https://clementon-nj.com/fire-safety/$t$, $j$[{"url":"https://clementon-nj.com/fire-safety/","label":"Official source (clementon-nj.com)"},{"url":"https://clementon-nj.com/wp-content/uploads/2023/09/Fire-Safety.pdf","label":"Official source (clementon-nj.com)"},{"url":"https://ecode360.com/6913491","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$No owner may sell, lease or otherwise permit occupancy of a one- or two-family residence without a Certificate of Smoke Alarm, Carbon Monoxide Alarm and Secondary Power Source Labeling Compliance (CSACMASPSC).$t$, $t$c81034d8f5927c6e58956b32a91bd69f42530db2a82ac5a64d72e7e250eab47c$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":7,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0411.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0411.json$t$, true),
  ($t$0412$t$, $t$Collingswood Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (CO) Resale / Exterior Resale Certification (Exterior Housing Code Inspection, Borough Code Section 227-3)$t$, $j$["Issued by: Collingswood Fire Department, Office of Fire Prevention & Inspection Bureau","Contact: Geoffrey T. Joyce, Deputy Chief/Fire Official · 856-854-7447 x101 · fireprevention@collingswood.com","How to apply: Use the combined 'Residential Inspection for Sale of Property Application' (covers both the exterior resale certificate and the fire smoke/CO certificate). Print, complete and deliver it with a check or money order payable to 'Borough of Collingswood' to the Fire Prevention & Inspection Bureau, 434 Haddon Avenue, Collingswood NJ 08108. One check may cover both inspections. Call 856-854-7447 to schedule (inspections Tuesday, Wednesday or Thursday, AM or PM). Get the Construction Permit Affidavit and Zoning Official Affidavit in the packet signed.","Valid for: 6 months from the date of inspection, or one change of ownership, whichever comes first","Exterior only: sidewalks, walkways, curbing, driveways and aprons, exterior stairs and handrails, house numbers","Sidewalks and walkways free of trip hazards (1/2 inch or more height difference between blocks, or cracks 1/4 inch or wider); bad blocks replaced, not patched; Public Works permit needed","Curbs free of disintegration and cracks over 1/2 inch","Driveways in good condition, at least 9 by 18 feet; dirt, grass, gravel, stone or shell surfaces not allowed","Exterior stairs with more than 4 risers or over 30 inches high need handrails and guards","House numbers at least 3 1/2 inches high, readable from the street","Repairs must be finished within 30 days of notice; a shade tree permit is needed if trees are in the curb strip","No open construction permits and no outstanding zoning violations (signed affidavits from the Construction Office and Zoning Office)","Also: Construction Permit Affidavit: Construction Office must certify there are no open permits.","Also: Zoning Official Affidavit: Zoning Office must certify there are no outstanding zoning violations.","Also: Sidewalk/curb repair permit: Owner must get a Public Works permit before sidewalk or curb repairs; Shade Tree Commission permit if trees are in the curb strip. Public Works: 856-854-0533."]$j$::jsonb, $j$[{"label":"Exterior resale inspection","amount":"$ 50.00"},{"label":"Re-inspection (form says all re-inspections)","amount":"$50.00"},{"label":"Returned check processing fee","amount":"$20.00"}]$j$::jsonb, $t$https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130$t$, $t$https://www.collingswood.com/government/departments/property_maintenance_nuisance_cos.php$t$, $j$[{"url":"https://www.collingswood.com/government/departments/property_maintenance_nuisance_cos.php","label":"Official source (collingswood.com)"},{"url":"https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130","label":"Official source (collingswood.com)"},{"url":"https://ecode360.com/10016352","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$There are several types of Certificates of Occupancy (COs). This type is required at the time of resale of any property in the Borough of Collingswood.$t$, $t$f3dd80b2fd8fd383af2773099b4d1a188a3d78ef9c03919e071bdc2e9c0cc707$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":8,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0412.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0412.json$t$, true),
  ($t$0412$t$, $t$Collingswood Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Collingswood Fire Department, Office of Fire Prevention & Inspection Bureau (town fire bureau)","Contact: Geoffrey T. Joyce, Deputy Chief/Fire Official · 856-854-7447 · fireprevention@collingswood.com","Apply: Apply more than 10 days before the inspection appointment for the lower fee. Certificates are valid for one change of ownership or 6 months, whichever comes first.","How to apply: Same combined application as the exterior resale certificate. Submit with a check or money order payable to 'Borough of Collingswood' to 434 Haddon Avenue; fees are due at application. Call 856-854-7447 to schedule.","Fire official in the NJ state directory, updated 1/9/2026: Geoffrey T Joyce · (856) 854-7447 · gjoyce@collingswood.com","Working 10-year sealed battery smoke alarm in every bedroom and on every level (hardwired 110V alarms are exempt from the 10-year battery rule but must be tested to NFPA 72 with a test report at inspection)","Smoke alarms on the ceiling at least 4 inches from the wall, or on the wall 4 to 12 inches below the ceiling","CO alarm within 10 feet of each sleeping area","Homes with a secondary power source (generator, solar, battery storage) need a non-handwritten label within 18 inches of the main electrical panel and electric meter, such as 'CAUTION: MULTIPLE SOURCES OF POWER'","Fire extinguisher no longer required (removed February 2025 under P.L.2025, c.19)","A representative must be present to let the inspector in","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Interior smoke/CO certificate, application more than 10 days before the inspection appointment","amount":"$75.00"},{"label":"Interior smoke/CO certificate, application less than 10 days before the inspection appointment","amount":"$150.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130$t$, $t$https://www.collingswood.com/government/departments/fire.php$t$, $j$[{"url":"https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130","label":"Official source (collingswood.com)"},{"url":"https://www.collingswood.com/government/departments/fire.php","label":"Official source (collingswood.com)"},{"url":"https://ecode360.com/10015799","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for CSACMAPFEC & Exterior Resale Certification$t$, $t$3097cea4767f4cbc305ca289665315cc8f071ff24da4138087227736fbb842c9$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":8,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0412.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0412.json$t$, true),
  ($t$0413$t$, $t$Gibbsboro Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale or change of tenancy certificate$t$, $j$["Issued by: Gibbsboro Code Enforcement Office (Compliance Officer / Code Enforcement Officer)","Contact: Craig Fallstick, Code Enforcement Officer / Fire Official · 856-783-6655 ext. 151 · codeenforcement@gibbsborotownhall.com","Apply: The form says inspections require 15 days notice; the code says the inspection is made within 15 working days after the application and fee are received","How to apply: Download the Continuing Certificate of Occupancy (CCO) application from the Code Enforcement page or the Forms page, fill in seller, buyer and settlement date, sign, and turn it in with payment to Borough Hall, 49 Kirkwood Road, Gibbsboro, NJ 08026. Office hours and inspection times vary, so call or email the Code Enforcement Officer to schedule.","Inspection of yard (trash and debris), sidewalks, curbing and driveway","Roof, rain gutters and spouts, chimneys, exterior paint or stain","Windows, steps, stairs and handrails","Plumbing, heating, electrical and fireplaces","Smoke alarms, attic, basement or crawl space and foundation","Wells and septic systems where present; the Compliance Officer may require a certification for any item that cannot be inspected","Handicap items (listed on the form)","Outstanding building permits and zoning are checked on the application; repairs that need permits go through the Construction Code Official","Not inspected: termites, lead-based paint, appliances and grading","Also: Outstanding building permits and zoning: The CCO application has fields for outstanding building permits and zoning, which are reviewed as part of the resale certificate. Repairs that need permits go through the Construction Code Official (Section 132-4B)."]$j$::jsonb, $j$[{"label":"Initial inspection (within 10 business days)","amount":"$125.00"},{"label":"Initial inspection (within 5 business days)","amount":"$150.00"},{"label":"Initial inspection (within 2 business days)","amount":"$175.00"},{"label":"Second and later reinspections (first reinspection is free)","amount":"$50.00"}]$j$::jsonb, $t$https://gibbsborotownhall.com/wp-content/uploads/2023/06/CCO_APPLICATION_Residents_06212023.pdf$t$, $t$https://gibbsborotownhall.com/code-enforcement/$t$, $j$[{"url":"https://gibbsborotownhall.com/code-enforcement/","label":"Official source (gibbsborotownhall.com)"},{"url":"https://gibbsborotownhall.com/wp-content/uploads/2023/06/CCO_APPLICATION_Residents_06212023.pdf","label":"Official source (gibbsborotownhall.com)"},{"url":"https://ecode360.com/10092784","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A CCO is required prior to the sale of all commercial and residential properties and whenever there is a change in tenant.$t$, $t$99f12d74e3659d1934533269306b94f8a58e9c454b390f2ff1276bb652566931$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":8,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0413.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0413.json$t$, true),
  ($t$0413$t$, $t$Gibbsboro Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Gibbsboro Bureau of Fire Safety (Borough Fire Official) (town fire bureau)","Contact: Craig Fallstick, Fire Official · 856-783-6655 ext. 151 · fireofficial@gibbsborotownhall.com","Apply: 10 days advance notice needed to schedule; less than 10 days costs more. Cancel at least 48 hours ahead.","How to apply: Mail the application with a check or money order payable to 'Gibbsboro Bureau of Fire Safety' to 49 Kirkwood Rd, Gibbsboro, NJ 08026, or drop it in the lock box in front of the building. Payment must come with the application; no cash and no payment on site. The application must be signed by the seller or the seller's agent. Questions are best sent by email to the Fire Official.","Fire official in the NJ state directory (town), updated 7/22/2026: Craig C Fallstick Sr · (856) 783-6655 · fireofficial@gibbsborotownhall.com","Smoke alarms on every level, including the basement, and within 10 feet of bedrooms; all smoke alarms, including hardwired, must be under 10 years old","10-year sealed battery smoke alarms required; non-sealed battery alarms not accepted; hardwired alarms must be replaced with hardwired","CO alarm on each level with a sleeping area, near the bedrooms; the form says CO alarms must be under 5 years old","Portable fire extinguisher, at least 5 lb 2A:10BC and no larger than 10 lb 4A:60BC, charged, mounted in plain view within 10 feet of the kitchen (form still lists it)","Fire alarm systems must be put on test through the alarm company; owner must know the codes to silence and reset","Someone over 18 must be present at the inspection","If the change of occupancy does not happen within 6 months, a new application is required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"10 or more days notice","amount":"$45.00"},{"label":"4 to 10 days notice","amount":"$90.00"},{"label":"4 days or less notice","amount":"$161.00"},{"label":"Failure / re-inspection, each visit","amount":"$35.00"},{"label":"Missed appointment, late cancellation or entry denied","amount":"$15.00"}]$j$::jsonb, $t$https://gibbsborotownhall.com/wp-content/uploads/2023/06/Smoke_Residents_06212023.pdf$t$, $t$https://gibbsborotownhall.com/fire-official/$t$, $j$[{"url":"https://gibbsborotownhall.com/wp-content/uploads/2023/06/Smoke_Residents_06212023.pdf","label":"Official source (gibbsborotownhall.com)"},{"url":"https://gibbsborotownhall.com/fire-official/","label":"Official source (gibbsborotownhall.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Payment should be made to “Gibbsboro Bureau of Fire Safety” and must accompany this application.$t$, $t$3f6aeee97804740e61d8cd717e93115780a52fb23af20d3d671c764488d5354a$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":8,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0413.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0413.json$t$, true),
  ($t$0414$t$, $t$Gloucester City$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (City Code Section 55-13; formerly called the Residential Certificate of Occupancy)$t$, $j$["Issued by: Gloucester City Buildings and Housing Office (Housing Inspector / Code Enforcement Official)","Contact: William Gallagher, Director - Chief Housing Inspector & Zoning Official (as listed in April 2024) · 856-456-7689 · housing@cityofgloucester.org","How to apply: Apply to the Buildings and Housing Office, 700 Somerset Street, Gloucester City, NJ 08030 (856-456-7689, housing@cityofgloucester.org) with the City's certificate application, and get the warrant waiver from the Municipal Court at 313 Monmouth Street. The City website (cityofgloucester.org) is behind a bot check and could not be read this time, so the current application form and payment methods were not confirmed. A vacant property can instead be sold with a Certificate for Transfer of Property Title ($75, valid 90 days) if a Certificate of Inspection application is filed before it expires.","Valid for: Until the next new occupant or transfer of title; not transferable","Home must comply with the applicable provisions of the City code (Housing Code, Chapter 55)","Smoke detectors certified by the Fire Official: hard-wired interconnected battery backup or 10-year sealed battery smoke alarms on or near the ceiling of each level, and battery smoke detectors in each bedroom or sleeping area","Owner supplies the address, owner name, address and phone, and the name and age of each person who will occupy the home","Warrant waiver from the Gloucester City Municipal Court (313 Monmouth Street) showing no outstanding warrants for the buyer, owner, tenants and proposed occupants","Violations must be fixed and reinspected within 90 days of the first report (one extension to 120 days if asked for in time), or a new application and fee are needed","Also: Municipal Court warrant waiver: Get a warrant waiver from the Gloucester City Municipal Court, 313 Monmouth Street, for the buyer, owner, tenants and proposed occupants (City Code 55-13 D(4)).","Also: Vacant property sale option: A vacant structure can be transferred with a Certificate for Transfer of Property Title ($75, valid 90 days, one battery smoke detector per level inspected first), but a Certificate of Inspection application must be filed before it expires.","Also: Outstanding Housing Office fees: The City's 2019 application said that under Ordinance 019-2017 all fees owed to the Housing Office on the property, including vacant or abandoned property fees, must be paid before a certificate is issued. Not re-confirmed on a current City page."]$j$::jsonb, $j$[{"label":"Initial inspection and first reinspection, residential","amount":"$100"},{"label":"Second reinspection, residential","amount":"$15"},{"label":"Each later reinspection, residential","amount":"$50"},{"label":"Certificate for Transfer of Property Title (vacant property sale only; a Certificate of Inspection application must follow within 90 days)","amount":"$75"}]$j$::jsonb, null, $t$https://www.cityofgloucester.org/code-enforcement-housing-department$t$, $j$[{"url":"https://ecode360.com/35213294","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35213319","label":"Official source (ecode360.com)"},{"url":"https://web.archive.org/web/20240408172626/https://www.cityofgloucester.org/code-enforcement-housing-department","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$the owner of any premises or that owner's agent shall obtain a certificate of inspection from the Housing Inspector or Code Enforcement Official upon the occurrence of any one of the following events:$t$, $t$b73fa1af94ca9bf1bac676365e68748400aa7694f9594e4e2178ca40bb31b03d$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":4,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0414.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0414.json$t$, true),
  ($t$0414$t$, $t$Gloucester City$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Gloucester City Fire Department Bureau of Fire Prevention (Fire Official Patrick R. Hagan), certifying smoke detectors for the Housing Office's Certificate of Inspection; DCA lists 'Gloucester City… (town fire bureau)","Contact: Patrick R Hagan, Fire Official · 856-456-7689 · pat.hagan@gloucestercityfd.org","How to apply: The smoke detector check is tied to the Housing Office's Certificate of Inspection: City Code 55-13 C(1) says the certificate is issued once the Fire Official or other authorized staff certify the smoke detectors, and the DCA directory lists Gloucester City Housing, (856) 456-7689, as the smoke detector compliance contact. No separate smoke/CO application or fee was found. Fire Official: Patrick R. Hagan, (856) 456-2652.","Fire official in the NJ state directory, updated 5/22/2026: Patrick R Hagan · (856) 456-2652 · pat.hagan@gloucestercityfd.org","Hard-wired interconnected battery backup smoke detectors or 10-year sealed battery smoke alarms on or near the ceiling of each level","Battery smoke detectors in each bedroom or sleeping area","Carbon monoxide alarm rules were not found in the City code section; ask the Housing Office","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[{"url":"https://ecode360.com/35213294","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35212793","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$a certificate of occupancy shall be issued by the Housing Inspector or Code Enforcement Official upon the certification by the Fire Official, or other duly authorized personnel, of the satisfactory installation of hard-wired interconnected battery backup smoke detectors or 10-year sealed battery smoke alarms$t$, $t$20fbd32cc2600fed1a0bac01ed44098f2bdb0e6267507bf2ba88ac7d8380672e$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":4,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0414.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0414.json$t$, true),
  ($t$0415$t$, $t$Gloucester Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Gloucester Township. Confirm with the office if the buyer's lender or title company asks.","Contact: 856-374-3500","How to apply: Nothing to apply for from the Township for a resale of a home. The Township's Community Development and Planning page says a certificate of occupancy from the construction office is not required for re-sales and tells sellers to get the smoke detector certification from the local fire district (see fire certificate). The rental certificate of compliance (Chapter 59A) applies only when a rental unit changes tenants."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://glotwp.com/department/community-development-planning/$t$, $j$[{"url":"https://glotwp.com/department/community-development-planning/","label":"Official source (glotwp.com)"},{"url":"https://ecode360.com/42578344","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/42577522","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$For re-sales of homes in Gloucester Township, a certificate of occupancy from the construction office is not required. Please contact your local fire department to obtain the required smoke detector certification:$t$, $t$a8029b40afc73ba926ce460813ae14e06c41f8fadd93d754efc0d97d34e892d0$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":21,"fee_ok":17,"fee_bad":0,"fee_unchecked":4,"quotes":30,"q_ok":23,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0415.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0415.json$t$, true),
  ($t$0415$t$, $t$Gloucester Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District #1 (Glendora area): issued by Gloucester Township Fire District #1 Bureau of Fire Prevention (Glendora Fire Company) (fire district). Check the property's fire district in the 'Special Taxing Districts' block at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #1 (Glendora area) contact: Harry D. Woods, Fire Official · 856-939-1177 · gtfm81@comcast.net","Fire District #1 (Glendora area), apply: 10 or more business days before settlement for the lowest fee","Fire District #1 (Glendora area), how to apply: Download the District 1 smoke application (08-2025 version) from the district's forms page, and mail it with cash or check payable to GTFD1 to PO Box 38, Glendora, NJ 08029. Fees are based on business days.","Fire District #2 (Chews Landing area): issued by Gloucester Township Fire District #2 Bureau of Fire Prevention (Chews Landing Fire Department) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #2 (Chews Landing area) contact: Kenneth Young, Fire Official · 856-282-3370 ext. 124 · gtfm82@gtfd2.com","Fire District #2 (Chews Landing area), apply: 10 or more business days before settlement (not counting settlement day) for the lowest fee","Fire District #2 (Chews Landing area), how to apply: Download the application (Word file) from the Fire Prevention Bureau page, fill it in (include lockbox code if vacant), and submit it with exact cash or a check payable to GTFD#2 to 43 Somerdale Road, Blackwood, NJ 08012 (fax 856-545-7485, email gtfm82@gtfd2.com). Appointments are given as a two-hour window. Call the Fire Prevention Office to schedule a re-inspection after a failure.","Fire District #3 (Blenheim area): issued by NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (for Gloucester Township Fire District #3, Blenheim) (NJ DCA, state). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #3 (Blenheim area) contact: 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Fire District #3 (Blenheim area), apply: More than 10 business days before the change of occupant for the lowest fee","Fire District #3 (Blenheim area), how to apply: Apply online through the DCA Fire Safety portal ('Apply For Smoke Certification'). The applicant checks off each placement and operating requirement, pays by e-check or credit card before submitting, and the certificate is emailed once the fee is paid and any required inspections are done. A valid email address is required. Electric-heat homes with no CO requirement should email BFCE_CSDCMAC@dca.nj.gov.","Fire District #4 (Blackwood area): issued by Gloucester Township Fire District #4 Bureau of Fire Prevention (Blackwood Fire Company) (fire district). The property record on the Township's tax lookup shows 'FIRE DISTRICT=F04' under Special Taxing Districts (https://wipp.edmundsassoc.com/Wipp/?wippid=0415)","Fire District #4 (Blackwood area) contact: Brandon M. O'Connor, Captain, Fire Official · 856-227-7037 · fm84@gtfd4.org","Fire District #4 (Blackwood area), apply: 10 or more business days before settlement for the lowest fee","Fire District #4 (Blackwood area), how to apply: Download the Smoke Detector / CO Application (linked from the Bureau of Fire Prevention page), and send it with cash or check payable to GTFD4 to 14 West Central Avenue, Blackwood, NJ 08012. To schedule, call 856-227-7037 or email fm84@gtfd4.org with the property address, contact information and preferred dates. Office hours Monday to Thursday 8 am to 4 pm.","Fire District #5 (Lambs Terrace / Sicklerville area): issued by Gloucester Township Fire District #5 Bureau of Fire Prevention (Lambs Terrace Fire Company) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #5 (Lambs Terrace / Sicklerville area) contact: Steve Schwegel, Fire Official/UFD · 856-228-0678","Fire District #5 (Lambs Terrace / Sicklerville area), apply: 10 or more business days before settlement for the lowest fee","Fire District #5 (Lambs Terrace / Sicklerville area), how to apply: Download the Smoke Application (SmokeCOCertApp.pdf) from the district's Forms & Applications page and mail it with cash or check payable to GTFD5 to 1781 Sicklerville Rd., Sicklerville, NJ 08081 (fax 856-374-0424). The same page links an Inspection Checklist (April 2025) with alarm rules by year built.","Fire District #6 (Erial area): issued by Gloucester Township Fire District No. 6 Bureau of Fire Prevention (Erial) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #6 (Erial area) contact: James Gordon, Sr, Fire Official (per NJ DCA directory) · 856-435-0700 · Inspections@gtfd6.com","Fire District #6 (Erial area), apply: 10 or more business days before settlement for the lowest fee; affidavits are processed once a week","Fire District #6 (Erial area), how to apply: For a sale, the owner or agent completes and signs the district's CSACMAPFEC affidavit (self-certification in lieu of inspection under N.J.A.C. 5:70-2.3(b)) and emails it to Inspections@gtfd6.com or drops it off at 1946 Williamstown-Erial Road, Sicklerville (mailbox if no one is there). Pay by cash or check payable to GTFD6; no certificate until paid. Affidavits are processed once a week. Rentals with a new tenant are inspected in person. Certificate valid 6 months, not transferable.","Fire official in the NJ state directory (fire district), updated 6/25/2025: Brandon O'Connor · (856) 227-7731 · fm84@gtfd4.org","Fire official in the NJ state directory (NJ DCA, state), updated 2/9/2026: Louis Kilmer · (609) 633-6132","Fire official in the NJ state directory (fire district), updated 3/16/2026: Kenneth Young · (856) 282-3370 · gtfm82@gtfd2.com","Districts 1, 2, 4 and 5: CO alarms must be less than 7 years old","Districts 1, 4 and 5: smoke alarms older than 10 years not accepted; battery alarms must be 10-year sealed (hardwired exempt); hardwired alarms cannot be replaced with battery alarms. District 6: hardwired units more than 10 years old must be replaced","Basement smoke alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarms within 10 feet of all bedroom doors","House numbers at least 4 inches high, contrasting color, permanently on the house and visible from the street (mailbox or light post numbers not accepted)","Homes with a secondary power source (solar, generator, battery storage) need a non-handwritten 'CAUTION: MULTIPLE SOURCES OF POWER' label within 18 inches of the main electrical panel and the electric meter","District 5 checklist: alarm type follows the year the house was built (for example 1991 to present: hardwired interconnected alarms with battery backup on every level and in each bedroom); hardwired fire alarm systems need an NFPA 72 test report at the inspection","Current district forms do not list a fire extinguisher (District 6's 2026 affidavit title still says 'Portable Fire Extinguisher' but its checklist has no extinguisher item)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District #1 (Glendora area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #1 (Glendora area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #1 (Glendora area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #1 (Glendora area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #2 (Chews Landing area): 10 or more business days before settlement","amount":"$35.00"},{"label":"Fire District #2 (Chews Landing area): 5 to 9 business days before settlement","amount":"$70.00"},{"label":"Fire District #2 (Chews Landing area): 4 or fewer business days before settlement (done as manpower permits)","amount":"$125.00"},{"label":"Fire District #3 (Blenheim area): Request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Fire District #3 (Blenheim area): Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Fire District #3 (Blenheim area): Request received fewer than 4 business days before the change of occupant","amount":"$161.00"},{"label":"Fire District #4 (Blackwood area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #4 (Blackwood area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #4 (Blackwood area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #4 (Blackwood area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #6 (Erial area): 10 or more business days before settlement","amount":"$35.00"},{"label":"Fire District #6 (Erial area): 4 to 9 business days before settlement","amount":"$70.00"},{"label":"Fire District #6 (Erial area): Fewer than 4 business days before settlement","amount":"$125.00"}]$j$::jsonb, $t$https://img1.wsimg.com/blobby/go/3bf548b5-402d-4490-8fd3-def7b989165b/downloads/e04298d2-df83-4cf5-af43-ddc780efee15/Township%20Smoke%20Application%2008-2025.pdf?ver=1789009271453$t$, $t$https://glotwpnjfd1.gov/district-forms$t$, $j$[{"url":"https://glotwp.com/department/fire-departments/","label":"Official source (glotwp.com)"},{"url":"https://img1.wsimg.com/blobby/go/3bf548b5-402d-4490-8fd3-def7b989165b/downloads/e04298d2-df83-4cf5-af43-ddc780efee15/Township%20Smoke%20Application%2008-2025.pdf?ver=1789009271453","label":"Official source (img1.wsimg.com)"},{"url":"https://glotwpnjfd1.gov/fire-marshall","label":"Official source (glotwpnjfd1.gov)"},{"url":"https://glotwpnjfd1.gov/district-forms","label":"Official source (glotwpnjfd1.gov)"},{"url":"https://gtfd2.org/?page_id=4","label":"Official source (gtfd2.org)"},{"url":"https://gtfd2.org/wp-content/uploads/2025/04/Application-CO-Insp.docx","label":"Official source (gtfd2.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Township of Gloucester is served by six separate Boards of Fire Commissioners, known as Gloucester Township Fire District #1 through Gloucester Township Fire District #6$t$, $t$b8f18990534294a0cf44781188d7176cff77c8da5db396150da1066a85513c44$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":21,"fee_ok":17,"fee_bad":0,"fee_unchecked":4,"quotes":30,"q_ok":23,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0415.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0415.json$t$, true),
  ($t$0416$t$, $t$Haddon Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC) / Temporary Certificate of Compliance (TCOC), Residential Resale Inspection (Township Code Chapter 186)$t$, $j$["Issued by: Construction & Zoning Office / Code Official (Township Annex, 10 Reeve Ave.)","Contact: Ryan Sheppard, Resale Inspector (also Fire Marshal / Investigator) · 856-833-6265 · rsheppard@haddontwp.com","Apply: Application in and paid at least 14 business days before closing; inspections Mondays and Wednesdays 8 to 10 AM","How to apply: Download the Residential Resale / Tenant Change Inspection Application (PDF) or use the township's online GovPilot form (https://main.govpilot.com/web/public/474cdd15-dbc_Rental-Resale-Township-of-Haddon?uid=7071&ust=NJ&pu=1&id=0). Submit it with a check or money order payable to 'Township of Haddon' to the Annex Building, 10 Reeve Ave., at least 14 business days before closing. Questions: Ryan Sheppard, rsheppard@haddontwp.com.","Valid for: 6 months (if the sale does not happen within 6 months a new application, fee and inspection are required)","Interior and exterior inspection under the township Land Use code, International Property Maintenance Code and NJ fire code; includes the smoke/CO (CSDCMAC) check","House numbers: numerals only, at least 4 inches, contrasting color, on the house (not doors or mailboxes)","Smoke alarms on every level on the ceiling, at the base of basement stairs, within 10 feet of all bedrooms; no more than 10 years old; 10-year sealed battery where battery units are allowed; hardwired alarms cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedrooms, less than 10 years old","Thumb-turn locks on all exit doors; no keyed locks on the egress side","Gutters, downspouts with splash blocks, roof, soffit, fascia, siding and paint in good repair","Guardrails on porches, decks and landings over 30 inches; handrails on steps with 3 or more risers","Sidewalk, driveway and apron level with no trip hazards; replacement rather than patching","GFCI outlets trip; outlet, switch and junction box covers in place; electrical panel covered, no open spaces, circuits labeled","Faucets hot on left, cold on right, no leaks; sink strainers; stove anti-tip device","Sump pump discharges outside, not into the sanitary sewer; water meter installed and accessible","Metal dryer vent; proper water heater and furnace venting; water heater bonding; oil heat emergency shut-off switch with red label","Attached garage walls/ceiling next to living space drywalled and taped","Bathroom window or working exhaust fan; screens installed","Pool barrier 5 to 6 feet with self-closing, self-latching gate","All permitted work must have final inspections and a Certificate of Approval (heater, water heater, finished basement, roof, siding, deck, etc.)","Also: Open permits must be closed: Any work that needed a permit must have had one, with final inspections done and a Certificate of Approval issued.","Also: Water meter: Water meter must be installed, connected and accessible at inspection."]$j$::jsonb, $j$[{"label":"COC application more than 14 business days before change of ownership","amount":"$150"},{"label":"COC application more than 7 but less than 13 business days before","amount":"$175"},{"label":"COC application more than 4 but less than 6 business days before","amount":"$200"},{"label":"COC application less than 4 business days before","amount":"$225"},{"label":"COC application after the change of ownership","amount":"$250"},{"label":"Re-inspection (paid before re-inspection is scheduled)","amount":"$25.00"},{"label":"First re-inspection after a Temporary COC","amount":"$25"},{"label":"Second re-inspection after a Temporary COC","amount":"$50"},{"label":"Third re-inspection after a Temporary COC","amount":"$75"},{"label":"Fourth or later re-inspection after a Temporary COC, each","amount":"$100"}]$j$::jsonb, $t$https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf$t$, $t$https://www.haddontwp.com/departmets/construction-office/$t$, $j$[{"url":"https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf","label":"Official source (haddontwp.com)"},{"url":"https://www.haddontwp.com/departmets/construction-office/","label":"Official source (haddontwp.com)"},{"url":"https://ecode360.com/36013747","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36013771","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Residential Property Inspection MUST be completed and a COC or Temporary COC MUST be issued PRIOR to closing per Township of Haddon Municipal Code Chapter 186-6 Article 3B.$t$, $t$fe6b731ee24a19bbdd6e8e485004ba0792b45b9b32f2a94e304c85bf51ea0280$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0416.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0416.json$t$, true),
  ($t$0416$t$, $t$Haddon Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Township Bureau of Fire Prevention (Fire Marshal Office); the smoke/CO check is part of the township Resale COC inspection (town fire bureau)","Contact: William Behnke, Chief Fire Marshal / Official · 856-833-6276 · rsheppard@haddontwp.com","Apply: At least 14 business days before closing","How to apply: No separate smoke certificate application or fee was found. The Fire Marshal Office says it inspects all homes for sale for smoke alarms, CO alarms and fire extinguishers, and the township's Residential Resale / Tenant Change Inspection Application covers that (CSDCMAC) check together with the COC; see the the town certificate fees ($150 and up). Submit the application with payment to the Annex Building, 10 Reeve Ave., at least 14 business days before closing.","Fire official in the NJ state directory (town), updated 5/19/2026: William A Behnke · (856) 854-1176 · wbehnke@haddontwp.com","Smoke alarms on every level on the ceiling, at the base of basement stairs and within 10 feet of all bedrooms; no more than 10 years old; 10-year sealed battery where battery units are allowed; hardwired alarms cannot be replaced with battery alarms","CO alarms less than 10 years old, in the hallway within 10 feet of all bedrooms","Homes with a low-voltage fire alarm system must have it tested by a certified alarm contractor before the inspection and show the certificate","House numbers at least 4 inches, numerals only, contrasting, on the house (not doors or mailboxes)","The Fire Marshal page says sale inspections check fire extinguishers too, but the June 2026 resale form and checklist do not list one","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf$t$, $t$https://www.haddontwp.com/departmets/fire-marshall/$t$, $j$[{"url":"https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf","label":"Official source (haddontwp.com)"},{"url":"https://www.haddontwp.com/departmets/fire-marshall/","label":"Official source (haddontwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$I understand that any change of ownership/occupancy including storage of personal property may not occur, prior to successful inspection & possession of a (CSDCMAC) inspection.$t$, $t$4694df844d6ec31aa125570b26a5c40c17dd7e425483f853a800427104afe505$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0416.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0416.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale CO (made up of the Fire Marshal smoke detector certificate of compliance plus the sidewalk inspection certificate of compliance)$t$, $j$["Issued by: Borough of Haddonfield Construction and Zoning Office (Community Development), with the Bureau of Fire Prevention (Fire Marshals) and the Sidewalk Inspector","Contact: 856-429-4700 · SKrohn@haddonfield-nj.gov","Apply: Notify the Borough at least 30 days before transfer of title (or within 5 days of signing the sales contract, whichever is later) for the sidewalk inspection. Lower fees apply if applications are submitted more than 10 business days before settlement.","How to apply: Submit the Smoke Detector form, Sidewalk Inspection form and (if in the Historic District) the Historic District Disclosure form to the Construction and Zoning Office, Room 104, Borough Hall, 242 Kings Highway East, with the fees in cash or check payable to the Borough of Haddonfield. Staff check permit history first. Schedule the smoke inspection directly with the Fire Marshal. Sidewalk inspections happen Tuesdays and Thursdays without an appointment; results are emailed.","Valid for: 90 days","All construction permits must be inspected and closed before the CO is released","Sidewalks, driveway aprons and walkways in the public right-of-way free of trip hazards (no lifts, holes or height differences of 1/2 inch or more)","Sidewalk repairs completed and the Borough notified at least 7 days before title transfer, or money placed in escrow and repairs done within 30 days after closing","Smoke alarm on every level (10-year sealed battery if battery powered)","CO alarm outside the bedroom area","ABC portable fire extinguisher no larger than 10 lb, within 10 feet of the kitchen (form still lists it)","Street number at least 4 inches, contrasting and readable from the street","Historic District disclosure form if the home is in the Historic District","Also: Open construction permits must be closed: Staff check permit history; all permits must be inspected and closed before the Resale CO is released, and no smoke inspection is scheduled while permits are open.","Also: Sidewalk and driveway apron inspection: Required on every sale; repairs or escrow before closing.","Also: Historic District disclosure: Buyers must be notified if the property is in the Historic District (Ch. 135-60). No fee.","Also: Move-out/move-in trash pickup: Schedule with Public Works at 856-429-0183 before putting out excess trash."]$j$::jsonb, $j$[{"label":"Sidewalk inspection, settlement more than 10 business days away (includes first re-check after repairs)","amount":"$50"},{"label":"Sidewalk inspection, settlement less than 10 business days away","amount":"$75"},{"label":"Sidewalk re-inspection, each (beyond the first re-check)","amount":"$25.00"},{"label":"Sidewalk late notice fee, each failure to give timely notice","amount":"$25.00"},{"label":"Historic District Disclosure Form","amount":"no fee"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071$t$, $t$https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"}]$j$::jsonb, $t$Selling a Home in the Borough of Haddonfield Resale CO 1. Smoke Detector Form / Fire Marshall CO Inspection$t$, $t$51c32c109099b344dbe73a151541c972d82b2ff8ad74849c353b96dee7052b86$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Haddonfield Bureau of Fire Prevention (Office of the Fire Marshal) (town fire bureau)","Contact: Ernest Busch, Fire Official · 856-429-4308 ext. 504/505 · EBusch@haddonfield-nj.gov","Apply: Lowest fee if submitted more than 10 business days before settlement","How to apply: Submit the Sale and Rental of Residential Property Ordinance Compliance Application with payment (cash or check to the Borough of Haddonfield) at the Construction and Zoning Office, Room 104, Borough Hall. Then schedule directly with the Fire Marshal's Office; inspections are Tuesdays or Wednesdays, 9 a.m. to 1 p.m. If it passes, a copy of the approval is left on site.","Fire official in the NJ state directory (town), updated 5/18/2026: Ernest F Busch · (856) 429-4308 · ebusch@haddonfield-nj.gov","All single-station battery smoke alarms must be the 10-year sealed battery type; at least one smoke detector on each level","Hardwired (110-volt) smoke detectors maintained per manufacturer and the code in effect at installation","CO alarm in the bedroom area (not required if there is no fuel-burning device and no attached garage)","ABC-type portable fire extinguisher, no larger than 10 lb, in the kitchen area (form still lists it; Borough Code 114-8B(1)(d))","Street number at least 4 inches, contrasting, readable from the street","Form includes a check for a secondary power source","No inspection is scheduled until all open permits are closed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Submitted more than 10 business days before settlement","amount":"$56"},{"label":"Submitted 4 to 10 business days before settlement","amount":"$125"},{"label":"Submitted fewer than 4 business days before settlement","amount":"$201"},{"label":"First re-inspection","amount":"no additional charge"},{"label":"Each additional re-inspection (prepaid)","amount":"$25"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Resale%20Rental%20CO%20App%20-%20Smoke%20Detector%20Application%20Form%20-%20Updated%20Fees%20-%20May%202026.pdf?t=20260625102151298$t$, $t$https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Resale%20Rental%20CO%20App%20-%20Smoke%20Detector%20Application%20Form%20-%20Updated%20Fees%20-%20May%202026.pdf?t=20260625102151298","label":"Official source (haddonfieldnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/index.php","label":"Official source (haddonfieldnj.org)"}]$j$::jsonb, $t$The Borough of Haddonfield, Bureau of Fire Prevention is responsible for inspection of all one- and two-family dwelling units.$t$, $t$3343237af7f72e0364f632b3eba629020b759e897c8dfe134c3f0292a7f03a00$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0418$t$, $t$Haddon Heights Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) / Certificate of Compliance$t$, $j$["Issued by: Zoning Officer / Code Enforcement Officer (Zoning and Code Enforcement)","Contact: Brian Kelly, Zoning Official & Code Enforcement Officer · 856-546-2580 · zoning@haddonhts.com","Apply: No application can be filed without a settlement date. All fees must be paid before scheduling an inspection. The code says the certificate is issued (or the failures listed) within 10 business days after the written application.","How to apply: Fill out the CCO application (needs a settlement date) and return it with payment (check or cash) to Zoning and Code Enforcement, 514 W. Atlantic Avenue, Haddon Heights. The applicant is responsible for scheduling all inspections and re-inspections after fees are paid.","Inspection for conformance with the Borough Zoning and Property Maintenance Ordinances (Section 262-4B)","Additions, attic or basement apartments, finished basements, garages, sheds, pools, second kitchens and decks must have had permits or a variance","Exterior graded for drainage; sidewalks (to the curb line), walkways and driveways in good repair; weeds and plant growth kept down","Separate Fire Department smoke detector / CO inspection is also needed to close","Also: Permits for additions and finished spaces: The CCO inspection checks that additions, attic or basement apartments, finished basements, garages, sheds, pools, second kitchens and decks were built with permits or a variance (Section 262-4B(1))."]$j$::jsonb, $j$[{"label":"Application filing fee","amount":"$11.00"},{"label":"First inspection","amount":"$50.00"},{"label":"Second inspection","amount":"no charge"},{"label":"Third or later inspection, each","amount":"$25.00"}]$j$::jsonb, $t$https://www.haddonhts.com/DocumentCenter/View/3128/Certification-of-Continued-Occupancy-Application-CCO$t$, $t$https://www.haddonhts.com/1364/Certificate-of-Continued-Occupancy$t$, $j$[{"url":"https://www.haddonhts.com/1364/Certificate-of-Continued-Occupancy","label":"Official source (haddonhts.com)"},{"url":"https://www.haddonhts.com/DocumentCenter/View/3128/Certification-of-Continued-Occupancy-Application-CCO","label":"Official source (haddonhts.com)"},{"url":"https://ecode360.com/33976360","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Per Ordinance 2018:1453, no residential properties may change ownership or tenancy until a Certificate of Continued Occupancy (CCO) is issued by the Zoning Officer and a Smoke Detector/Carbon Monoxide Inspection is also required by the Fire Department.$t$, $t$8b9cee889a63606bdd9729562e52b59a3205020c93d3f5a22cf9c36b5d835cf9$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":4,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0418.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0418.json$t$, true),
  ($t$0418$t$, $t$Haddon Heights Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Heights Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Benjamin Zwaska, Fire Official (per NJ DCA directory) · 856-546-7135 ext. 81","Apply: Lowest fee with 8 or more days advance notice; schedule early","How to apply: Fill out the Request for Inspection form and email it to one of the fire inspectors, fax it to 856-546-5340, or bring it to the office at 608 Station Avenue. Checks payable to Borough of Haddon Heights.","Fire official in the NJ state directory, updated 7/22/2026: Benjamin Zwaska · (856) 546-7135 · bzwaska@haddonhts.com","One smoke detector on each level including basement and any attic reachable by stairs; each level of each unit in a two-family","Ceiling-mounted at least 4 inches from walls, at least 36 inches from cold air returns and bathroom doors, away from ceiling fans; wall-mounted 4 to 12 inches below ceiling","UL-approved CO detector in the vicinity of each sleeping area","House number visible from the street, Arabic numerals at least 3 inches","2-A:10-B:C extinguisher no more than 10 lbs, charged, in a conspicuous place no more than 10 feet from the kitchen, instructions visible (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"8 or more days advance notice","amount":"$75.00"},{"label":"4 to 7 days advance notice","amount":"$100.00"},{"label":"3 or fewer days advance notice","amount":"$140.00"},{"label":"Re-inspection","amount":"$35.00"},{"label":"Failure to keep appointment (Borough Code 233-7A(3))","amount":"$20"},{"label":"Senior discount, credited on the initial inspection (Borough Code 233-7A(3))","amount":"$30"}]$j$::jsonb, $t$https://www.haddonhts.com/DocumentCenter/View/3225/Request-for-Smoke-Detector-and-Carbon-Monoxide-Inspection-3207-KB?bidId=$t$, $t$https://www.haddonhts.com/1336/Fire-Prevention$t$, $j$[{"url":"https://www.haddonhts.com/1336/Fire-Prevention","label":"Official source (haddonhts.com)"},{"url":"https://www.haddonhts.com/DocumentCenter/View/3225/Request-for-Smoke-Detector-and-Carbon-Monoxide-Inspection-3207-KB?bidId=","label":"Official source (haddonhts.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/6580593","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/40314057","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$SELLING YOUR HOME? The Bureau of Fire Prevention also handles the Certificate of Smoke Detector and Carbon Monoxide Compliance (CSDCMAC). This inspection is required prior to selling your home.$t$, $t$e11ce1fdc36a6b27a33b24565849c99529cf549e13636e41d66aaa262a63fd05$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":4,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0418.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0418.json$t$, true),
  ($t$0419$t$, $t$Hi-Nella Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Hi-Nella Borough requires a resale certificate. Call the office before closing.","Contact: 856-784-6237 ext. 400 · clerkhinellaboro@comcast.net"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.hinellaboro.org/contact$t$, $j$[{"url":"https://www.hinellaboro.org/contact","label":"Official source (hinellaboro.org)"},{"url":"https://www.hinellaboro.org/forms-documents","label":"Official source (hinellaboro.org)"}]$j$::jsonb, $t$Construction DCA (609) 567-3653$t$, $t$b2cd13dec9cc9f3c4d3520aa44c726596a6c684d88ba3fbb3e2dbd46e001f8be$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0419.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0419.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0419$t$, $t$Hi-Nella Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Borough of Barrington Bureau of Fire Prevention) (town fire bureau)","Contact: Nick D'Alonzo, Fire Official (fire code questions: fireofficial@barringtonboro.com) · 856-547-0991 · firealliance@barringtonboro.com","Apply: Lowest fee with 14 or more business days notice before the change of occupant (weekends, holidays and the settlement date do not count). Certificates are valid for 6 months.","How to apply: Fill out the Alliance's certificate application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox or mail it to 205 Haines Avenue, Barrington, NJ 08007. A check or money order payable to 'Regional Fire Prevention Alliance' must go with the application. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 5/18/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; take them down and check the date, replace if undated","Smoke alarm type by build year: pre-1975 homes need 10-year sealed battery alarms on each level including the basement; newer homes need AC powered, interconnected alarms per the year-built chart (1991 and later: on each level and in each bedroom)","Smoke alarms on every level, outside sleeping areas, and at the bottom of basement stairwells","CO alarm outside of but within 10 feet of all sleeping areas if there is a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers: Arabic numerals at least 3 inches, contrasting, at least 60 inches above ground, visible from the street","Homes with a secondary power source (solar, generator, battery storage) need a printed label within 18 inches of the main panel and meter, like \"CAUTION MULTIPLE SOURCES OF POWER\"","Someone over 18 must meet the inspector at the start of the time block; all items must be done before the inspector arrives","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8 to 13 business days before","amount":"$74.00"},{"label":"Request received 4 to 7 business days before","amount":"$106.00"},{"label":"3 business days or less notice","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$eb8a936201d08b2cbdc8b7cddbaa17ee475a02fcfbee4abd03e32fd7b71a4082$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0419.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0419.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0420$t$, $t$Laurel Springs Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Property Compliance (CPC)$t$, $j$["Issued by: Borough of Laurel Springs Office of Property Maintenance and Fire Prevention (Property Maintenance Officer / public officer)","Contact: Dominic Krawchuk, Property Maintenance Officer · 856-784-0500 · dkrawchuk@laurelsprings-nj.com","Apply: Notify at least 10 days before the change in occupancy; higher fees for 4 to 9 days and 1 to 3 days notice","How to apply: Fill out the Certificate of Property Compliance form (and the Fire Safety Certificate form for a sale) and pay at Borough Hall, 723 West Atlantic Avenue, payable to the Borough of Laurel Springs. Inspectors are notified by email only after payment is received. Fees are non-refundable. The inspector leaves a copy at the property.","Valid for: 45 days from the date of inspection","No refuse, garbage, abandoned vehicles, or overgrown brush, weeds or trees","Sidewalks and driveways free of holes; no standing stormwater","Foundation, walls, chimney, roof shingles and gutters in good repair","Porches, landings, stairs, balconies and railings safe","No broken glass or doors; windows and doors working","Working smoke detectors and CO detector","Central heating, air conditioning, kitchen, baths and light fixtures in working order","No fire or electrical hazards","Basement and crawl space condition","Property tax, sewer and property code fee balances are checked by Borough staff","Also: Tax, sewer and code fee balances checked: Borough Hall staff record property tax, sewer utility fee and property code fee status on the CPC form.","Also: Lead-safe certificate question: The CPC form asks whether the owner has a valid lead-safe certificate."]$j$::jsonb, $j$[{"label":"CPC, home resale, 10+ days notice","amount":"$50"},{"label":"CPC, home resale, 4 to 9 days notice","amount":"$70"},{"label":"CPC, home resale, 1 to 3 days notice","amount":"$125"}]$j$::jsonb, $t$https://www.laurelsprings-nj.com/DocumentCenter/View/389/Certificate-of-Property-Compliance$t$, $t$https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance$t$, $j$[{"url":"https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/DocumentCenter/View/389/Certificate-of-Property-Compliance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://ecode360.com/12440450","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Whenever there shall occur a change in occupancy in any residential property, including one- and two-family homes and apartments, a new certificate of property compliance shall be required. A change in occupancy shall occur in an apartment by a change in tenant or by the execution of a new lease with a new tenant, and in all other dwelling units by sale or lease.$t$, $t$0bf25ef8ee113f31db48fe2d46f4818d1eb60dd8b088a6ceafb44e23226385fd$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0420.json$t$, true),
  ($t$0420$t$, $t$Laurel Springs Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Laurel Springs Office of Fire Prevention and Property Maintenance (Fire Marshal) (town fire bureau)","Contact: Kenneth J. Cheeseman, Fire Marshal · 856-784-0500 ext. 25 · kcheeseman@laurelsprings-nj.com","Apply: Ten days notice is required for all inspections","How to apply: Fill out the Fire Safety Certificate of Compliance form and pay at Borough Hall (payable to the Borough of Laurel Springs) together with the CPC. The Fire Marshal is notified by email after payment.","Fire official in the NJ state directory, updated 5/22/2026: Kenneth Cheeseman · (856) 784-0500 · kcheeseman@laurelsprings-nj.com","Working smoke alarms on every level including basement and within 10 feet of bedroom doors; type depends on build year (hardwired and interconnected for newer homes, in every bedroom for 1991/1992 and later)","Hardwired smoke detectors may not be replaced with battery units; interconnected detectors must be replaced with compatible ones","Basement detector within 10 feet of the stairway, not in the stairway","Two-family homes: detectors at each landing of common hallways and stairs","Do not place detectors within 5 feet of a kitchen, 3 feet of fans, bathroom doors or supply vents, or 1 foot of a light fixture; detectors must not be painted","Central-station monitored alarm systems must be certified by a licensed NJ Fire Protection Contractor before the Fire Marshal's inspection","CO alarm on each sleeping level, in the hallway near every bedroom door, if there is a fuel-burning appliance or attached garage","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Safety Inspection, home resale, 10+ days notice","amount":"$45"},{"label":"Fire Safety Inspection, home resale, 4 to 9 days notice","amount":"$90"},{"label":"Fire Safety Inspection, home resale, 1 to 3 days notice","amount":"$161"}]$j$::jsonb, $t$https://www.laurelsprings-nj.com/DocumentCenter/View/390/Fire-Safety-Certificate-of-Compliance-PDF$t$, $t$https://www.laurelsprings-nj.com/1359/Fire-Safety-Requirements-Smoke-Detectors$t$, $j$[{"url":"https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/1359/Fire-Safety-Requirements-Smoke-Detectors","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/DocumentCenter/View/390/Fire-Safety-Certificate-of-Compliance-PDF","label":"Official source (laurelsprings-nj.com)"},{"url":"https://ecode360.com/12439949","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In the case of the resale of a property, both a Certificate of Property Compliance and Fire Safety are required.$t$, $t$67454fdfa4b4c8e57230402e4c397de937b28b8d0afa33c50f3bdbe6d0ed12eb$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0420.json$t$, true),
  ($t$0421$t$, $t$Lawnside Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Resale / Rental)$t$, $j$["Issued by: Borough of Lawnside Construction Office (Construction Code Department)","Contact: Marian Hauser, Primary contact named on the Construction Office CO application · 856-573-6214 · m.hauser@lawnside.net","Apply: Allow 10 business days for the inspection to be completed","How to apply: Fill out the Certificate of Occupancy Application (circle Resale) and submit it to the Construction Office, 4 Dr. Martin Luther King Jr. Road, with $75 per unit in cash, check or money order. Choose pick up, fax or email for the certificate. Repairs must be done within 30 days of the first inspection or a new application is needed.","Working smoke alarm on each level and in every bedroom","CO alarm within 10 feet of sleeping areas","ABC extinguisher (2.5 lb) mounted within 10 feet of the cooking area (form still lists it)","Heater and roof certification from a NJ licensed contractor (resale only); a private home inspection or a new roof or heater under permit in the last 5 years is accepted instead","Heater/chimney connection secure; water heater relief valve pipe 2 to 6 inches from the floor","Sump pump may not discharge into the sewer line","Sidewalks and walkway to the house in good condition with no trip hazards","Graspable handrails on steps 24 inches or more above grade (both sides if 44 inches or wider); guardrails on decks and porches 24 inches or more above grade","GFCI outlets within 6 feet of sinks and along kitchen counters; all outlet and switch covers in place; no openings in the breaker panel","No water leaks; faucets working","Holes in walls and floors fixed; exposed wood painted inside and out","Trash and debris removed","House numbers visible from the street","All open construction permits completed and closed; no unresolved violation notices","Also: Open permits must be closed: All work under open construction permits must be completed and permits closed before the CO is issued.","Also: Heater and roof certification (resale only): From a NJ licensed contractor, or a private home inspection, unless a new roof or heater was installed under a UCC permit in the last 5 years."]$j$::jsonb, $j$[{"label":"CO inspection, per unit (includes initial inspection and one re-inspection)","amount":"$75.00"},{"label":"Additional re-inspection (after the included re-inspection, a missed re-inspection, or violations not fixed within 30 days)","amount":"$75.00"},{"label":"Fine for violations not corrected within 30 days, per day","amount":"$25"}]$j$::jsonb, $t$https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF$t$, $t$https://www.lawnside.net/1204/Construction-Department$t$, $j$[{"url":"https://ecode360.com/35982076","label":"Official source (ecode360.com)"},{"url":"https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF","label":"Official source (lawnside.net)"},{"url":"https://www.lawnside.net/1204/Construction-Department","label":"Official source (lawnside.net)"}]$j$::jsonb, $t$It shall be unlawful to use or permit the use of any structure or building or part of the structure or building that presently exists in the Borough of Lawnside or any structure or building that has had a change in ownership or a change in occupancy, if that portion of the structure has been leased or sold, until a certificate allowing the new occupancy and/or use shall have been applied for by the owner or the owner's agent and such certificate issued by the Construction Code Official.$t$, $t$07f34f2931403adf46d23634055bf8a891ec3cc68b49e4474f3dfa6cd8de5d07$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":13,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0421.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0421.json$t$, true),
  ($t$0421$t$, $t$Lawnside Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Borough of Barrington Bureau of Fire Prevention) (town fire bureau)","Contact: Nick D'Alonzo, Fire Official (fire code questions: fireofficial@barringtonboro.com) · 856-547-0991 · firealliance@barringtonboro.com","Apply: Lowest fee with 14 or more business days notice before the change of occupant (weekends, holidays and the settlement date do not count). The Alliance form says certificates are valid 6 months; Borough Code 70-6B(3) says 90 days.","How to apply: Fill out the Alliance's certificate application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox or mail it to 205 Haines Avenue, Barrington, NJ 08007. A check or money order payable to 'Regional Fire Prevention Alliance' must go with the application. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 5/19/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; take them down and check the date, replace if undated","Smoke alarm type by build year: pre-1975 homes need 10-year sealed battery alarms on each level including the basement; newer homes need AC powered, interconnected alarms per the year-built chart","Borough Code 70-6B(4): a working smoke detector and CO detector in each sleeping area, plus one outside each sleeping area within 10 feet","CO alarm outside of but within 10 feet of all sleeping areas if there is a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers: Arabic numerals at least 3 inches, contrasting, at least 60 inches above ground, visible from the street","Homes with a secondary power source (solar, generator, battery storage) need a printed label within 18 inches of the main panel and meter, like \"CAUTION MULTIPLE SOURCES OF POWER\"","Fire extinguisher (form still lists it on the June 2025 version posted by Lawnside, and Code 70-6B still names extinguisher inspections): fully charged 2-A:10-BC in or within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8 to 13 business days before","amount":"$74.00"},{"label":"Request received 4 to 7 business days before","amount":"$106.00"},{"label":"3 business days or less notice","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://ecode360.com/36320110","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35985317","label":"Official source (ecode360.com)"},{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF","label":"Official source (lawnside.net)"},{"url":"https://www.lawnside.net/DocumentCenter/View/464/Smoke-Alarm-Detector-Application-for-2025-PDF","label":"Official source (lawnside.net)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detector, carbon monoxide detector and portable fire extinguisher inspections, to be conducted on all one- and two-family residential dwellings for resale being sold in the Borough, shall be charged as follows:$t$, $t$41e88694532bb05faafecdcb095490556778823c230383b1fc33e95195629ca4$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":13,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0421.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0421.json$t$, true),
  ($t$0422$t$, $t$Lindenwold Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO); Certificate of Transfer of Title (CTT) for vacant or rehab properties$t$, $j$["Issued by: Borough of Lindenwold Construction Office / Code Enforcement (Housing Clerk)","Contact: Heather Protich, Office Manager, Code Enforcement / Housing (ext. 225); Housing Clerk at ext. 224 · 856-783-2121 ext. 224 · hprotich@lindenwold.net","Apply: Borough Code 105-13.1 says apply not less than 10 business days before the scheduled closing; the inspection is to happen within 5 days of the application. The fee is lower when the inspection is scheduled 10 or more business days out. For a vacant CTT, apply at least 10 days before settlement.","How to apply: Fill out the one-page CCO application and submit it to the Code Enforcement Office at 15 N. White Horse Pike with a check or money order payable to the Borough of Lindenwold. Fees are per unit and nonrefundable. The Borough calls the listed contact to schedule after the permit and zoning search is done. A failed inspection needs a new application and fee before reinspection. For vacant or rehab properties, file the CTT and the CCO at the same time.","Valid for: 90 days from issuance (Borough Code 105-13.1); may be extended up to another 90 days if the owner certifies in writing that nothing has changed","No open building or zoning permits (must be closed with fees paid)","No work done without a required construction or zoning permit","No unsafe structures or unsafe conditions","10-year sealed battery smoke alarm on every level and outside each sleeping area","CO alarm within 10 feet of sleeping areas","2A-10B:C fire extinguisher under 10 lbs, mounted within 10 ft of kitchen, tagged with current receipt (form still lists it)","House numbers at least 4 inches, contrasting, fixed to the house and visible from the street","Handrails on 3 or more risers; guardrails on porches/decks 30 inches or higher","GFCI within 6 ft of water; no bare-wire fixtures","Heat, appliances (anti-tip on range), hot and cold water and toilets working","Water heater relief valve discharge pipe 2 to 6 inches from floor","Bathroom window or exhaust fan","No holes, flaking paint or water stains on walls, ceilings, floors; no roof leaks","Yard free of trash, debris and junk vehicles; all code violations abated","Utilities on at time of inspection","Also: Open permits must be closed: No open building or zoning permits; must be fully satisfied with fees and inspections before the CCO is issued.","Also: Work without permits: Unpermitted work (commonly finished basements, water heaters, furnaces) must be permitted and inspected before the CCO is issued.","Also: Zoning check: The Borough runs a zoning approval and permit search before scheduling the CCO inspection."]$j$::jsonb, $j$[{"label":"CCO inspection, 1-2 units, scheduled over 10 days out (form: 10 or more business days), per unit","amount":"$75"},{"label":"CCO inspection, scheduled less than 10 days out (form: 4 to 10 business days), per unit","amount":"$100"},{"label":"Re-inspection, per unit","amount":"$50"},{"label":"Administration fee for changing inspection date or unit number more than once","amount":"$20"},{"label":"Certificate of Transfer of Title (vacant property), includes one re-inspection within 120 days","amount":"$125"}]$j$::jsonb, $t$https://www.lindenwoldnj.gov/DocumentCenter/View/140/Residential-Property-Sales---Inspection-Application--CCO-Certificate-of-Continued-Occupancy-PDF$t$, $t$https://www.lindenwoldnj.gov/178/Code-Enforcement-Housing$t$, $j$[{"url":"https://www.lindenwoldnj.gov/178/Code-Enforcement-Housing","label":"Official source (lindenwoldnj.gov)"},{"url":"https://www.lindenwoldnj.gov/DocumentCenter/View/140/Residential-Property-Sales---Inspection-Application--CCO-Certificate-of-Continued-Occupancy-PDF","label":"Official source (lindenwoldnj.gov)"},{"url":"https://www.lindenwoldnj.gov/DocumentCenter/View/141/Residential-Property-Sales---Inspection-Application--CTT-Certificate-of-Title-Transfer--for-Vacant-or-Rehab-Properties-PDF","label":"Official source (lindenwoldnj.gov)"},{"url":"https://ecode360.com/34828458","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$All sales of a property must file for a certificate of occupancy (C/O) inspection for smoke detectors, carbon monoxide detectors, fire extinguishers, and house numbers.$t$, $t$a178468da9f0f4df04a066cab88f430e187d783dbc8fe4bc2a5b6eb7a0c4e5b9$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0422.json$t$, true),
  ($t$0422$t$, $t$Lindenwold Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lindenwold Fire District No. 1, Bureau of Fire Prevention (fire district)","Contact: Timothy D Shannon, Fire Official (DCA directory); questions to firemarshal@lindenwoldfire.com · 856-346-0935 · firemarshal@lindenwoldfire.com","Apply: Submit request 3 to 4 weeks before settlement","How to apply: Submit the online Residential Inspection Request Form on lindenwoldfire.com. Pay at the time of inspection by check or money order (no cash). The certificate is issued at the inspection if the home passes and payment is received. No temporary certificates.","Fire official in the NJ state directory (fire district), updated 5/26/2026: Timothy D Shannon · (856) 346-0935 · tshannon@lindenwoldfire.com","10-year sealed battery smoke alarm on every level; hardwired alarms cannot be replaced with battery alarms","Basement alarm at bottom of stairwell on the ceiling, not between joists","Bedroom hallway smoke alarms within 10 feet of all bedroom doors","Smoke and CO alarms less than 10 years old and working","CO alarm in hallway within 10 feet of all bedrooms; not in switched outlets","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers at least 4 inches, contrasting, fixed to the house, visible from the street or 50 feet (Borough Ordinance No. 757)","Homes with a secondary power source (solar, generator, battery storage) need a permanent printed label at the main panel and meter, e.g. \"Caution: Multiple Sources of Power\"","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 8 or more calendar days before settlement","amount":"$45.00"},{"label":"Request received 7 calendar days before settlement","amount":"$90.00"},{"label":"Request received 3 calendar days or less before settlement","amount":"$161.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.lindenwoldfire.com/FormCenter/General-Forms-4/Residential-Inspection-Request-Form-46$t$, $t$https://www.lindenwoldfire.com/182/Smoke-Carbon-Monoxide-Alarm-Compliance-C$t$, $j$[{"url":"https://www.lindenwoldfire.com/182/Smoke-Carbon-Monoxide-Alarm-Compliance-C","label":"Official source (lindenwoldfire.com)"},{"url":"https://www.lindenwoldfire.com/DocumentCenter/View/198/Residential-Resale-Requirements---","label":"Official source (lindenwoldfire.com)"},{"url":"https://ecode360.com/50282089","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$When selling a one or two family home in Lindenwold, you must obtain a Certificate of Smoke Alarm and Carbon Monoxide Detector Compliance CSACMAPFEC 5:70-2.3 (a) prior to the settlement. Please submit your request for inspection 3 to 4 weeks prior to the settlement date.$t$, $t$86d551944f5796d9745ce99faaaa0e463261e2836b74f601b7e5df0637177659$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0422.json$t$, true),
  ($t$0423$t$, $t$Magnolia Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (Certificate of Change in Ownership / Change in Occupancy), Borough Code Chapter 112$t$, $j$["Issued by: Borough of Magnolia Construction Office (building inspector or housing inspector)","Contact: 856-783-1520","How to apply: Fill out the Certificate of Continued Occupancy Application (linked from the Borough's \"Certificate of Change in Occupancy\" page, with an inspection checklist) and turn it in to the Construction Office, 438 W. Evesham Ave, Magnolia, with the $75.00 fee. An inspector will contact you to schedule. The owner or the owner's agent must apply.","Home must meet the property maintenance standards the Borough adopted (BOCA National Property Maintenance Code, 1993) and all Borough ordinances","Hard-wired, interconnected smoke detectors with battery backup on or near the ceiling of each level","Battery smoke detectors in each bedroom or sleeping area","Smoke detectors must be certified by the fire official or other authorized person before the certificate is issued","Any repairs needed for the certificate are the current owner's responsibility, even if the problem was caused by a previous owner","Under Ordinance 12-2026 (adopted Sept 2, 2026) the owner stays responsible until the certificate is issued, no matter what the sale contract, settlement or escrow agreement says; each day of violation after notice is a separate offense"]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy inspection when a home is sold (Borough page; same as Code 15.112-11 \"Change of property ownership, Residential\")","amount":"$75.00"}]$j$::jsonb, null, $t$https://www.magnolia-nj.org/construction/page/certificate-change-occupancy$t$, $j$[{"url":"https://web.archive.org/web/20260111210243/https://www.magnolia-nj.org/construction/page/certificate-change-occupancy","label":"Official source (web.archive.org)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC_15.112-11FE","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/magnolia/ordinances/code_of_ordinances?nodeId=1442309","label":"Official source (library.municode.com)"},{"url":"https://web.archive.org/web/20260112020819/https://www.magnolia-nj.org/construction/page/inspections","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$Pursuant to Borough Code 17.270-31 Certificate of Occupancy Inspections are required whenever a home is being sold.$t$, $t$7acbd547a0275d7c6d08bd78739980941a618f36a38eba30cd4844abe9c1c731$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":5,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0423.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0423.json$t$, true),
  ($t$0423$t$, $t$Magnolia Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Magnolia Construction Office (smoke detector compliance) (town fire bureau)","Contact: 856-783-1520","Fire official in the NJ state directory (NJ DCA, state), updated 5/22/2026: Louis Kilmer · (609) 633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.magnolia-nj.org/construction/page/certificate-change-occupancy$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC","label":"Official source (library.municode.com)"}]$j$::jsonb, $t$LEAID: 0423-999 Magnolia Boro SMOKE DETECTOR COMPLIANCE Enf Auth. State ... Name: Magnolia Boro Constr Office ... Addr: 438 West Evesham Av ... Magnolia NJ 08049 ... Fire Official Louis Kilmer ... Phone (856) 783-1520 Phone$t$, $t$5acc9f2bcd48c55ab5d267af5db745038ddc36b7f908e504ed55595567a50752$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":5,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0423.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0423.json$t$, true),
  ($t$0424$t$, $t$Merchantville Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Inspection / Resale Certificate$t$, $j$["Issued by: Borough of Merchantville Code Enforcement (Office of Code Enforcement and Rental Housing Inspection)","Contact: Tom Connelly, Code Inspector (Property Maintenance Officer: Kevin Patti, kpatti@merchantvillenj.gov) · 609-413-0010 · codeenforcement@merchantvillenj.gov","How to apply: Complete the Resale Inspection Application (includes the smoke detector certificate application) and bring it to the Borough Clerk's office at 1 W. Maple Avenue to pay the fee. Code Enforcement then contacts the applicant to schedule the inspection.","Valid for: 6 months after passed inspection","House numbers visible from the street","Fences, decks, sheds and accessory structures must have proper permits","Sidewalks and driveways level and free of trip hazards","Smoke alarm on each level including basement; 10-year sealed lithium battery type","CO detector within 10 feet of sleeping areas (plug-in or battery OK)","2A:10BC fire extinguisher in a cabinet or on a hanger within 10 feet of the kitchen (form still lists it)","Handrail on stairs with more than 4 risers; guards on surfaces more than 30 inches above grade","Exterior surfaces painted or protected and in good repair","Yard free of excess weeds, rubbish and garbage","Accessory structures (garages, fences, walls) sound and in good repair","Pools clean; pools over 24 inches deep fenced at least 48 inches with self-closing, self-latching gates","Also: Permits for accessory structures: All fences, decks, sheds, and accessory structures must have proper permits."]$j$::jsonb, $j$[{"label":"Resale inspection","amount":"$50.00"},{"label":"Resale re-inspection","amount":"$10.00"},{"label":"Resale re-inspection under Borough Code 25-14 (first re-inspection no charge; this is the second and later)","amount":"$25"}]$j$::jsonb, $t$https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300$t$, $t$https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php$t$, $j$[{"url":"https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php","label":"Official source (merchantvillenj.gov)"},{"url":"https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300","label":"Official source (merchantvillenj.gov)"},{"url":"https://ecode360.com/47312219","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/34599243","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Before the sale of all residential properties, you are required to obtain a Resale Inspection, including smoke detector compliance. Please bring your completed application to the clerk's office with you to pay the required fee. The Applicant will be contacted to schedule an inspection.$t$, $t$52a03c43189c45ec07947a044ed6b35acf2cbe4b0ab84dc6c5cd6c6a9c511704$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0424.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0424.json$t$, true),
  ($t$0424$t$, $t$Merchantville Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Merchantville Code Enforcement (Certificate of Smoke Detector Compliance) (town fire bureau)","Contact: Kevin Patti, Fire Official and Property Maintenance Officer · 856-662-2474 ext. 310 · codeenforcement@merchantvillenj.gov","Apply: Fee is lowest if applied for more than 10 business days before settlement","How to apply: Fill out the Borough 'Application for Certificate of Smoke Detector Compliance' (page 3 of the resale packet) and submit it with the resale application at the Clerk's office with payment. The Code Enforcement Official schedules the inspection.","Fire official in the NJ state directory, updated 3/17/2026: Kevin Patti · (856) 662-0900 · kpatti@merchantvillenj.gov","Each smoke alarm must be a 10-year sealed lithium battery detector, on every level including basements","CO detector within 10 feet of sleeping areas","2A:10BC extinguisher in an approved cabinet or on a hanger within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before settlement","amount":"$35.00"},{"label":"Less than 10 days but more than 4 days","amount":"$70.00"},{"label":"4 business days or fewer","amount":"$125.00"},{"label":"Re-inspection, each","amount":"$10.00"}]$j$::jsonb, $t$https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300$t$, $t$https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php$t$, $j$[{"url":"https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300","label":"Official source (merchantvillenj.gov)"},{"url":"https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php","label":"Official source (merchantvillenj.gov)"},{"url":"https://ecode360.com/47312220","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/34642977","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$BOROUGH OF MERCHANTVILLE APPLICATION FOR CERTIFICATE OF SMOKE DETECTOR COMPLIANCE$t$, $t$9825fcac695fd1de3cf62c99808e83346d9e7d26bfd636893ff23c40607f810f$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0424.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0424.json$t$, true),
  ($t$0425$t$, $t$Mount Ephraim Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Occupancy (Certificate of Continued Occupancy)$t$, $j$["Issued by: Borough of Mount Ephraim Construction / Zoning / Code Enforcement Office (Enforcement Officer is the Construction Code Official or designee)","Contact: 856-931-1546 · tmartin@mountephraim-nj.com","Apply: Application and fee must be received before an inspection can be scheduled. Resale CO inspections are done on Tuesdays between 4:00 and 4:30 by appointment. Town code says the inspection is done within a reasonable time, not more than 20 days after a complete application.","How to apply: Complete the borough's Application for Certificate of Single Family Dwelling RESALE and submit it with the $120 fee (cash or check payable to 'Borough of Mount Ephraim'). If mailing, address it to 'Attn: Construction', 121 S. Black Horse Pike, Mount Ephraim, NJ 08059. After the office receives the form and payment, call to schedule the inspection (Tuesdays 4:00 to 4:30 by appointment). Separately, schedule the smoke/CO inspection with the Regional Fire Prevention Alliance before settlement. The form also offers a 'Change of ownership ONLY' certificate with no inspection, but no one can occupy the property until the full CO is issued.","Visible 911 house number, at least 4 inches tall, visible from the street","Sidewalks safe and free of hazards; no raised sidewalks or deteriorated concrete","Driveways and aprons: asphalt or macadam only for driveways; a deteriorated asphalt apron must be replaced with concrete","Handrails where there are three or more steps; steps 30 inches above grade need handrails on both sides; no more than 4 inch spacing between spindles","Porches with no perimeter railings must have railings installed (no more than 4 inch spindle spacing)","Peeling or chipping exterior paint scraped and repainted; unpainted exterior surfaces painted","Broken window panes repaired","Exterior electrical open splices or improperly installed fixtures corrected","Gutters and downspouts properly installed","Any hazardous condition the inspector finds must be corrected","Work done without permits may be cited and must be permitted and inspected","Open permits must be closed out (final inspections passed and certificate obtained)","Separate smoke alarm / CO alarm certificate from the Regional Fire Prevention Alliance before settlement","Also: Open permits and work done without permits: Open permits must be closed out (remaining inspections passed and the certificate obtained), and work done without permits may be cited during the resale inspection.","Also: Temporary certificate of occupancy fee: Town code sets $30 for the first issuance and renewal of a temporary certificate of occupancy."]$j$::jsonb, $j$[{"label":"Single family dwelling resale CO (2026 application)","amount":"$120.00"},{"label":"Reinspection (2026 application)","amount":"$25.00"},{"label":"Reinspection fee in town code, 1-2 family residences under 5,000 sq ft (Ord. 2024-15; differs from the $25 on the form)","amount":"$50"}]$j$::jsonb, $t$https://web.archive.org/web/20260301203838/https://mountephraim-nj.com/wp-content/uploads/2026/02/Application-for-Resale-CO-Inspection.pdf$t$, $t$https://www.mountephraim-nj.com/page/construction-office-zoning-resale-inspections/$t$, $j$[{"url":"https://ecode360.com/30453557","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/30453559","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/30453560","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/30453572","label":"Official source (ecode360.com)"},{"url":"https://web.archive.org/web/20260301203838/https://mountephraim-nj.com/wp-content/uploads/2026/02/Application-for-Resale-CO-Inspection.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260301204218/https://mountephraim-nj.com/wp-content/uploads/2026/02/Resale-Inspection-Checklist.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20211229005949/https://mountephraim-nj.com/wp-content/uploads/2021/10/Application-for-Resale-CO-inspection.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$Prior to the sale of any residential premises involving a new occupancy, the Enforcement Officer shall issue a certificate of continued occupancy in accordance with the standards set forth in Subsection A of this section.$t$, $t$2d6c5c7444e6c3c469f0c7cff2b0fc8fbe153d194585861fca5b3177295fe8dd$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":17,"q_ok":8,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0425.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0425.json$t$, true),
  ($t$0425$t$, $t$Mount Ephraim Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (run by Barrington Borough) (town fire bureau)","Contact: Nick D'Alonzo, Fire Official (fire code questions: fireofficial@barringtonboro.com) · 856-547-0991 · firealliance@barringtonboro.com","Apply: 14 or more business days before the change of occupant for the lowest fee; weekends, holidays and the settlement date do not count. Inspections are scheduled Monday to Friday, 9am to 2pm. Certificates are valid 6 months and are not transferable.","How to apply: Fill out the Regional Fire Prevention Alliance smoke alarm certification application (fillable PDF) and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox at 205 Haines Avenue, Barrington, NJ 08007. Include a check or money order payable to 'Regional Fire Prevention Alliance'. Walk-in office hours are Tuesday to Friday, 8am to 2pm. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 8/5/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","Smoke alarms by construction date: pre-1975 homes need 10-year sealed battery alarms on each level including the basement; newer homes need AC powered interconnected alarms per the era table on the form","Smoke alarms on every level, outside sleeping areas, and at the bottom of basement stairwells","All smoke alarms must be less than 10 years old; someone must take them down and check the date on the back, and undated alarms must be replaced","Low voltage (alarm company) fire alarm systems must be tested by an alarm contractor before the inspection, with the certification shown to the inspector","CO alarm outside of but within 10 feet of all sleeping areas if the home has a fuel burning appliance, fireplace or garage; CO alarms must be less than 7 years old","House numbers: Arabic numerals at least 3 inches tall, contrasting, mounted at least 60 inches above ground and visible from the street","Secondary power source warning label (wording like 'CAUTION MULTIPLE SOURCES OF POWER', not handwritten) within 18 inches of the main electrical panel and meter if there is a generator, solar panels or battery storage","Everything must be done before the inspector arrives; an adult (18+) must be present at the start of the time block","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8-13 business days before","amount":"$74.00"},{"label":"Request received 4-7 business days before","amount":"$106.00"},{"label":"Request received 3 business days or less before","amount":"$171.00"},{"label":"Reinspection after a failed inspection","amount":"$50.00"},{"label":"Penalty for change of ownership or occupancy without the certificate","amount":"$500"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://web.archive.org/web/20211229005949/https://mountephraim-nj.com/wp-content/uploads/2021/10/Application-for-Resale-CO-inspection.pdf","label":"Official source (web.archive.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$08eebb02e7c8c8956f22eef6f3fd0c43dab6aa79123e41b674552e541c99159e$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":17,"q_ok":8,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0425.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0425.json$t$, true),
  ($t$0426$t$, $t$Oaklyn Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (exterior housing code and property area inspection on sale)$t$, $j$["Issued by: Borough of Oaklyn Administrative Office of Code Enforcement (Housing Code Department)","Contact: 856-858-2457","How to apply: Request the exterior inspection from the Code Enforcement office at Borough Hall, 500 White Horse Pike, Oaklyn, NJ 08107 (tel. 856-858-2457). The borough's Certificate of Compliance form (updated 10/10/18) asks for the settlement date, block and lot, contact person, property address and owner, and how to receive the repair letter and certificate (pick up, mail or fax). Confirm the current form and how to pay with Borough Hall, since the current borough website could not be read.","Valid for: 90 days, provided the seller has not changed (2018 borough form)","Exterior housing code inspection and exterior property area inspection on every sale or resale","Sidewalks, walkways, driveways and driveway aprons made safe: no cracks, raised walkways or deteriorated concrete (asphalt or macadam for driveways only, not aprons or sidewalks)","Handrails where there are three or more steps; steps 30 inches above grade need a handrail on one side; 2 inch round handrails returned to post, with no more than 4 inch spindle spacing","Railings on porch or stoop perimeters that have none, with no more than 4 inch spindle spacing","Peeling, chipping or unpainted exterior surfaces scraped and painted","Broken window panes repaired","Open electrical splices or improperly installed fixtures corrected","Gutters and downspouts hooked up and in place","Any obvious hazardous and maintenance conditions","Repairs the Code Enforcement office finds necessary must be completed within 30 days of notice","Sump pump must not be connected to the sanitary sewer; Public Works inspects before settlement","Also: Sump pump sewer connection inspection by Public Works: Town code section 108-12 bars connecting sump pumps and similar discharges to the sanitary sewer; the borough form has a Public Works sign-off and says Public Works inspects before settlement (the form cites both 108-12 and 108-22)."]$j$::jsonb, $j$[{"label":"Housing code exterior inspection on sale (covers all inspections and reinspections)","amount":"$50"}]$j$::jsonb, $t$https://img1.wsimg.com/blobby/go/5cd08893-258d-4063-980b-adf6716d47d7/downloads/Resale%20Application.pdf$t$, $t$https://www.oaklyn-nj.net/$t$, $j$[{"url":"https://ecode360.com/11272064","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11272065","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11272066","label":"Official source (ecode360.com)"},{"url":"https://img1.wsimg.com/blobby/go/5cd08893-258d-4063-980b-adf6716d47d7/downloads/Resale%20Application.pdf","label":"Official source (img1.wsimg.com)"}]$j$::jsonb, $t$It is hereby determined that an exterior housing code inspection and an exterior property area inspection, as defined in the BOCA National Property Maintenance Code/1996, shall be required on the sale and/or resale of all properties within the boundaries of the Borough of Oaklyn.$t$, $t$6a8e71a1ac8c0a88920992f2ebcacbe1d1a2e4c16e7b937e378de1f76e2c059b$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":6,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0426.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0426.json$t$, true),
  ($t$0426$t$, $t$Oaklyn Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (run by Barrington Borough) (town fire bureau)","Contact: Nick D'Alonzo, Fire Official (fire code questions: fireofficial@barringtonboro.com) · 856-547-0991 · firealliance@barringtonboro.com","Apply: 14 or more business days before the change of occupant for the lowest fee; weekends, holidays and the settlement date do not count. Inspections are scheduled Monday to Friday, 9am to 2pm. Certificates are valid 6 months and are not transferable.","How to apply: Fill out the Regional Fire Prevention Alliance smoke alarm certification application (fillable PDF) and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox at 205 Haines Avenue, Barrington, NJ 08007. Include a check or money order payable to 'Regional Fire Prevention Alliance'. Walk-in office hours are Tuesday to Friday, 8am to 2pm. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 8/5/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","Smoke alarms by construction date: pre-1975 homes need 10-year sealed battery alarms on each level including the basement; newer homes need AC powered interconnected alarms per the era table on the form","Smoke alarms on every level, outside sleeping areas, and at the bottom of basement stairwells","All smoke alarms must be less than 10 years old; someone must take them down and check the date on the back, and undated alarms must be replaced","Low voltage (alarm company) fire alarm systems must be tested by an alarm contractor before the inspection, with the certification shown to the inspector","CO alarm outside of but within 10 feet of all sleeping areas if the home has a fuel burning appliance, fireplace or garage; CO alarms must be less than 7 years old","House numbers: Arabic numerals at least 3 inches tall, contrasting, mounted at least 60 inches above ground and visible from the street","Secondary power source warning label (wording like 'CAUTION MULTIPLE SOURCES OF POWER', not handwritten) within 18 inches of the main electrical panel and meter if there is a generator, solar panels or battery storage","Everything must be done before the inspector arrives; an adult (18+) must be present at the start of the time block","Oaklyn ordinance (2018 borough form): smoke alarms on every floor and in every bedroom; 10-year sealed battery alarms required since 1/1/19","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8-13 business days before","amount":"$74.00"},{"label":"Request received 4-7 business days before","amount":"$106.00"},{"label":"Request received 3 business days or less before","amount":"$171.00"},{"label":"Reinspection after a failed inspection","amount":"$50.00"},{"label":"Penalty for change of ownership or occupancy without the certificate","amount":"$500"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://img1.wsimg.com/blobby/go/5cd08893-258d-4063-980b-adf6716d47d7/downloads/Resale%20Application.pdf","label":"Official source (img1.wsimg.com)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$9c65f39679078c6065e6c51c2405fb9e740c345001c34a14fbf9637041389214$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":6,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0426.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0426.json$t$, true),
  ($t$0427$t$, $t$Pennsauken Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Housing Resale Certificate of Inspection (Housing Resale CO)$t$, $j$["Issued by: Pennsauken Township Department of Housing / Property Maintenance","Contact: Suzanne Paul, Housing & Property Maintenance Assistant · 856-665-1000 ext. 1411 · spaul@pennsauken.gov","Apply: No fixed number of days published. The township says to leave enough time between the inspection and settlement so the certificate is issued before settlement. If the home fails, the report arrives about 2 to 3 days after the inspection.","How to apply: Complete the Housing Resale & Fire Certificate Inspection application (PDF) or apply online through the township's GovPilot portal. Submit the form with the $175 fee (cash, check or money order payable to Pennsauken Township) to the Municipal Building, Attn: Housing / Property Maintenance Dept., 5605 N. Crescent Blvd., Pennsauken, NJ 08110. The inspection is scheduled once the form and fee are received. Housing & Property Maintenance Assistant Suzanne Paul (ext. 1411, spaul@pennsauken.gov) handles applications and scheduling.","Interior and exterior housing resale inspection of every 1 and 2 family dwelling","Grading and drainage, sidewalks and driveways, accessory structures","Stumps from trees that caused sidewalk damage","Exterior structure: protective treatment, structural members, foundation walls, roofs and drainage","Roof certification and chimney certification (wood burning or gas) may be required","Stairways, decks, porches and balconies; handrails and guards","Interior structural members, surfaces, stairs and walking surfaces","Infestation / termite","Plumbing system hazards and plumbing certification","Mechanical appliances and mechanical certification","Electrical hazards and electrical certification; 2 outlets in every bedroom; protected outlets for sump or toilet pumps, bathrooms, kitchen counters and sinks within 6 feet; outdoor outlets weather resistant with a weatherproof cover","Smoke alarms, carbon monoxide detector, interior locked doors","Shed letter if there is a shed; grass or weeds","Rental registration if the property will be rented","New or open permits must be closed; no new occupancy until the final CO is issued","Also: Open and required construction permits must be closed: All permits must be obtained, inspected and pass inspection before the final Certificate of Inspection is issued. Construction dept: 856-665-1000 x129, building@pennsauken.gov.","Also: Temporary CO by buyer affidavit: Only the buyer may sign a notarized Affidavit for a Temporary CO, accepting responsibility for the violations; it must be delivered to Housing before settlement.","Also: Rental registration if buyer will rent: Checklist item 251.19 rental registration required; 1-2 family rentals register annually ($350) and are inspected."]$j$::jsonb, $j$[{"label":"Housing Resale CO plus Fire Certificate, combined application fee","amount":"$175.00"},{"label":"Housing Resale Certificate of Inspection portion","amount":"$100"}]$j$::jsonb, $t$https://www.pennsauken.gov/DocumentCenter/View/1116/Housing-Resale-And-Fire-Cert-Inspection-Application-PDF$t$, $t$https://www.pennsauken.gov/194/Housing-Property-Maintenance$t$, $j$[{"url":"https://www.pennsauken.gov/194/Housing-Property-Maintenance","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1154/Housing-Resale-And-Fire-Cert-Inspection-Information-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1116/Housing-Resale-And-Fire-Cert-Inspection-Application-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1406/Housing-Resale-Inspection-Checklist-PDF","label":"Official source (pennsauken.gov)"}]$j$::jsonb, $t$A housing resale CO and fire certificate is required for every transfer of ownership for all one and/or two-family dwellings.$t$, $t$f160be40592bbd5f2b67369d92f7ca7ce36ca0e579b0ad36ccb762cdf8cc1bc9$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0427.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0427.json$t$, true),
  ($t$0427$t$, $t$Pennsauken Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pennsauken Township Department of Housing / Property Maintenance (Fire Certificate issued with the Housing Resale CO) (town fire bureau)","Contact: Suzanne Paul, Housing & Property Maintenance Assistant · 856-665-1000 ext. 1411 · spaul@pennsauken.gov","Apply: No tier schedule on the current township application (flat $75 fire certificate portion). Town code says a certificate is not transferable and a new application is needed if the change of occupancy does not happen within six months.","How to apply: Same combined application as the Housing Resale CO. Submit the Housing Resale & Fire Certificate Inspection application with the $175 total fee to the Housing / Property Maintenance Dept., 5605 N. Crescent Blvd., or apply online via GovPilot.","Fire official in the NJ state directory (town), updated 5/18/2026: Steven Schwegel, Jr. · (856) 665-0774 · sschwegel@pennsaukenfire.org","Each level must have an AC hard wired or 10-year sealed battery smoke alarm; all smoke alarms must be within 10 years of the manufacture date","Alarm type depends on original construction date: pre-1975 homes need 10-year sealed battery alarms on each level within 10 feet of each bedroom; newer homes need hard wired interconnected alarms per the era table","A smoke alarm is required in every bedroom regardless of the home's age, plus outside sleeping areas and on every level","Smoke alarm in the basement within 10 feet of the stairway (not in the stairway), and at the top of walk-up attic stairs","Carbon monoxide alarm within 10 feet of each sleeping area","Hard-wired proprietary fire alarm systems must be tested per NFPA 72 with a test report at inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Certificate portion of the combined resale application","amount":"$75"},{"label":"Reinspection after noncompliance on the first inspection (town code section 243-18D)","amount":"$50"},{"label":"Town code CSDCMAC fee, request more than 10 days before inspection (section 243-18A, Ord. 2017:09; the current application charges a flat $75)","amount":"$50"},{"label":"Town code CSDCMAC fee, request 4 to 10 days before inspection (section 243-18B)","amount":"$85"},{"label":"Town code CSDCMAC fee, request less than 4 days before inspection (section 243-18C)","amount":"$140"}]$j$::jsonb, $t$https://www.pennsauken.gov/DocumentCenter/View/1116/Housing-Resale-And-Fire-Cert-Inspection-Application-PDF$t$, $t$https://www.pennsauken.gov/194/Housing-Property-Maintenance$t$, $j$[{"url":"https://www.pennsauken.gov/DocumentCenter/View/1154/Housing-Resale-And-Fire-Cert-Inspection-Information-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1115/Smoke-Alarm-Carbon-Monoxide-Detector-Fire-Extinguisher-Instructions-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://ecode360.com/32740868","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/32740874","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/32740885","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1116/Housing-Resale-And-Fire-Cert-Inspection-Application-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://ecode360.com/32740869","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The housing resale and fire inspections are completed by the township housing department inspectors.$t$, $t$40a0ac59a97c733fc0906085dfe2203bd8ad7b0e70476d2882f88cfa301f411d$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0427.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0427.json$t$, true),
  ($t$0428$t$, $t$Pine Hill Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (resale C.O.)$t$, $j$["Issued by: Borough of Pine Hill (town code names the Construction Official; the borough's Construction Office page sends resale C.O. requests to the Pine Hill Fire Department / Fire District)","Contact: 856-783-8666","Apply: Town code: inspection within five working days after the application and fee are received.","How to apply: The borough's Construction Office page says to contact the Pine Hill Fire Department at (856) 783-8666 to obtain a Certificate of Occupancy for the resale of a property. Confirm with the borough whether a separate Construction Office continued C.O. (town code fee $150) is also required, or whether the fire district certificate is the resale C.O. Construction Office paperwork can be dropped off and picked up daily 8:30 am to 4:00 pm; Construction Official James Gallagher, (856) 783-7400 x 208.","Valid for: Town code: an application is valid for six months from filing; after that a new application and fee are needed.","Town code: the home must comply with state and borough building, plumbing, electrical, zoning, health, safety, fire and minimum housing standards (including the International Property Maintenance Code) before the certificate is issued","Violations found at inspection are grounds to deny the certificate","A temporary certificate of compliance may be issued for up to 30 days for minor violations, but not where conditions make the home uninhabitable or unsafe","In practice the borough points sellers to the Pine Hill Fire District smoke alarm, CO alarm and fire extinguisher inspection (see the fire certificate)","Also: Rental registration and Certificate of Habitability (if the buyer will rent): Rental dwelling units must be registered with the borough, and a new owner of a registered rental must notify the borough within 10 days after receiving the deed; a Certificate of Habitability for rentals comes from the Construction Office."]$j$::jsonb, $j$[{"label":"Continued certificate of occupancy (town code section 10-1.10b10(c))","amount":"$150"},{"label":"Temporary certificate of occupancy, issuance or renewal (section 10-1.10b10(d))","amount":"$50"}]$j$::jsonb, null, $t$https://www.pinehillboronj.com/departments/construction-office/$t$, $j$[{"url":"https://www.pinehillboronj.com/departments/construction-office/","label":"Official source (pinehillboronj.com)"},{"url":"https://ecode360.com/35591545","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35591542","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35591553","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35591562","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35591557","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35591560","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35591561","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$To obtain a Certificate of Occupancy (C.O.) for the resale of a property, please contact the Pine Hill Fire Department: (856) 783-8666.$t$, $t$6a71d89af81afa739760b6a070fe3c23ba6e39513fcdf514d5399126ed7030ec$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0428.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0428.json$t$, true),
  ($t$0428$t$, $t$Pine Hill Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pine Hill Fire District #1, Bureau of Fire Prevention (fire district)","Contact: Robert Fowler Jr., Fire Marshal · 856-784-0030 · firemarshal@pinehillfiredistrict.com","Apply: More than 10 business days before the inspection date for the lowest fee; inspections are done one day a week. Form and payment must be received before an appointment is scheduled.","How to apply: Fill out the application in the Smoke Detector Inspection Packet and mail it or drop it off with a check or money order (no cash) at the Bureau of Fire Prevention, 1109 Erial Road, Pine Hill, NJ 08021. The form and payment must be received before an appointment is scheduled; the office then contacts you. If dropping off, put it in the mailbox and send a follow-up email. The office is part time and voicemail is not checked daily, so email firemarshal@pinehillfiredistrict.com for a faster reply. Fees are non-refundable.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Robert Fowler · (856) 784-0030 · firemarshal@pinehillfiredistrict.com","Power to the house must be on before scheduling, or an approved Special Circumstance form (extra fee, plus a follow-up inspection before anyone moves in)","Smoke alarm on every level within 15 feet of the bedrooms","Smoke alarms older than 10 years must be replaced before inspection","Hardwired smoke alarms must stay and cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedroom doors; CO alarms older than 7 years must be replaced; not plugged into switched outlets or outlets against floor molding","Fire extinguisher rated 2A10BC (5 lbs), brand new or dated/tagged for the current year, mounted visibly within 10 feet of the kitchen or toward an exit from the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before inspection","amount":"$45.00"},{"label":"5 to 9 business days before inspection","amount":"$90.00"},{"label":"4 or less business days before inspection","amount":"$161.00"},{"label":"Re-inspection","amount":"$20.00"},{"label":"Special Circumstance (power off with hardwired alarms): additional fee on top of the normal fee, same tiers, e.g. 10+ business days","amount":"$45.00"},{"label":"Penalty for occupying without the required follow-up inspection (Special Circumstance cases)","amount":"$500.00"}]$j$::jsonb, $t$https://pinehillfiredistrict.com/wp-content/uploads/2025/11/Smoke-Detector-Inspection-Packet.pdf$t$, $t$https://pinehillfiredistrict.com/department-list/inspection-office/$t$, $j$[{"url":"https://pinehillfiredistrict.com/wp-content/uploads/2025/11/Smoke-Detector-Inspection-Packet.pdf","label":"Official source (pinehillfiredistrict.com)"},{"url":"https://pinehillfiredistrict.com/department-list/inspection-office/","label":"Official source (pinehillfiredistrict.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for Certification of Smoke Detector and carbon Monoxide Alarm Compliance as required by N.J.A.C 5:70-2.3, based upon the amount of time remaining before the date of inspection as follows:$t$, $t$1fbfa5a384c5e12d6c1a4f753b194b94a7835f47c358bd378980ecf83b22310b$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0428.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0428.json$t$, true),
  ($t$0430$t$, $t$Runnemede Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Runnemede Office of Code Enforcement (Construction and Code Enforcement)","Contact: Keith Raveling, Construction Official · 856-939-2815","Apply: Apply at least 10 working days before settlement or occupancy","How to apply: Download the Residential CCO application (3 pages, including a swimming pool affidavit), check 'Buyer/Sale', complete it, and submit it with a check to the Office of Code Enforcement, 24 N. Black Horse Pike, Runnemede, NJ 08078, at least 10 working days before settlement. Call 856-939-2815 with questions; Code Enforcement is also at 856-939-5161 x1006.","Valid for: Application expires 90 days after inspection if the CCO has not been issued","House number visible from the street, at least 4 inches tall, Arabic numerals","Steps free of cracks and trip hazards, even treads and risers, closed risers (4 inch ball rule)","Sidewalks, aprons and driveways level with no cracks or lifts over 1/2 inch; driveway parking surface must be impervious (no stone or gravel)","Graspable handrail on steps with 4 or more risers; guardrails where porch, landing or stairs are over 30 inches above grade","Property free of debris and hazards; abandoned tanks and wells removed with a permit","No peeling paint or rust on exterior surfaces","Gutters and downspouts secure and clear, with splash blocks or diverters","Foundation openings sealed; basement and crawlspace windows intact; Bilco doors and crawlspace access working and sealed","Exterior receptacles, including garages and sheds, GFCI protected","Window glass intact; electric service cable secured; damaged wiring and fixtures replaced","Approved chimney cap","Zoning and construction permits for additions, pools, sheds, garages, decks and fences; open permits must be closed","Swimming pool: bonding/grounding certificate from a licensed NJ electrician dated within 30 days of the application, plus pool affidavit","All work must be completed before the certificate can be issued","Also: Open construction permits must be closed before sale: Any permits without final inspection or certificate of approval must be closed out before the CCO is issued; permits are required for any work done without permits.","Also: Swimming pool affidavit and bonding certificate: Pool affidavit is page 3 of the residential CCO application; a bonding/grounding certificate from a licensed NJ electrician dated within 30 days is required if there is a pool."]$j$::jsonb, $j$[{"label":"Residential dwelling CCO application","amount":"$100.00"},{"label":"Reinspection, after the first reinspection (residential)","amount":"$25.00"},{"label":"Commercial / Multi Family CCO application (may apply to a 2-family sale; not confirmed)","amount":"$150.00"}]$j$::jsonb, $t$https://runnemedenj.org/documents/add-document/department-documents/construction/certificate-of-continued-occupancy/69-construction-form-residential-cco/file$t$, $t$https://runnemedenj.org/departments/construction$t$, $j$[{"url":"https://runnemedenj.org/documents/add-document/department-documents/construction/certificate-of-continued-occupancy/68-exterior-compliance-requirements-for-a-certificate-of-continued-occupancy-for-the-sale-of-a-single-family-dwelling/file","label":"Official source (runnemedenj.org)"},{"url":"https://runnemedenj.org/documents/add-document/department-documents/construction/certificate-of-continued-occupancy/69-construction-form-residential-cco/file","label":"Official source (runnemedenj.org)"},{"url":"https://runnemedenj.org/documents/add-document/department-documents/construction/certificate-of-continued-occupancy/72-certificate-of-continued-occupancy-requirement-for-rental-commercial-properties/file","label":"Official source (runnemedenj.org)"},{"url":"https://runnemedenj.org/departments/construction","label":"Official source (runnemedenj.org)"},{"url":"https://runnemedenj.org/documents/add-document/department-documents/construction/certificate-of-continued-occupancy/70-construction-form-commercial-multi-family-cco/file","label":"Official source (runnemedenj.org)"}]$j$::jsonb, $t$EXTERIOR COMPLIANCE REQUIREMENTS$t$, $t$9fa3bd9eb90c5a022996723b1c3e7039e0e7d5486db9551eb0185b3adf232eba$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0430.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0430.json$t$, true),
  ($t$0430$t$, $t$Runnemede Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Runnemede Bureau of Fire Prevention, Office of the Fire Marshal (town fire bureau)","Contact: Michael Kearney, Captain / Fire Official · 856-939-2817 · Mkearney@runnemedenj.org","Apply: Schedule at least 8 days ahead for the lowest fee (March 2025 application)","How to apply: Request a Smoke Detector & Carbon Monoxide Alarm inspection through the borough's SDL online portal, linked from the Fire Prevention / Inspections page (the portal needs a free citizen login). The March 2025 paper application said fees are payable to the Borough of Runnemede by check or money order, no refunds.","Fire official in the NJ state directory (town), updated 5/22/2026: Michael Kearney · (856) 939-2817 · Mkearney@runnemedenj.org","Smoke alarm requirements depend on the year the home was built (pre-1977 battery alarms on each level including the basement, within 10 feet of bedroom doors; later eras need 120V hardwired, and later interconnected, alarms as listed in the borough table)","Where no alarms exist or battery alarms are being replaced, use 10-year sealed battery alarms; hardwired alarms cannot be replaced with battery alarms","Smoke alarms must not be over 10 years old from date of manufacture","Alarms must be mounted with proper hardware; nails, thumbtacks, tape or Velcro are not acceptable","Carbon monoxide alarm in the hall outside bedrooms, no more than 10 feet from any bedroom","Monitored alarm systems in homes built 1977 or later must be maintained at change of occupancy","Secondary power source label ('CAUTION: MULTIPLE SOURCES OF POWER') within 18 inches of the main panel and meter if the home has a generator, solar panels or battery storage","The borough states that since February 2025 a fire extinguisher is no longer required for the certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Appointment scheduled at least 8 days before inspection","amount":"$50.00"},{"label":"Appointment scheduled less than 8 but more than 4 days before inspection","amount":"$75.00"},{"label":"Appointment scheduled less than 4 days before inspection","amount":"$125.00"},{"label":"Penalty for not obtaining the certificate before sale or change of occupancy","amount":"$500"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/camden/runnemede/requests/smokeAlarm$t$, $t$https://runnemedenj.org/public-safety/fire-prevention$t$, $j$[{"url":"https://runnemedenj.org/documents/add-document/department-documents/fire-prevention/847-requirements-for-smoke-alarms-for-one-and-two-family-residences/file","label":"Official source (runnemedenj.org)"},{"url":"https://web.archive.org/web/20250803120942/https://runnemedenj.org/wp-content/uploads/2025/03/CSDCMAC-Application-2025.pdf","label":"Official source (web.archive.org)"},{"url":"https://runnemedenj.org/public-safety/fire-prevention","label":"Official source (runnemedenj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$At the time of change of occupancy by way of sale, lease or rent of a residential dwelling, the smoke detectors shall remain in compliance from the time when the house or building was built$t$, $t$564097d0c15d2c9723d954007c9c9c288c0f05bc227d2d8161c9d483e582bd4a$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0430.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0430.json$t$, true),
  ($t$0431$t$, $t$Somerdale Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance / Certificate of Continued Occupancy (CCO), Residential Safety Inspection$t$, $j$["Issued by: Office of the Fire Marshal (Somerdale Fire Prevention Bureau), acting for the Borough Housing Code Official","Contact: David Marx, Fire Official (NJ DCA fire directory) · 856-783-6320 ext. 2100 · dmarx@somerdale-nj.com","Apply: Apply 11 or more working days before settlement for the lowest fee","How to apply: Fill out the Application for Certificate of Compliance, Single Family Dwelling completely and submit it with a check or money order payable to the Somerdale Fire Prevention Bureau. Contact the Fire Marshal's office at 856-783-6320 ext. 2100 or dmarx@somerdale-nj.com. Borough Hall is at 105 Kennedy Blvd.","A representative must be on location for the inspection","Lead paint certification for any house built before 1978 (application form; the guideline sheet labels this as for rental properties)","House numbers in Arabic lettering, 3 inches, on the front wall or porch, 30 inches above ground","Smoke alarm on each floor and in each bedroom; 10-year sealed battery alarms where none exist or when replacing battery alarms; hardwired alarms may not be replaced with battery alarms","Carbon monoxide detector on each floor","2A/10BC fire extinguisher, not over 10 lbs, wall mounted about 5 ft from the ground (waist level accepted), within 10 ft of the kitchen and in view (form still lists it)","Sidewalks and driveways with no cracks or unevenness, no skim coating or ramping; must be visible and clear of snow, ice and parked cars","Front and rear porch or deck well maintained and sturdy","Windows operable and in decent condition","Firmly secured railing on stairs with 4 or more steps","Water check: toilets flush, drains work, hot water","Covers on all light switches and receptacles","No holes in walls, floors or ceilings; painted","Sump pump must not be tied into the sewer","Yard and property maintained (grass cut, trimmed)","Secondary power source labels on electric panel and meter if there is solar or a generator; solar panels and EV chargers must have been permitted","Any open permits must be closed / finalized","Also: Open permits must be closed: Any open permits must be closed / finalized; solar panels and EV chargers must have been permitted.","Also: Lead paint certification for pre-1978 homes: The single family application states any house built before 1978 must have a lead paint certification provided (citing N.J. P.L. 2021, c. 182, the rental lead law)."]$j$::jsonb, $j$[{"label":"Single family, 11+ working days before settlement","amount":"$70.00"},{"label":"Single family, 4 to 10 working days before settlement","amount":"$90.00"},{"label":"Single family, 1 to 3 working days before settlement","amount":"$161.00"},{"label":"Reinspection (each)","amount":"$25.00"}]$j$::jsonb, $t$https://somerdale-nj.com/wp-content/uploads/2026/05/Single-Family-Dewelling.pdf$t$, $t$https://somerdale-nj.com/departments/fire-marshal/$t$, $j$[{"url":"https://ecode360.com/30005482","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/30005485","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/30005487","label":"Official source (ecode360.com)"},{"url":"https://somerdale-nj.com/departments/fire-marshal/","label":"Official source (somerdale-nj.com)"},{"url":"https://somerdale-nj.com/departments/construction/","label":"Official source (somerdale-nj.com)"},{"url":"https://somerdale-nj.com/wp-content/uploads/2026/05/Single-Family-Dewelling.pdf","label":"Official source (somerdale-nj.com)"},{"url":"https://somerdale-nj.com/wp-content/uploads/2026/05/Guidelines.pdf","label":"Official source (somerdale-nj.com)"}]$j$::jsonb, $t$All existing homes, dwellings, buildings and structures in the Borough of Somerdale that are being sold, conveyed or transferred from one owner to another owner shall be inspected by the Housing Code Official upon such resale after the effective date of this chapter$t$, $t$25e5bd87be00b3fdb1020d6caf7a785c1f72f8c456d642876c4856cc12794651$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":11,"q_ok":3,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0431.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0431.json$t$, true),
  ($t$0431$t$, $t$Somerdale Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Somerdale Office of the Fire Marshal / Somerdale Fire Prevention Bureau (town fire bureau)","Contact: David Marx, Fire Official (NJ DCA fire directory) · 856-783-6320 ext. 2100 · dmarx@somerdale-nj.com","Apply: 11 or more working days before settlement for the lowest fee","How to apply: Same application as the CCO: submit the Single Family Dwelling Certificate of Compliance application with a check or money order payable to the Somerdale Fire Prevention Bureau.","Fire official in the NJ state directory (town), updated 3/9/2026: David Marx · (856) 783-6320 · dmarx@somerdale-nj.com","Smoke alarm on each floor and in each bedroom","10-year sealed battery alarms where no alarms exist or when replacing battery alarms; hardwired alarms must not be replaced with battery alarms","Carbon monoxide detector on each floor","2A/10BC fire extinguisher, not to exceed 10 lbs, wall mounted about 5 ft from the ground (waist level accepted), within 10 ft of the kitchen, in view (form still lists it)","Secondary power source labels on electric panel and meter (as of 2/3/25) where solar or generators exist","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined CCO and smoke/CO/extinguisher inspection, 11+ working days before settlement","amount":"$70.00"},{"label":"Combined inspection, 4 to 10 working days","amount":"$90.00"},{"label":"Combined inspection, 1 to 3 working days","amount":"$161.00"}]$j$::jsonb, $t$https://somerdale-nj.com/wp-content/uploads/2026/05/Single-Family-Dewelling.pdf$t$, $t$https://somerdale-nj.com/departments/fire-marshal/$t$, $j$[{"url":"https://somerdale-nj.com/wp-content/uploads/2026/05/Guidelines.pdf","label":"Official source (somerdale-nj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://somerdale-nj.com/wp-content/uploads/2026/05/Single-Family-Dewelling.pdf","label":"Official source (somerdale-nj.com)"}]$j$::jsonb, $t$FIRE EXTINGUISHER (INSTALLED 5 FT. FROM GROUND, MOUNTED ON THE WALL, WITHIN 10 FT OF THE KITCHEN IN VIEW OF PUBLIC) (MOUNTED WAIST LEVEL IS ACCEPTED) MUST BE A 2A/10BC FIRE EXTINGUISHER, not to exceed 10lbs.$t$, $t$b3bcb534ba526efcc78590a64f7c88625d28db6a7a83f1a3b9bea1602c218dc2$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":11,"q_ok":3,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0431.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0431.json$t$, true),
  ($t$0432$t$, $t$Stratford Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Stratford Borough requires a resale certificate. Call the office before closing.","Contact: 856-783-0600 · codeenforcement@stratfordnj.org"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://stratfordnj.org/code-enforcement/$t$, $j$[{"url":"https://stratfordnj.org/borough-forms/","label":"Official source (stratfordnj.org)"},{"url":"https://stratfordnj.org/code-enforcement/","label":"Official source (stratfordnj.org)"}]$j$::jsonb, $t$Smoke and Fire Certificates of Occupancy$t$, $t$22730652de077c463cca3c064ee2b52324094f1fc2d3f30e5e0460d11b7cdb0d$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0432.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0432.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0432$t$, $t$Stratford Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106","Apply: Fee depends on how many business days before the change of occupant the request is received: more than 10 business days for the lowest fee.","How to apply: Apply, schedule and pay online through the NJ DCA fire service portal (firesolutions.dca.nj.gov), using 'Apply for Smoke Certification'.","Fire official in the NJ state directory (NJ DCA, state), updated 2/2/2023: Louis Kilmer · (609) 633-6132","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-4.19 for 1 and 2 family homes (the Borough and DCA pages found do not list the details)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://stratfordnj.org/pdf/forms/DCA-Smoke-Fire-CO.pdf","label":"Official source (stratfordnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$All Certificates of Occupancy for the Borough of Stratford will now be handled by the New Jersey Department of Community Affairs (DCA).$t$, $t$698338d559dd74c2fb0831486dbc0678bc18d380aff5bdb69345d679bfcd525e$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0432.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0432.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0433$t$, $t$Tavistock Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Tavistock Borough requires a resale certificate. Call the office before closing.","Contact: Denise K. Moules, Municipal Clerk / CFO · 856-429-0039 · clerk@tavistocknj.org"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://tavistocknj.org/whos-who/$t$, $j$[{"url":"https://tavistocknj.org/wp-content/uploads/2025/05/2024-Tavistock-Minutes-12-19-2024.pdf","label":"Official source (tavistocknj.org)"},{"url":"https://tavistocknj.org/wp-content/uploads/2026/05/2026-Tavistock-Minutes-2-24-2026.pdf","label":"Official source (tavistocknj.org)"},{"url":"https://tavistocknj.org/whos-who/","label":"Official source (tavistocknj.org)"}]$j$::jsonb, $t$Resolution #34-2024 Authorizing Shared Service Agreement with Haddonfield - Construction$t$, $t$c9de72853dd79c3caa583e563508246b7fdba997de8c3d88b22f3ec7cfe44441$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":7,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0433.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0433.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0433$t$, $t$Tavistock Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Haddonfield Bureau of Fire Prevention (serving Tavistock under a shared service agreement) (town fire bureau)","Contact: Ernest F. Busch, Fire Official (Haddonfield, listed for Tavistock in the DCA fire directory) · 856-429-4308 · ebusch@haddonfield-nj.gov","How to apply: Contact the Haddonfield Fire Official (Ernest F. Busch) or the Haddonfield Construction and Zoning Office, Room 104, Haddonfield Borough Hall, which takes smoke detector compliance forms and payment for Haddonfield. Confirm the Tavistock process and fee before applying.","Fire official in the NJ state directory (town), updated 5/18/2026: Ernest F Busch · (856) 429-4308 · ebusch@haddonfield-nj.gov","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php$t$, $j$[{"url":"https://tavistocknj.org/wp-content/uploads/2025/05/2024-Tavistock-Minutes-12-19-2024.pdf","label":"Official source (tavistocknj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"}]$j$::jsonb, $t$Resolution #33-2024 Authorizing Shared Service Agreement with Haddonfield - Fire Services$t$, $t$de9ef09aab281ecb23a6d245ecfc271a37d2560897e9c10df9a56258b5788c90$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":7,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0433.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0433.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0434$t$, $t$Voorhees Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate (Residential Change of Owner)$t$, $j$["Issued by: Voorhees Planning & Zoning Department","Contact: Suraya Rahmad, Zoning Clerk (zoning@voorheesnj.com and srahmad@voorheesnj.com on the Zoning page) · 856-429-0647 · resales@voorheesnj.com","Apply: Fee depends on how soon the inspection is requested after the application is submitted: more than 10 business days is the lowest fee. Submit the signed and sealed survey early (one issued within the past 60 days is recommended).","How to apply: Fill out the Residential Resale Application and send it to the Planning & Zoning Department by email (resales@voorheesnj.com), through the SDL online portal, or in person at 2400 Voorhees Town Center. Pay by cash or check payable to Voorhees Township. Include the buyer, agent and certificate email, lock box details, and the survey.","Valid for: 60 days after issue if settlement or occupancy has not occurred","Recent signed and sealed survey for all single family homes (not required for condos); one issued within the past 60 days is recommended","All open construction permits must be closed before the certificate is issued","House number on the building itself, at least 30 inches above ground, at least 3 inches tall, on a contrasting background, visible from the street; stick-on numbers not accepted","Carbon monoxide alarm outside and within 10 feet of every sleeping area; extra alarm if a bedroom is on another level or more than 10 feet away","Smoke alarms per the year the home was approved; battery-only alarms must be 10-year sealed units","A hardwired or monitored alarm system cannot be reverted to battery-only alarms; monitored systems must be put in test mode for the inspection","No zoning violations; any addition or accessory structure built without zoning or construction permits must be brought into compliance first","Pool fencing and gates must meet Section 305 of the International Swimming Pool and Spa Code","Someone must be present unless the property is completely empty; inaccessible areas fail the inspection","Tax assessor property record card is checked during the inspection","Also: Open permits must be closed: The resale form requires Township sign-off that all outstanding permits for the property have been closed and finalized before the certificate is issued.","Also: Survey: A current signed and sealed survey must be reviewed before the Resale Certificate can be issued (single family homes; not condos).","Also: Zoning compliance: Any zoning violation, including an addition or accessory structure built without permits, must be resolved before the certificate is issued."]$j$::jsonb, $j$[{"label":"Inspection requested more than 10 business days after application","amount":"$75.00"},{"label":"Inspection requested 2 to 10 business days after application","amount":"$125.00"},{"label":"Inspection requested 1 to 2 business days after application","amount":"$150.00"},{"label":"Inspection requested the same day as application","amount":"$200.00"},{"label":"First re-inspection (also charged when any part of the property is inaccessible)","amount":"$75"},{"label":"Each later re-inspection","amount":"$150"}]$j$::jsonb, $t$https://voorheesnj.com/wp-content/uploads/2024/01/Residential-Resale-Application-7.02.2026.pdf$t$, $t$https://voorheesnj.com/departments/zoning/$t$, $j$[{"url":"https://voorheesnj.com/departments/zoning/","label":"Official source (voorheesnj.com)"},{"url":"https://voorheesnj.com/wp-content/uploads/2024/01/Residential-Resale-Application-7.02.2026.pdf","label":"Official source (voorheesnj.com)"},{"url":"https://voorheesnj.com/departments/construction/","label":"Official source (voorheesnj.com)"},{"url":"https://www.vtfd66.org/wp-content/uploads/2023/10/townshipord2023.pdf","label":"Official source (vtfd66.org)"}]$j$::jsonb, $t$If you are selling your home, the presence of an unpermitted improvement (a violation) may delay settlement since a resale certificate cannot be issued for a transfer of ownership while a violation exists.$t$, $t$3b73b3b2ed47995264c5eeac10ebb36b4138cec0a885080e8f2d05f5f2ce830b$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":9,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0434.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0434.json$t$, true),
  ($t$0434$t$, $t$Voorhees Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Voorhees Township Planning & Zoning Department (residential smoke/CO inspections, done with the resale certificate inspection) (town fire bureau)","Contact: Thomas O'Brien, Fire Official, Voorhees Township Fire Department (fire code enforcing agency); residential smoke inspections are done… · 856-429-0647 · resales@voorheesnj.com","Apply: Same as the resale certificate; see resale fee tiers","How to apply: Use the Residential Resale Application from the Zoning Department; the smoke and CO alarm check is part of that inspection.","Fire official in the NJ state directory, updated 5/26/2026: Thomas O'Brien · (856) 783-6630 · tom.Obrien@vtfd66.org","Battery-only smoke alarms must be 10-year sealed units (Voorhees resale packet and Fire Department page)","Carbon monoxide alarm within 10 feet of each sleeping area","Hardwired or monitored alarm systems cannot be downgraded to battery-only alarms","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://voorheesnj.com/wp-content/uploads/2024/01/Residential-Resale-Application-7.02.2026.pdf$t$, $t$https://www.vtfd66.org/fire-prevention/inspection-bureau/$t$, $j$[{"url":"https://www.vtfd66.org/fire-prevention/inspection-bureau/","label":"Official source (vtfd66.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SMOKE DETECTOR INSPECTIONS FOR RESIDENTIAL PROPERTIES ARE COMPLETED THROUGH THE VOORHEES TOWNSHIP ZONING DEPARTMENT.$t$, $t$7139553be45e86aead02699fda09e4abc25fe04377f5ca2ad084657b9acbc464$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":9,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0434.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0434.json$t$, true),
  ($t$0435$t$, $t$Waterford Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Reoccupancy Inspection (Residential Resale Inspection); Certificate of Inspection$t$, $j$["Issued by: Waterford Township (form posted by the Construction & Zoning Enforcement office; the Township code lists it as a fire prevention smoke and CO inspection fee)","Contact: Craig Fallstick, Fire Official (DCA fire directory); the Township form gives no named contact · 856-768-2300 ext. 307 · fireofficial@waterfordtwp.org","Apply: Apply at least 10 days before settlement for the lowest fee","How to apply: Fill out the Residential Reoccupancy Inspection form (settlement date, block, lot, lock box code and location, owner, buyer and realtor contacts) and submit it to Waterford Township, 2131 Auburn Ave, Atco, NJ 08004. Pay by cash, check or money order. Include passed water and septic certifications.","Valid for: 30 days","Smoke alarm on each floor including the basement and within 10 feet of a bedroom","Battery smoke alarms must be 10-year sealed; hardwired (110 volt) alarms cannot be replaced with battery alarms","Smoke alarms less than 10 years old (or per manufacturer replacement date)","Carbon monoxide alarm within 10 feet of a bedroom, less than 5 years old (or per manufacturer)","House number visible from the street, 3 to 6 inches tall","Passed water and septic certifications must be submitted before the certificate is released","A house with a cesspool cannot be sold until a septic system is installed; if a new system is needed, show money in escrow","Secondary power (meter and electrical panels) and all utilities on and working (listed on the 2025 form)","Do not take Township trash and recycling carts and do not leave trash at the curb","Also: Water and septic certifications: Passed water and septic certifications must be submitted before the Township releases the certificate (mark public water, private well, public sewer or septic).","Also: Cesspool replacement: A house with a cesspool cannot be sold until a septic system is installed; if a new system is needed, proof of escrowed funds is required."]$j$::jsonb, $j$[{"label":"Inspection, applied 10 days before settlement","amount":"$75"},{"label":"Inspection, applied 4 to 9 days before settlement","amount":"$125"},{"label":"Inspection, applied 2 to 3 days before settlement","amount":"$200"},{"label":"Re-inspection","amount":"$50"}]$j$::jsonb, $t$https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf$t$, $t$https://waterfordtwp.org/departments/construction-zoning-enforcement/$t$, $j$[{"url":"https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf","label":"Official source (waterfordtwp.org)"},{"url":"https://waterfordtwp.org/departments/construction-zoning-enforcement/","label":"Official source (waterfordtwp.org)"},{"url":"https://waterfordtwp.org/wp-content/uploads/2025/09/NEW-CO.pdf","label":"Official source (waterfordtwp.org)"},{"url":"https://ecode360.com/7192375","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$***PASSED WATER AND SEPTIC CERTIFICATIONS MUST BE SUBMITTED BEFORE WE RELEASE CO***$t$, $t$a7ceda7f562c0e1bf2703ff84eb2c35048a238555116f8d2513ee9524dee4fee$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0435.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0435.json$t$, true),
  ($t$0435$t$, $t$Waterford Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Waterford Township Fire Prevention (municipal local enforcing agency, Fire Official Craig Fallstick) (town fire bureau)","Contact: Craig Fallstick, Fire Official · 856-768-2300 · fireofficial@waterfordtwp.org","Apply: Apply at least 10 days before settlement for the lowest fee; certificate good for 30 days","How to apply: Use the Township Residential Reoccupancy Inspection form; the smoke and CO alarm certificate is issued from that inspection.","Fire official in the NJ state directory (town), updated 8/17/2026: Craig Fallstick · (856) 768-2300 · fireofficial@waterfordtwp.org","Smoke alarms less than 10 years old (or per manufacturer replacement date)","Carbon monoxide alarms less than 5 years old (or per manufacturer replacement date)","Battery smoke alarms must be 10-year sealed; hardwired alarms cannot be swapped for battery units","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Same combined reoccupancy inspection fee (pay once), applied 10 days before settlement","amount":"$75"},{"label":"Same combined reoccupancy inspection fee (pay once), applied 4 to 9 days before settlement","amount":"$125"},{"label":"Same combined reoccupancy inspection fee (pay once), applied 2 to 3 days before settlement","amount":"$200"},{"label":"Re-inspection","amount":"$50"}]$j$::jsonb, $t$https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf$t$, $t$https://waterfordtwp.org/departments/construction-zoning-enforcement/$t$, $j$[{"url":"https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf","label":"Official source (waterfordtwp.org)"},{"url":"https://ecode360.com/7192375","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/7192448","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Inspection will only be issued when the premises meet the minimum requirements of the New Jersey State Uniform Fire Code, N.J.A.C. 5:70-4:19.$t$, $t$343d04d5e940f480cc79047111028e220935b59d82030df73d7f412a61a1f2c4$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0435.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0435.json$t$, true),
  ($t$0436$t$, $t$Winslow Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate / Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Winslow Township Construction Official (Housing Office)","Contact: 609-567-0700 option 5 · construction@winslowtownship.com","Apply: Payment must come with the application; check payments need a 10 working day hold before the inspection. The code says the inspection is made within 10 working days of a complete application and fee.","How to apply: Complete the Resale Certificate Application (seller, buyer, both agents, settlement date, block and lot) and submit it with payment to the Housing Office, Township of Winslow, 125 South Route 73, Braddock, NJ 08037. Attach well and septic certifications if they apply. Schedule the inspection by calling 609-567-0700, option 5 (Monday to Friday, 8:30 am to 4:30 pm).","Well water: passing test by an NJDEP certified lab (Private Well Testing Act), or Camden County Health Dept. letter of approval for a new well","Septic: Camden County Health Dept. letter of compliance (no future action), or certificate of compliance for a new system","Property must comply with all Township and State codes and ordinances (the Township adopts the International Property Maintenance Code)","Sidewalks and driveway aprons are the owner's responsibility and must meet Township ordinances","All open permits closed with final inspections (for example water heater, A/C, furnace, finished basement)","Dwelling must be fit for human habitation","Certificate issued only when all requirements are met","Separate fire (smoke/CO) certificate from the Winslow Township Fire District is also required","The buyer may take over the seller's responsibility for the certificate with a written waiver filed with the Construction Official","Also: Well and septic certifications: If the property has a well or septic system, the certifications must accompany the Township resale application (NJDEP certified lab well test or County Health letter; County Health septic compliance letter).","Also: Open permits must be closed: All open permits must be closed with final inspections before the Township issues the certificate.","Also: Sidewalks and aprons: Sidewalks and driveway aprons are the homeowner's responsibility and must comply with Township ordinances."]$j$::jsonb, $j$[{"label":"Residential inspection (includes 1 free re-inspection)","amount":"$100"},{"label":"Commercial inspection (includes 1 free re-inspection)","amount":"$200"},{"label":"Each re-inspection after the first free re-inspection","amount":"$50"}]$j$::jsonb, $t$https://www.winslowtownship.com/filestorage/3308/3536/3538/3540/RESALECERTIFICATE.pdf$t$, $t$https://www.winslowtownship.com/content/3298/3503/default.aspx$t$, $j$[{"url":"https://www.winslowtownship.com/content/3298/3503/default.aspx","label":"Official source (winslowtownship.com)"},{"url":"https://www.winslowtownship.com/filestorage/3308/3536/3538/3540/RESALECERTIFICATE.pdf","label":"Official source (winslowtownship.com)"},{"url":"https://ecode360.com/35704976","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Our office also performs rental inspections and CCO inspections for resale property, Monday thru Friday.$t$, $t$9e2cd3e8d06fde7f4af87a00c4ae09d22facd27c0db6dcfcf28a04c2eac5cbf4$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0436.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0436.json$t$, true),
  ($t$0436$t$, $t$Winslow Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Winslow Township Fire District No. 1 (Winslow Township Fire Department), Fire Prevention Division / Office of the Fire Marshal (fire district)","Contact: Joseph G. Hahn, Fire Official (Winslow Township and Chesilhurst Borough) · 609-561-4225 · firedistrict@winslowtwpfd.org","Apply: Apply 3 to 4 weeks before closing (recommended); fee depends on days of notice; certificate valid 90 days from inspection","How to apply: Apply online on the Fire District website and then pay through the linked Edmunds WIPP payment page, or download the packet and fax it to 609-561-5823, or apply in person at the Fire District Office, 9 Cedar Brook Road, Sicklerville (Monday to Friday, 9 am to 5 pm). Staff contact you to schedule. Inspections are on Tuesdays and Thursdays in a morning or afternoon block. Pay by check (payable to Winslow Township Fire District), credit card, debit card or money order. All fees are non-refundable.","Fire official in the NJ state directory (fire district), updated 2/6/2026: Joseph G Hahn · (609) 561-4225 · josephh@winslowtwpfd.org","Every smoke alarm must be less than 10 years old; take each alarm down and check the date on the back","Battery (DC) smoke alarms must be 10-year sealed units","Hardwired (110 volt) interconnected alarms must all sound when one is tested; AC power must be on or no inspection is done; replacing a hardwired alarm with a battery unit fails","Smoke alarm type and number depend on the year built (for example 1991 to present: hardwired with battery backup on each level and in each bedroom, interconnected)","CO alarm outside of but within 10 feet of all sleeping areas if there is any fuel-burning appliance, fireplace or attached garage","Homes with a secondary power source (solar, generator, battery storage) need a permanent, not handwritten, 'Caution: Multiple Sources of Power' label at the main panel and the electric meter (ANSI Z535.4)","Monitored low-voltage fire alarm systems must be tested and certified by an alarm contractor before the inspection; bring the certificate","An adult (18+) must be present for the whole inspection; no lockbox entry","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Application, 8 or more days advance notice","amount":"$65.00"},{"label":"Application, 4 to 7 days advance notice","amount":"$100.00"},{"label":"Application, 3 or fewer days notice","amount":"$150.00"},{"label":"Senior citizen (62 or older, proof of age attached) discount line","amount":"$30.00"},{"label":"Re-inspection (per visit)","amount":"$35.00"},{"label":"Missed appointment","amount":"$35.00"}]$j$::jsonb, $t$https://winslowtwpfd.org/online-resale-application$t$, $t$https://winslowtwpfd.org/fire-marshal-office$t$, $j$[{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/Smoke_Application_2025.pdf","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/CSDCMACPFE_Instructions_4.15.2025.pdf","label":"Official source (winslowtwpfd.org)"},{"url":"https://www.winslowtownship.com/filestorage/3308/3536/3538/3540/RESALECERTIFICATE.pdf","label":"Official source (winslowtownship.com)"},{"url":"https://winslowtwpfd.org/online-resale-application","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/history","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/fire-marshal-office","label":"Official source (winslowtwpfd.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$CERTIFICATIONS ARE VALID FOR 90 DAYS FROM THE DATE OF INSPECTION$t$, $t$398bd2c7f836709ae267b41196a6490c6c300d12e61ae481243c89862c966ba6$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0436.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0436.json$t$, true),
  ($t$0437$t$, $t$Woodlynne Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection for Resale (resale certificate of occupancy)$t$, $j$["Issued by: Borough of Woodlynne Construction Official (form); the Borough code also calls for a zoning certificate of occupancy from the Zoning Officer on a change of occupants by sale","Contact: Bill Lunemann, Contact named on the resale application (no title shown) · 856-962-8300 ext. 219 · William.lunemann@woodlynne.org","How to apply: Fill out the Application for Certificate of Inspection for Resale (building address, owner, agent or contractor, email) and return it to the Borough of Woodlynne, 200 Cooper Ave., Woodlynne, NJ 08107, or fax it to 856-962-8763. Contact Bill Lunemann at 856-962-8300 ext. 219.","Inspection for resale, marked pass or fail by the Construction Official","Any building, plumbing, electrical or fire permits the Construction Official requires must be completed before the final Certificate of Occupancy","Under the Borough code, the new owner must get a certificate of occupancy from the Zoning Officer showing the intended use meets Borough zoning","Also: Zoning certificate of occupancy: On a change of occupants by sale, the new owner must get a certificate of occupancy from the Zoning Officer confirming the use meets Borough zoning (Code section 480-2A(1)). It may be the same document as the resale certificate; confirm with the Borough.","Also: Open permits: Any building, plumbing, electrical or fire permits the Construction Official requires must be completed before the final Certificate of Occupancy."]$j$::jsonb, $j$[{"label":"Application for Certificate of Inspection for Resale","amount":"$96.00"}]$j$::jsonb, $t$https://www.woodlynnenj.org/_files/ugd/b7bd99_eff4bcd5931549398dc38abfbdfb47b2.pdf$t$, $t$https://www.woodlynnenj.org/code-enforcement$t$, $j$[{"url":"https://www.woodlynnenj.org/_files/ugd/b7bd99_eff4bcd5931549398dc38abfbdfb47b2.pdf","label":"Official source (woodlynnenj.org)"},{"url":"https://www.woodlynnenj.org/code-enforcement","label":"Official source (woodlynnenj.org)"},{"url":"https://ecode360.com/35957746","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Application for Certificate of Inspection for Resale$t$, $t$2ff6198acdbd4ad73a446f579f793ec68f7c45b10d9d2266a4582cacdbfa8305$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0437.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0437.json$t$, true),
  ($t$0437$t$, $t$Woodlynne Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106","Apply: Fee depends on how many business days before the change of occupant the request is received: more than 10 business days for the lowest fee.","How to apply: Apply, schedule and pay online through the NJ DCA fire service portal (firesolutions.dca.nj.gov), using 'Apply for Smoke Certification'.","Fire official in the NJ state directory (NJ DCA, state), updated 3/14/2023: Louis Kilmer · (609) 633-6132","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-4.19 for 1 and 2 family homes (the Borough and DCA pages found do not list the details)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$LEAID: 0437-999 Woodlynne Boro SMOKE DETECTOR COMPLIANCE Name: NJ Division of Fire Safety Enf Auth. State Fire Official Louis Kilmer Phone (609) 633-6132$t$, $t$25dfd3f88207dc0ae80c0e27357c4fbe2eec8264d19270da9b24c20276695b8e$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0437.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0437.json$t$, true),
  ($t$0502$t$, $t$Cape May$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy, Certificate of Zoning Compliance and Certificate of Flood Damage Prevention Compliance$t$, $j$["Issued by: City of Cape May Construction & Zoning Office (Construction Official, Zoning Officer and Floodplain Manager)","Contact: Lou Vito Jr, Plumbing Subcode Official / Construction Official · 609-884-9555 · construction@capemaycity.com","Apply: Apply at least 15 business days before the transfer of title","How to apply: Submit the Certificate of Zoning Compliance Application (block, lot, zoning district, current and new owners, use, number of units, settlement date) and the Certificate of Flood Damage Prevention Compliance Application (with an elevation certificate if the property is in a flood zone), each with its fee, to the Construction & Zoning Office, City Hall, 643 Washington Street, Cape May, NJ 08204, at least 15 business days before closing. No separate Certificate of Continued Occupancy form was found online; ask the Construction Office (609-884-9555, construction@capemaycity.com) how to request it.","Valid for: Certificate of continued occupancy and flood certificate: 2 years from issuance (the continued occupancy certificate expires on the date of transfer)","Certificate of Continued Occupancy (Code Section 199-7): inspection showing no work done without a construction permit, no open construction permits, and no unsafe or unsanitary conditions, blocked exits or fire hazards","Certificate of Zoning Compliance (Code Section 199-5): inspection confirming no change of use and that the use and number of units comply with the Zoning Ordinance; the certificate also gives notice of the property's historic district status","Certificate of Flood Damage Prevention Compliance (Code Section 199-6): checks the minimum number of flood vents; a flood elevation certificate must be submitted if the property is in a flood zone (one issued on or after January 1, 2010 is accepted)","Violations found must be fixed before closing, unless the buyer signs an acknowledgment, assumes the risk and agrees to fix them within 30 days (30 business days for the flood certificate) after closing","Exceptions: new construction with a certificate of occupancy issued within 2 years of the transfer, transfers without payment to a related person or entity, buyer certifies demolition within 90 days, and foreclosure transfers to a lender","Separate smoke/CO certificate from the Bureau of Fire Prevention (see fire certificate)","Also: Certificate of Zoning Compliance and Certificate of Flood Damage Prevention Compliance: Both are required before transfer of title along with the Certificate of Continued Occupancy (see the town certificate). The flood certificate needs a flood elevation certificate if the property is in a flood zone.","Also: Open construction permits: The Certificate of Continued Occupancy certifies there are no open construction permits and no work done without a permit, so open permits should be closed before closing."]$j$::jsonb, $j$[{"label":"Certificate of Zoning Compliance application","amount":"$85.00"},{"label":"Certificate of Flood Damage Prevention Compliance application","amount":"$85"},{"label":"Certificate of Continued Occupancy (Code Section 199-8A(7))","amount":"$85"},{"label":"Certificate of Continued Occupancy, each subcode inspection (Code Section 199-8A(7))","amount":"$50"}]$j$::jsonb, $t$https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/3/media/734.pdf$t$, $t$https://www.capemaycity.com/departments/ConstructionZoning$t$, $j$[{"url":"https://ecode360.com/6658125","label":"Official source (ecode360.com)"},{"url":"https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/3/media/734.pdf","label":"Official source (evocloud-prod3-public.s3.us-east-2.amazonaws.com)"},{"url":"https://www.capemaycity.com/media/Flood%20Information/Flood%20Damage%20Prevention%20Compliance%20Application%202020.pdf","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/forms-center","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/departments/ConstructionZoning","label":"Official source (capemaycity.com)"}]$j$::jsonb, $t$Transfer of building, structures, or units. No person or entity shall sell or transfer title to any building, structure, portion of structure, or unit in a structure until such person or entity shall have first requested and obtained a certificate of continued occupancy certifying as follows:$t$, $t$ed719f9a130b3077a7aec350c668f11c8ba26014a99f27a410ae2722392f57f9$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":24,"q_ok":15,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0502.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0502.json$t$, true),
  ($t$0502$t$, $t$Cape May$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Cape May Bureau of Fire Prevention (town fire bureau)","Contact: Mark Barham, Fire Official · 609-884-9587 · mbarham@capemaycity.com","Apply: Apply more than 10 business days before settlement for the lowest fee. The certificate is valid for 180 days from the inspection and is not transferable.","How to apply: Fill out the Sale of Property Form (check the Certificate of Smoke Alarm, Carbon Monoxide Alarm option for 1-2 family dwellings, give the closing date and agent/title contact) and send it to the Bureau of Fire Prevention, fireprevention@capemaycity.com, 609-884-9599. Do not send payment with the application; the fee is set when the form is received and the Bureau invoices it (fire invoices can be paid online through the City's Tyler portal).","Fire official in the NJ state directory (town), updated 7/22/2026: Mark C Barham · (609) 884-9599 · mbarham@capemaycity.com","Sale of Property Form (created March 2025) still names the certificate as covering a portable fire extinguisher, but the Bureau's web page says fire extinguishers are no longer required in one- or two-family dwellings for sales or rentals; if one is kept it must be maintained (approved hanger, serviced within 12 months)","Smoke alarms no older than 10 years; battery-only smoke alarms must be the 10-year sealed battery type (listed on the Bureau page as top rental violations)","Carbon monoxide alarm near sleeping areas and on every level when there are fuel-burning appliances, an attached garage or a fireplace","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (1-2 family), application received more than 10 business days from settlement","amount":"$150"},{"label":"Smoke/CO certificate (1-2 family), application received 4 to 10 business days from settlement","amount":"$250"},{"label":"Smoke/CO certificate (1-2 family), application received fewer than 4 business days from settlement","amount":"$375"}]$j$::jsonb, $t$https://www.capemaycity.com/media/Fire%20Prevention/Sale%20of%20Property%20Form.pdf$t$, $t$https://www.capemaycity.com/departments/FirePrevention$t$, $j$[{"url":"https://ecode360.com/6658355","label":"Official source (ecode360.com)"},{"url":"https://www.capemaycity.com/media/Fire%20Prevention/Sale%20of%20Property%20Form.pdf","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/departments/FirePrevention","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/departments/staff_directory/FirePrevention/","label":"Official source (capemaycity.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Beginning in 2018, and continuing for each year thereafter, all 1 & 2 Family Dwellings shall be inspected prior to the sale of property.$t$, $t$c91ea336a8a1f22bb8c87bbc12a2d49de3d74ee35231d4e8d3c217b3f236df4d$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":24,"q_ok":15,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0502.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0502.json$t$, true),
  ($t$0503$t$, $t$Cape May Point Borough$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Land Use Compliance (Certificate of Compliance)$t$, $j$["Issued by: Zoning Official, Borough of Cape May Point","Contact: Bruce Britton, Zoning Official · 609-884-8468 x16 · bbritton@capemaypoint.org","Apply: Issued or rejected within 10 business days of receiving the application","How to apply: Fill out the Certificate of Compliance Application (name, mailing address, unit, street address, block, lot, date of settlement, and a key or lock box code for the interior inspection) and send it with the $100.00 per unit fee to the Office of the Zoning Official, Borough of Cape May Point, PO Box 490, Cape May Point, NJ 08212 (215 Lighthouse Avenue). Office hours are 4:00 PM to 6:00 PM Tuesday and Wednesday only.","Valid for: 180 days after issuance, for one transfer only","Inspection of the premises by the Zoning Officer to confirm the structure or unit complies with the Borough Zoning Ordinance (Chapter 150); the Tax Assessor may come along to update the property record","The certificate confirms the property may continue to be used as before and lists the number and designation of units","Interior inspection: send a key or give a lock box code with the application","Not needed for new construction whose original certificate of occupancy was issued within 18 months of the transfer","A tenant under an existing lease may stay, but title may not transfer until the certificate is issued"]$j$::jsonb, $j$[{"label":"Certificate of Land Use Compliance inspection, per unit (not over $300 per building)","amount":"$100.00"}]$j$::jsonb, $t$https://capemaypoint.org/uploaded_files/document/Certificate%20of%20Compliance%20Application.pdf$t$, $t$https://capemaypoint.org/zoning.php$t$, $j$[{"url":"https://ecode360.com/35935568","label":"Official source (ecode360.com)"},{"url":"https://capemaypoint.org/uploaded_files/document/Certificate%20of%20Compliance%20Application.pdf","label":"Official source (capemaypoint.org)"},{"url":"https://capemaypoint.org/zoning.php","label":"Official source (capemaypoint.org)"}]$j$::jsonb, $t$No person, persons or organization of persons shall sell or transfer title to any structure, portion of a structure or unit in a structure until such person, persons or organization of persons shall have first obtained a certificate of land use compliance certifying:$t$, $t$e4cda95034a1a402b69e09edb7e264ad820d5a6ad05936a96312e448fbb961c4$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0503.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0503.json$t$, true),
  ($t$0503$t$, $t$Cape May Point Borough$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency and issues smoke certificates) (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before closing for the lowest fee","How to apply: Apply online through the DCA Fire Safety portal ('Start Your Smoke Certification Application'). Payment by e-check or credit card is required before submitting, and a valid email address is required. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 7/31/2026: Louis Kilmer · (609)633-6132","The State application certifies smoke alarms, carbon monoxide alarms and the secondary power source identification label (homes with solar, generators or battery systems); it no longer lists a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45.00"},{"label":"4 to 10 business days before closing","amount":"$90.00"},{"label":"Fewer than 4 business days before closing","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Cape May Point Borough$t$, $t$921cc341424fabe25856a5b9a98aa2fea15ab513b1ac264ca322187dcd15ff0a$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0503.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0503.json$t$, true),
  ($t$0506$t$, $t$Middle Township$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Middle Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Daniel Speigel, Construction Official · 609-465-8740 · dspeigel@middletownship.com","Also: Open construction permits: The fire bureau will not issue the smoke/CO certificate while any construction permit is open."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://middletownship.com/departments/contruction/$t$, $j$[{"url":"https://middletownship.com/departments/contruction/","label":"Official source (middletownship.com)"}]$j$::jsonb, $t$Please be advised that the Township of Middle DOES NOT issue a Certificate of Occupancy or a Zoning Certificate for the transfer of a property/business nor for the renting of a property. The only time a Certificate of Occupancy is issued is at the origination of the building, change of use, reconstruction or an addition per the Uniform Construction Code 5:23-2.24.$t$, $t$8a3075732f6303d9b25610b67db6aa58953514da4924db4bf26edcd41ee4feb3$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0506.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0506.json$t$, true),
  ($t$0506$t$, $t$Middle Township$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bureau of Fire Prevention, Middle Township Fire Districts (run by Fire District #1) (fire district)","Contact: Douglas Greenberg, Fire Official (per state fire directory) · 609-465-8710 · firebureau@cmchfire.com","Apply: Apply more than 10 days before closing for the lowest fee; the certificate must be used within six months","How to apply: Download the 2025 Home Sale Application Packet (CSACMAPFEC) from the Fire District 1 Forms page, complete and initial all 4 pages (seller must sign), and submit it with a check or money order payable to Bureau of Fire Prevention to 115 Mechanic Street, Cape May Court House, NJ 08210 (firebureau@cmchfire.com, 609-465-8710). Forms dated before August 2025 are not accepted. Applications left in the mailbox count as received the next business day. Office hours Monday to Thursday 8:00am to 4:00pm, Friday 8:00am to 1:00pm.","Fire official in the NJ state directory (fire district), updated 8/17/2026: Douglas Greenberg · (609) 465-8710 · greenbergdm@cmchfire.com","Smoke alarms by year built: before 1977, 10-year sealed battery alarms on each level and outside each sleeping area; newer homes need AC-powered (hardwired) alarms per the construction code of their year, interconnected from August 1984, and in each bedroom with battery backup from March 1991","Do not replace AC-powered alarms with battery alarms; alarms over 10 years old (or with no date) must be replaced; no tape or velcro mounting","Low-voltage fire alarm systems in homes built 1977 or later must be kept and tested by a NJ licensed alarm contractor, with the passed report sent to the Bureau before the inspection; systems installed 2011 or later must be monitored","CO alarm (UL 2034) in the hallway within 10 feet of each sleeping area when there is a fuel-burning appliance or attached garage, plus one in any bedroom with a fuel-burning appliance; not more than 10 years old","Portable fire extinguisher 2-A:10-B:C, no larger than 10 lbs, new or tagged within 12 months, on the manufacturer's bracket within 10 feet of the kitchen, top no higher than 5 feet (still listed in the 2025 packet)","Secondary power source label within 18 inches of the main electrical panel and meter for homes with solar, backup generators or batteries","Certificate will not be issued if there are any open construction permits","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate, application received more than 10 days prior to closing","amount":"$78.00"},{"label":"Certificate, application received 4 to 10 days prior to closing","amount":"$115.00"},{"label":"Certificate, application received less than 4 days prior to closing","amount":"$210.00"},{"label":"Reinspection","amount":"$75.00"}]$j$::jsonb, $t$https://assets.zyrosite.com/m6LZvpK60zuj57RE/2025-csacmapfec-application-packet-1-mjEGJvOnNVH91QGq.pdf$t$, $t$https://middletownshipfiredistrict1.com/forms$t$, $j$[{"url":"https://assets.zyrosite.com/m6LZvpK60zuj57RE/2025-csacmapfec-application-packet-1-mjEGJvOnNVH91QGq.pdf","label":"Official source (assets.zyrosite.com)"},{"url":"https://middletownshipfiredistrict2.com/","label":"Official source (middletownshipfiredistrict2.com)"},{"url":"https://assets.zyrosite.com/m6LZvpK60zuj57RE/bureau-hours-door-sign-Y4LDBO7RJjIMXgol.pdf","label":"Official source (assets.zyrosite.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$BUREAU OF FIRE PREVENTION MIDDLE TOWNSHIP FIRE DISTRICTS #1, 3 & 4 115 Mechanic Street Cape May Court House, NJ 08210 O: 609.465.8710 F: 609.465.3851 firebureau@cmchfire.com$t$, $t$324ff38370e2f95c5447fd152445ba7bb0f042aefff58a9992e1dd02e2e6b4b3$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0506.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0506.json$t$, true),
  ($t$0507$t$, $t$North Wildwood$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Zoning Use Compliance$t$, $j$["Issued by: Planning & Zoning (Zoning Officer)","Contact: Daniel Speigel, Construction Official/Fire Official/Zoning Officer · 609-522-2030 Ext. 1562 · dspeigel@northwildwood.com","Apply: Apply more than 10 business days before the certificate is needed for the lowest fee","How to apply: Fill out the Application for Certificate of Zoning Use Compliance (page 1 of the City's 'Forms required for sale of properties'), with property, seller/agent, owner and buyer details, settlement date, current use and number of units, and key or access code. Pay by check (a separate check from the fire certificate), exact cash, or credit card with a 2.75% surcharge, at City Hall, 901 Atlantic Avenue, North Wildwood, NJ 08260.","Zoning review that the current use (single family, two-family, multi-family and number of units) is permitted or a legal preexisting nonconforming use","Owner of record signs the application and discloses, under oath, all permitted or preexisting nonconforming uses and structures on the property (City Code Section 276-85)","Also: Certificate of Zoning Use Compliance: Required before a sale or transfer; separate application and check from the fire certificate. See the town certificate."]$j$::jsonb, $j$[{"label":"Zoning certificate, requested more than 10 business days before needed","amount":"$50.00"},{"label":"Zoning certificate, requested 4 to 9 days before needed","amount":"$70.00"},{"label":"Zoning certificate, requested less than 4 days before needed","amount":"$125.00"}]$j$::jsonb, $t$https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf$t$, $t$https://northwildwood.com/departments/construction-office/$t$, $j$[{"url":"https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf","label":"Official source (northwildwood.com)"},{"url":"https://northwildwood.com/public-safety/fire-housing-bureau/","label":"Official source (northwildwood.com)"},{"url":"https://ecode360.com/37124931","label":"Official source (ecode360.com)"},{"url":"https://northwildwood.com/departments/construction-office/","label":"Official source (northwildwood.com)"}]$j$::jsonb, $t$Application for Certificate of Zoning Use Compliance$t$, $t$acdc7fe918dbd1e6ae4f9ba71197ce48e2d16ad1d1c776a8126759385c1208d7$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0507.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0507.json$t$, true),
  ($t$0507$t$, $t$North Wildwood$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Wildwood Fire & Housing Bureau (Fire Prevention Bureau) (town fire bureau)","Contact: Daniel Speigel, Fire Official · 609-522-2160 · dspeigel@northwildwood.com","Apply: Apply more than 10 business days before settlement for the lowest fee; do not submit until all items are in place","How to apply: Fill out the Application for a Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (page 2 of 'Forms required for sale of properties'), note keys or lock box code, and submit with a separate check (or exact cash, or credit card with a 2.75% surcharge) to the Fire & Housing Bureau, 901 Atlantic Ave., North Wildwood (609-522-2160, fireinspector@northwildwood.com). Smoke detector applications are taken Monday to Friday 8AM to 4PM.","Fire official in the NJ state directory, updated 2/13/2025: Daniel F Speigel · (609) 522-2030 · dspeigel@northwildwood.com","Smoke alarms in each sleeping room, within 10 feet outside each sleeping area, and on every level","Hardwired smoke alarms older than 10 years must be replaced; battery smoke alarms must be the 10-year sealed battery type","CO alarms within 10 feet outside each sleeping area and on every level when there are fuel-burning appliances or an attached garage","Fire extinguisher at least 2A:10BC, new (current year) or tagged by a licensed agent, for each cooking area, hung in a visible spot or labeled cabinet (still listed on the March 2026 form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke / CO alarm and extinguisher certificate, per unit, applied more than 10 business days before settlement","amount":"$45.00"},{"label":"Smoke / CO alarm and extinguisher certificate, per unit, applied 4 to 10 business days before settlement","amount":"$90.00"},{"label":"Smoke / CO alarm and extinguisher certificate, per unit, applied less than 4 business days before settlement","amount":"$161.00"},{"label":"Re-inspection (same as the first inspection fee, by timing)","amount":"$45.00 to $161.00"},{"label":"Fire Code Status Report, for properties registered and inspected annually only","amount":"$25.00"}]$j$::jsonb, $t$https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf$t$, $t$https://northwildwood.com/public-safety/fire-housing-bureau/$t$, $j$[{"url":"https://northwildwood.com/public-safety/fire-housing-bureau/","label":"Official source (northwildwood.com)"},{"url":"https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf","label":"Official source (northwildwood.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Department Head: Daniel Speigel Fire Official$t$, $t$909008a980cfd3005f7f76ebbf8713bd1392b796da7907ff07ca1ffd5eda78fe$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0507.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0507.json$t$, true),
  ($t$0508$t$, $t$Ocean City$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Zoning Compliance Certification (homes built after January 1, 1996 only)$t$, $j$["Issued by: City of Ocean City (requested on the same sale-of-property inspection application; Zoning Office)","Contact: Jessica Fenton, Zoning Official · 609-399-6111 ext 9759 · jfenton@ocnj.us","How to apply: Use the City's Sale of Property inspection application (the same form as the smoke/CO certificate); give the date of the final CO (year built) so the City knows zoning certification is needed. Send it to 115 12th Street, Ocean City, NJ 08226, (609) 399-6111 x 9727, smokedetector@ocnj.us.","Zoning compliance check at the in-person sale inspection, for homes built after January 1, 1996","Also: Zoning Compliance Certification for homes built after January 1, 1996: Required on sale per the City's 2025 sale inspection form; see the town certificate."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf$t$, $t$https://www.ocnj.us/zoning$t$, $j$[{"url":"https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/departments/staff_directory/Administration/","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/zoning","label":"Official source (ocnj.us)"}]$j$::jsonb, $t$Homes built after January 1, 1996 also require Zoning Compliance Certification.$t$, $t$7b208924a6ddef427db7b37726961f2077978dea4fad8177c58ed66b56043f38$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0508.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0508.json$t$, true),
  ($t$0508$t$, $t$Ocean City$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Ocean City Division of Fire Prevention (Municipal Code, Licensing and Fire Prevention, Knight Building) (town fire bureau)","Contact: 609-399-6111 ext. 9727 · smokedetector@ocnj.us","Apply: Book before closing; inspections Monday to Friday 9am to 3pm at scheduled times","How to apply: Fill out the Inspection Request: Sale of Property Application for Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance (closing date, requested inspection date and time, access: meet owner/agent/tenant or lock box code, buyer and agent details, year of final CO). Submit to 115 12th Street, Ocean City, NJ 08226, call 609-399-6111 ext. 9727, or email smokedetector@ocnj.us. Payment by mail, in person or online. The seller or the seller's agent must get it before the sale or transfer of title.","Fire official in the NJ state directory (NJ DCA, state), updated 2/13/2025: Louis Kilmer · (609)633-6132","Homes built before 1977: 10-year sealed battery smoke alarms on each level and outside each sleeping area","Built January 1977 to February 21, 1983: hardwired (120 volt) smoke alarms on each level and near each sleeping area (interconnection not required)","Built February 22, 1983 to April 30, 1993: hardwired multi-station smoke alarms on each level and near each sleeping area, interconnected","Built May 1, 1993 to present: hardwired interconnected smoke alarms with battery backup in all bedrooms, outside each sleeping area and on every level","CO alarms (UL 2034) near sleeping areas when there are fuel-burning devices or an attached garage","Portable fire extinguisher 2A-10B:C for the sale of 1-2 family units, on its bracket within 10 feet of the kitchen in the path of egress, top no more than 5 feet up (City requirements sheet dated February 2024, before P.L.2025, c.19)","Inspections are in person only; self-certifications are no longer accepted","Individually owned condo units in multifamily buildings also need the certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Sale inspection, per unit, property built before 1996","amount":"$50"},{"label":"Sale inspection, per unit, property built after 1996 (form also requires Zoning Compliance Certification for these homes)","amount":"$100"}]$j$::jsonb, $t$https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf$t$, $t$https://www.ocnj.us/firepreventionfaq$t$, $j$[{"url":"https://www.ocnj.us/firepreventionfaq","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/SmokeRequirements.pdf","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/municipalcodeandlicensing","label":"Official source (ocnj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification is required for all residential rental units in one- and two-family dwellings and for the sale or transfer of title of residential units in one- and two-family dwellings, and individually owned condo units in multiple dwellings.$t$, $t$3c166b47bfb504d64eff5d1a0ca4e8b60739202b2a037d97860356bc4b08d407$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0508.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0508.json$t$, true),
  ($t$0509$t$, $t$Sea Isle City$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance, Floodplain Venting Requirements (flood vent check at sale)$t$, $j$["Issued by: Construction Office (Construction Official)","Contact: Neil Byrne, Construction Official, Building Sub-code Official, Zoning Officer & Certified Floodplain Manager · 609-263-1166 · construction@seaislecitynj.us","How to apply: Use the City's 'Smoke Detector, Extinguisher, CO Alarm & Venting application' packet from the Construction Forms page. Fill in the property address, owner's name and the mailing address for the certificate on the venting certificate page and return it to the Construction Office, City Hall 2nd floor, 233 John F. Kennedy Blvd. The Construction Official then inspects the flood venting.","Construction Official visits the home to verify the required square inches of flood venting","Flood vents: at least one square inch of net open area per square foot of enclosed area (non-engineered vents), or one engineered inch per square foot for engineered vents","Required vents and crawl space access door(s) must be located; if they fall short, the owner is given a set number of days to meet the City venting requirements"]$j$::jsonb, $j$[]$j$::jsonb, $t$https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf$t$, $t$https://www.seaislecitynj.us/departments/ConstructionOffice$t$, $j$[{"url":"https://www.seaislecitynj.us/departments/ConstructionOffice/ConstructionOfficeFAQs","label":"Official source (seaislecitynj.us)"},{"url":"https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf","label":"Official source (evocloud-prod3-public.s3.us-east-2.amazonaws.com)"},{"url":"https://www.seaislecitynj.us/departments/ConstructionOffice","label":"Official source (seaislecitynj.us)"}]$j$::jsonb, $t$What inspections do I need to sell my property? A self-inspection must be performed certifying that the smoke detectors, carbon monoxide alarms and fire extinguishers are placed properly throughout the house, are in working order, and are not expired. The City Construction Official will go to the property to verify the number of required square inches of flood venting. Both of these forms are on the Construction Office page on the City’s municipal website.$t$, $t$a2c2489e3110f032bf94b538e8d75a9a8390802f749b87916fbe6be03a91c54c$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0509.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0509.json$t$, true),
  ($t$0509$t$, $t$Sea Isle City$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Sea Isle City (Construction Office / Municipal Services, municipal fire code enforcing agency) (town fire bureau)","Contact: Robert Wojcik, Fire Official (per NJ DCA fire directory) · 609-263-4461 · rwojcik@seaislecitynj.us","Apply: Certificate is mailed; allow processing time. If the sale does not happen within 6 months a new application is needed.","How to apply: Download the Application for Certificate of Smoke Detector, Carbon Monoxide Alarm, Portable Fire Extinguisher Compliance from the Construction Forms page. Check off each item, sign in front of a notary, and return it with a $45 per unit check (payable to the City of Sea Isle City), cash or money order to Municipal Services, 2nd floor, 233 John F. Kennedy Blvd., Sea Isle City, NJ 08243. The certificate is mailed to the mailing address on the form. Fees are non-refundable and the certificate is not transferable.","Fire official in the NJ state directory (town), updated 2/1/2024: Robert Wojcik · (609) 263-1366 · rwojcik@seaislecitynj.us","Owner or authorized representative does the inspection and signs a notarized self-certification; no inspector visit for the alarms","Smoke detector on each level including basements (not attic or crawl space), and a smoke detector and CO alarm outside each separate sleeping area, within ten feet of it","Homes built after January 1977: AC powered and/or interconnected smoke alarms must be kept in working order; a ten year sealed battery smoke detector is required if detectors are not hard wired","CO alarm required when the home has fuel-burning appliances, a fireplace or wood/coal stove, or an attached garage; battery alarms are acceptable","City form still lists a portable fire extinguisher: minimum rating 2A-10B:C, no more than 10 pounds, within ten feet of the kitchen area, on its bracket, top no more than 5 feet above the floor, near an exit (seasonal summer units exempt)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke, CO alarm and fire extinguisher certificate, per unit","amount":"$45"}]$j$::jsonb, $t$https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf$t$, $t$https://www.seaislecitynj.us/departments/ConstructionOffice/constructionforms$t$, $j$[{"url":"https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf","label":"Official source (evocloud-prod3-public.s3.us-east-2.amazonaws.com)"},{"url":"https://www.seaislecitynj.us/departments/volunteerfiredepartment/firedepartmentfaqs","label":"Official source (seaislecitynj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application For Certificate of Smoke Detector Carbon Monoxide Alarm Portable Fire Extinguisher Compliance$t$, $t$62846efda849eb991124413acac841b9f7b269e6a88fae4cf833374503adc606$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0509.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0509.json$t$, true),
  ($t$0510$t$, $t$Stone Harbor Borough$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Title Transfer (zoning and flood conformance inspection)$t$, $j$["Issued by: Office of Code Enforcement, Zoning Officer (Zoning Official / Flood Plain Administrator)","Contact: Matthew Steich, Zoning Official/Code Officer/Community Development Director (signs the title transfer certificate) · 609-368-6814 · MSteich@shnj.org","How to apply: Fill out the Application for Certificate of Title Transfer (property address, block and lot, seller, purchaser, agent, scheduled closing date) and submit it with payment (check or cash) to the Office of Code Enforcement, Borough Hall, 9508 Second Avenue, Stone Harbor, NJ 08247 (609-368-6814, MSTEICH@SHNJ.ORG). Listing a realtor lets the official use the realtor's key. Office open to the public Monday to Friday 8:30 a.m. to 1:30 p.m.","Valid for: 180 days after issuance, for one transfer only (Code Section 214-7)","Zoning conformance inspection: the structure or unit must comply with Chapter 560, Zoning","Flood conformance inspection against the required design flood elevation (DFE + 2 or 11 feet), with the assessed value of the structure recorded","Inspector enters with the realtor's key; if no realtor or manager is listed, the owner must set an appointment during the inspection week","Not required for transfers of new construction when the original certificate of occupancy was issued within 18 months of the transfer","Also: Open permits closed: All open Uniform Construction Code permits must be closed before settlement (Fire Prevention Bureau guide).","Also: Certificate of Title Transfer (zoning and flood): Required before any sale or title transfer under Borough Code Chapter 214; separate $100 application to the Office of Code Enforcement. See the town certificate."]$j$::jsonb, $j$[{"label":"Zoning fee","amount":"$50.00"},{"label":"Flood inspection fee","amount":"$50.00"},{"label":"Total due","amount":"$100.00"}]$j$::jsonb, $t$https://stoneharbornj.org/wp-content/uploads/2026/10/Cert-of-title-transfer.pdf$t$, $t$https://stoneharbornj.org/departments/construction/$t$, $j$[{"url":"https://ecode360.com/10812862","label":"Official source (ecode360.com)"},{"url":"https://stoneharbornj.org/wp-content/uploads/2026/10/Cert-of-title-transfer.pdf","label":"Official source (stoneharbornj.org)"},{"url":"https://stoneharbornj.org/wp-content/uploads/2023/04/APPLICATION-FOR-CERTIFICATE-OF-TITLE-TRANSFER.pdf","label":"Official source (stoneharbornj.org)"},{"url":"https://stoneharbornj.org/departments/construction/","label":"Official source (stoneharbornj.org)"}]$j$::jsonb, $t$No person, persons or organization of persons shall sell or transfer title to any structure, portion of structure or unit$t$, $t$0bc7189d268375d1848d80812ef38fba3f5fedc6a690f1b952ddee71b9917e7b$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":7,"fee_bad":0,"fee_unchecked":3,"quotes":19,"q_ok":10,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0510.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0510.json$t$, true),
  ($t$0510$t$, $t$Stone Harbor Borough$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Stone Harbor Fire Prevention Bureau (Stone Harbor Bureau of Fire Prevention) (town fire bureau)","Contact: Mike Gihorski, Acting Fire Official · 609-368-5102 · fireofficial@shnj.org","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Fill out the CSACMAPFEC application (owner, buyer, block and lot, agent, settlement date, key or appointment details) and submit it with a check or money order payable to 'Borough of Stone Harbor' to the Stone Harbor Fire Prevention Bureau, 9508 Second Avenue, Stone Harbor, NJ 08247. The Bureau inspects before issuing the certificate.","Fire official in the NJ state directory, updated 3/6/2025: Michael Gihorski · (609) 368-5102 · fireofficial@shnj.org","On-site inspection by the Stone Harbor Bureau of Fire Prevention; closing or leasing before the certificate is issued carries a $500.00 penalty","Smoke alarms over ten years old must be replaced; battery alarms must be 10-year sealed battery type; wired alarms may not be replaced with battery alarms","Smoke alarm type and number depend on the year built or renovated (for example, homes from March 1991 on need wired, interconnected alarms on all levels and inside each sleeping room)","CO alarms on sleeping levels within 10 feet of every bedroom door when there is an attached garage, fuel-burning appliance or fireplace; CO alarms not more than 10 years old; homes built 2015 or later need hard-wired CO alarms","Low-voltage fire alarm systems must be tested by a NJ licensed alarm contractor with an NFPA 72 report sent to the Bureau","Form (October 2022) still requires a fire extinguisher: minimum 2A:40BC, not over 10 pounds, in or within 10 feet of the kitchen on its bracket, top no more than 5 feet up, serviced within the past year or bought within 6 months with receipt, manual left for the buyer","All open construction permits must be closed before settlement","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"1 unit, request more than 10 business days before change of occupant","amount":"$50.00"},{"label":"2 units in one structure, more than 10 business days before","amount":"$65.00"},{"label":"1 unit, request 5 to 9 business days before change of occupant","amount":"$100.00"},{"label":"2 units in one structure, 5 to 9 business days before","amount":"$115.00"},{"label":"1 unit, request 4 or fewer business days before change of occupant","amount":"$155.00"},{"label":"2 units in one structure, 4 or fewer business days before","amount":"$170.00"},{"label":"Re-inspection after a failed inspection","amount":"$25.00"}]$j$::jsonb, $t$https://stoneharbornj.org/wp-content/uploads/2022/10/CSACMAPFEC-2022.pdf$t$, $t$https://stoneharbornj.org/departments/stone-harbor-public-safety/stone-harbor-fire-prevention-bureau/$t$, $j$[{"url":"https://stoneharbornj.org/wp-content/uploads/2022/10/CSACMAPFEC-2022.pdf","label":"Official source (stoneharbornj.org)"},{"url":"https://stoneharbornj.org/departments/stone-harbor-public-safety/stone-harbor-fire-prevention-bureau/","label":"Official source (stoneharbornj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$I understand that a satisfactory inspection must be performed by the Stone Harbor Bureau of Fire Prevention prior to the issuance of the CSACMAPFEC$t$, $t$8a17e17f6d1920ec704eeb72ca8efa9c99af5549ee5369657769d59275488398$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":7,"fee_bad":0,"fee_unchecked":3,"quotes":19,"q_ok":10,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0510.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0510.json$t$, true),
  ($t$0511$t$, $t$Upper Township$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Upper Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Dory Cooper, Construction Official · 609-628-2011 ext. 225 · constructioncode@uppertownship.com","How to apply: No Township resale inspection. The Township's Construction Code page sends sellers to the NJ DCA online smoke detector and carbon monoxide certification."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://uppertownship.com/departments/construction-code/$t$, $j$[{"url":"https://uppertownship.com/departments/construction-code/","label":"Official source (uppertownship.com)"}]$j$::jsonb, $t$The Construction Department does not do inspections for resale of residential or non-residential structures.$t$, $t$bfff49ca0d07ef4325e452cc05ff94953c3b41373091da6cdda97a7690cbabda$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":7,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0511.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0511.json$t$, true),
  ($t$0511$t$, $t$Upper Township$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 8/5/2026: Louis Kilmer · (609)633-6132","State online self-certification (CSACMASPSIL): smoke alarms, carbon monoxide alarms, and the secondary power source identification label for homes with solar, generators or batteries; the current state application no longer lists a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://uppertownship.com/departments/construction-code/","label":"Official source (uppertownship.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Construction Department does not do inspections for resale of residential or non-residential structures. You can use the above link for the required smoke detector and carbon monoxide certification. This certification is administered by the NJ Department of Community Affairs.$t$, $t$60b88a0310b0e7c79caf95e24d94f32b3f764df1135da871aa14e537c1980604$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":7,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0511.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0511.json$t$, true),
  ($t$0514$t$, $t$Wildwood$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) and Zoning Certification, via the combined Application for Transfer of Ownership$t$, $j$["Issued by: City of Wildwood Construction / Code Enforcement Office (CCO) and Zoning Office (zoning certification)","Contact: Kate Dunn, Technical Assistant to the Construction Official / Planning and Zoning Board Secretary · 609-522-2444 ext. 2910 · kdunn@wildwoodnj.gov","Apply: 10 or more business days before settlement for the lowest zoning fee; reports take several days after the inspection to process","How to apply: Fill out the one combined City of Wildwood Application for Transfer of Ownership (property, block and lot, units, rooms, bedrooms, seasonal or year-round, settlement date, owner, buyer, agent) and turn it in with payment at City Hall, 4400 New Jersey Avenue. No application is accepted without payment; do not fax or mail it without payment. The current Fire Prevention forms say separate checks are required for the fire, CCO and zoning certificates. Reports are faxed or emailed when done.","Continued Occupancy (CCO) inspection","Zoning certification","Smoke alarm and carbon monoxide alarm compliance inspection (see the fire certificate)","Status of Fire Code report, only for properties that need a yearly fire inspection (single family homes do not)"]$j$::jsonb, $j$[{"label":"CCO, residential property with 1 to 5 units","amount":"$95.00"},{"label":"Zoning certification, 10 or more business days before settlement","amount":"$50.00"},{"label":"Zoning certification, 4 to 10 business days before settlement","amount":"$70.00"},{"label":"Zoning certification, less than 4 business days before settlement","amount":"$125.00"},{"label":"Status of Fire Code certificate (only properties that need a yearly fire inspection; not single family)","amount":"$50.00"}]$j$::jsonb, $t$https://wildwoodnj.gov/files/Transfer-of-ownership.pdf$t$, $t$https://wildwoodnj.gov/construction$t$, $j$[{"url":"https://wildwoodnj.gov/files/Transfer-of-ownership.pdf","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/codeenforcement","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/construction","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/planningzoning","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/images/CSACMAC%20Application%20FILLABLE.pdf","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/images/Status%20of%20Fire%20Code%20Application%20FILLABLE.pdf","label":"Official source (wildwoodnj.gov)"}]$j$::jsonb, $t$We have changed from 4 different applications to one combined application. You are still required to have the four different inspections, but only need to fill out the one form.$t$, $t$0bb09755ca280196f5b36801070583f5ab9bc1113b2ec4dcb4b2b961e68a3122$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":16,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0514.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0514.json$t$, true),
  ($t$0514$t$, $t$Wildwood$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Wildwood Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Jacob M. Spiegel, Fire Official · 609-846-2031 · jspiegel@wildwoodnj.gov","Apply: 10 or more business days before settlement for the lower fee; the inspection is scheduled once the application is received","How to apply: Fill out the Application for a Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance (CSACMAC) for 1 or 2 family dwellings and submit it with payment (a separate check from the CCO and zoning fees) to the Fire Prevention Bureau, 4400 New Jersey Avenue, Wildwood, NJ 08260, fax 609-522-4965 or email fireprev@wildwoodnj.gov. Credit cards are accepted with a 3% surcharge. A failed inspection needs a re-inspection with a re-inspection fee (amount not stated).","Fire official in the NJ state directory, updated 8/21/2024: Jacob Spiegel · (609) 846-2030 · jspiegel@wildwoodnj.org","On-site inspection by the Wildwood Fire Prevention Bureau; do not apply until everything is in place","Smoke alarms in each sleeping room/area (City ordinance), outside (within 10 feet of) each sleeping room/area, and on every level","Hardwired smoke alarms must be replaced if older than 10 years after the date of manufacture; battery smoke alarms must be sealed battery type","CO alarms outside (within 10 feet of) each sleeping room/area and on every level when there are fuel-burning appliances or an attached garage","Homes with a generator, solar panels, battery storage or other secondary power source need a printed label reading 'CAUTION: MULTIPLE SOURCES OF POWER.' within 18 inches of the main electrical panel and the electric meter (handwritten labels not accepted)","The January 2026 form does not list a fire extinguisher","Any outstanding fees on the property must be settled before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Application received 10 or more business days before settlement","amount":"$75.00"},{"label":"Application received less than 10 business days before settlement","amount":"$150.00"},{"label":"Penalty for failing to obtain the certificate (up to)","amount":"$2,000.00"}]$j$::jsonb, $t$https://wildwoodnj.gov/firedepartment/images/CSACMAC%20Application%20FILLABLE.pdf$t$, $t$https://wildwoodnj.gov/firedepartment/prevention-inspections$t$, $j$[{"url":"https://wildwoodnj.gov/firedepartment/images/CSACMAC%20Application%20FILLABLE.pdf","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/prevention-inspections","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/index","label":"Official source (wildwoodnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for a Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance (CSACMAC) - 1 or 2 Family Dwellings$t$, $t$d556ea510b7c75c789561b009e102a95abc36fd16044bb45cea2382ef0ff6818$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":16,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0514.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0514.json$t$, true),
  ($t$0515$t$, $t$Wildwood Crest Borough$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Zoning Use Compliance (Borough Code Chapter 86, Zoning Use Compliance Certificate)$t$, $j$["Issued by: Office of Zoning Administration (Zoning Official)","Contact: Rick Allen, Zoning Official · 609-729-8090 · rallen@wildwoodcrest.org","Apply: Ten or more days before settlement for the lowest fee","How to apply: Fill out the Borough's Application for Certificate of Zoning Use Compliance (updated July 2023): property, block and lot, applicant, owner, prospective buyer, settlement date and current use. File it with the fee at the Office of Zoning Administration, Borough Hall, 6101 Pacific Avenue, Wildwood Crest. Apply ten or more days before settlement for the lowest fee.","Zoning use compliance review confirming the current use (single family, two-family, multi-family, condo and so on) is permitted or a lawful pre-existing nonconforming use","Application lists the property owner, the prospective buyer and the settlement date"]$j$::jsonb, $j$[{"label":"Zoning use compliance, ten or more days before settlement","amount":"$50"},{"label":"Zoning use compliance, 9 to 5 days before settlement","amount":"$70"},{"label":"Zoning use compliance, four or fewer days before settlement","amount":"$125"}]$j$::jsonb, $t$https://wildwoodcrest.org/cp/tinymce/data/files/Application%20for%20Certificate%20of%20Zoning%20Use%20Compliance%20updated%20July%202023.pdf$t$, $t$https://wildwoodcrest.org/planningzoning.php$t$, $j$[{"url":"https://wildwoodcrest.org/cp/tinymce/data/files/Application%20for%20Certificate%20of%20Zoning%20Use%20Compliance%20updated%20July%202023.pdf","label":"Official source (wildwoodcrest.org)"},{"url":"https://wildwoodcrest.org/planningzoning.php","label":"Official source (wildwoodcrest.org)"},{"url":"https://ecode360.com/36124429","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36091719","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Borough of Wildwood Crest Office of Zoning Administration 6101 Pacific Avenue, Wildwood Crest, NJ 08260 Phone (609) 729-8089 E: rallen@wildwoodcrest.org Rick Allen, Zoning Official Application for Certificate of Zoning Use Compliance$t$, $t$a3056ab9e393490832eda5a5c4bbf9956a08218488f99b3687533283f0b39280$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-27","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0515.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-27. Source: property/data/municipal-requirements/checked/0515.json$t$, true),
  ($t$0515$t$, $t$Wildwood Crest Borough$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Wildwood Crest Fire Prevention & Inspection Bureau (town fire bureau)","Contact: Michael Neill, Fire & Temporary Housing Official · 609-729-8083 · mneill@wildwoodcrest.org","Apply: More than 10 business days before settlement for the lowest fee; the inspector inspects as soon as possible after the application is received","How to apply: Fill out the Application for a Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (CSACMAPFEC): property type, settlement date, key, access code or appointment, seller/agent, settlement agency, seller and buyer. Submit it with a check payable to the Fire Prevention Bureau at 6101 Pacific Avenue, Wildwood Crest, NJ 08260, and choose to have the certificate mailed or picked up.","Fire official in the NJ state directory, updated 7/13/2026: Mike Neill · (609) 729-5152 · mneill@wildwoodcrest.org","On-site inspection by the Borough Fire Prevention & Inspection Bureau; do not apply until everything is in place","Smoke alarms in each sleeping room/area, outside (within 10 feet of) each sleeping room/area, and on every level including attics","Hardwired smoke alarms must be replaced if older than 10 years after the date of manufacture; battery smoke alarms must be the 10-year sealed battery type","CO alarms outside (within 10 feet of) each sleeping room/area and on every level when there are fuel-burning appliances or an attached garage","Fire extinguisher, minimum 2A:10BC, new (current year) or tagged by a licensed fire protection agent, for each cooking area, hung in a visible location or labeled cabinet (form still lists it)","Failure to apply and have the inspection before closing carries a $1000.00 penalty to the owner","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Application received more than 10 business days before settlement","amount":"$50.00"},{"label":"Application received 4 to 10 business days before settlement","amount":"$90.00"},{"label":"Application received less than 4 business days before settlement","amount":"$160.00"},{"label":"Re-inspection","amount":"$50.00"},{"label":"Fire Code Status Report (search for existing violations, fees and penalties)","amount":"$50.00"},{"label":"Certificate copy (can be reissued for a resale if the last inspection was within 6 months of settlement)","amount":"$25.00"},{"label":"Penalty for not applying and inspecting before closing","amount":"$1000.00"}]$j$::jsonb, $t$https://wildwoodcrest.org/fileupload/CSACMAPEC-application%202026.pdf$t$, $t$https://wildwoodcrest.org/fireprevention.php$t$, $j$[{"url":"https://wildwoodcrest.org/fileupload/CSACMAPEC-application%202026.pdf","label":"Official source (wildwoodcrest.org)"},{"url":"https://wildwoodcrest.org/fireprevention.php","label":"Official source (wildwoodcrest.org)"},{"url":"https://wildwoodcrest.org/images/Fire%20Prevention%20Fee%20Ordinance%20May%202020.pdf","label":"Official source (wildwoodcrest.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Borough of Wildwood Crest Fire Prevention & Inspection Bureau 6101 Pacific Avenue Wildwood Crest, New Jersey 08260 Office - 609-729-5152$t$, $t$71633e2df29290ed11ea0a63482a439d52a2265de21ad572ffa3df87f642d355$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-27","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0515.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-27. Source: property/data/municipal-requirements/checked/0515.json$t$, true),
  ($t$0614$t$, $t$Vineland$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection / Continued Certification of Occupancy (CCO) for resale$t$, $j$["Issued by: Vineland Fire Department, Fire Prevention Division","Contact: Brian Murray, Sr., Fire Official · (856) 794-2338 · Bmurray@vinelandcity.org","Apply: File as soon as a settlement date is set; at least 4 business days are needed, and filing more than 10 days before closing gets the lower fee","How to apply: As soon as a settlement date is set, file the resale application in person at the Fire Administration building, 400 W. Plum St., Vineland (the application is in triplicate and must be completed in person; a watermarked sample is online). At least 4 business days are needed. Make the check, money order or exact cash payment payable to the City of Vineland; fees are per unit and depend on how early you file. If the home fails, a new application and fee are needed before the reinspection. For vacant or uninhabitable homes the buyer can file a Certificate of Transfer of Title (CTT) affidavit together with the CCO application.","All construction permits closed before applying; unpermitted basement, garage or attic conversions are checked","No basement bedrooms without proper egress; zoning approval for duplex or triplex use; open Code Enforcement violations closed","Utilities on at the time of inspection","Exterior walls, gutters, foundation and accessory structures sound; yard free of trash, debris and abandoned vehicles","House numbers at least 4 inches high, contrasting and readable from the street","Stairs, decks, porches and balconies sound; guardrails on landings or porches 30 inches high; handrails where there are 3 or more risers","No keyed deadbolts on the inside of exit doors; bedroom doors close and latch","In-ground pools fenced with self-closing, self-latching gates","Smoke alarm on each level and within 10 feet of sleeping areas; sealed battery units unless hardwired alarms already exist (hardwired must be kept)","Carbon monoxide alarm near bedrooms where there are fuel-burning appliances or an attached garage","Homes with a generator, solar or battery storage need a printed 'Caution Multiple Sources of Power' label at the electrical panel and meter box","No excessive peeling paint in pre-1978 homes; windows open and stay open with no broken glass; no holes in walls, ceilings or floors","Heater, water heater and chimney in working order; bathroom exhaust fan or window","Electrical free of hazards (covers on outlets and boxes, no open panel holes, no taped splices); an electrical certification may be required","Toilets flush without leaks, hot and cold water work, water heater bonding strap and relief valve pipe 2 to 6 inches off the floor","Also: Open construction permits and unpermitted conversions: All construction permits must be closed out before applying; basement, garage or attic conversions without permits are checked (Licenses and Inspections, 856-794-4113).","Also: Zoning approval for duplex or multi-family use: Duplex and multi-family (15 units or fewer) owners should contact the Zoning Department before listing to confirm the use is conforming (856-794-4113).","Also: Open Code Enforcement violations: Any open Code Enforcement violations must be closed out (856-794-3806).","Also: Electrical certification: An electrical certification may be required."]$j$::jsonb, $j$[{"label":"Resale inspection (CCO), per unit, filed more than 10 days before closing","amount":"$125.00"},{"label":"Resale inspection (CCO), per unit, filed 4 to 10 days before closing","amount":"$200.00"},{"label":"Re-inspection (a new application is needed before a reinspection)","amount":"$50"},{"label":"Certificate of Transfer of Title affidavit (buyer, for vacant or uninhabitable homes), more than 10 days before closing","amount":"$25"},{"label":"Certificate of Transfer of Title affidavit, under 10 days before closing","amount":"$50"}]$j$::jsonb, $t$http://fire.vinelandcity.org/wp-content/uploads/2024/10/Website-CCO-App-w-watermark.pdf$t$, $t$https://fire.vinelandcity.org/selling-your-home/$t$, $j$[{"url":"https://fire.vinelandcity.org/selling-your-home/","label":"Official source (fire.vinelandcity.org)"},{"url":"http://fire.vinelandcity.org/wp-content/uploads/2024/10/Website-CCO-App-w-watermark.pdf","label":"Official source (fire.vinelandcity.org)"},{"url":"https://fire.vinelandcity.org/wp-content/uploads/2025/02/RESIDENTIAL-DWELLING-RESALE-CHECKLIST-.pdf","label":"Official source (fire.vinelandcity.org)"},{"url":"https://www.vinelandcity.org/forms/","label":"Official source (vinelandcity.org)"},{"url":"https://www.vinelandcity.org/departments-contact-directory/","label":"Official source (vinelandcity.org)"}]$j$::jsonb, $t$As is in most municipalities, the City of Vineland requires the owner intending to sell their home, duplex or multi-family units to obtain a Certificate of Inspection prior to settlement.$t$, $t$1a9bcb7814fb0e28be04fd2071dff2eb4088d8f4bac9cab5a19e8ad54fcc1480$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0614.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0614.json$t$, true),
  ($t$0614$t$, $t$Vineland$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Vineland Fire Department, Fire Prevention Division (same inspection as the resale CCO) (town fire bureau)","Contact: Brian Murray, Sr., Fire Official · (856) 794-2338 · Bmurray@vinelandcity.org","Apply: At least 4 business days; more than 10 days before closing for the lower fee","How to apply: As soon as a settlement date is set, file the resale application in person at the Fire Administration building, 400 W. Plum St., Vineland (the application is in triplicate and must be completed in person; a watermarked sample is online). At least 4 business days are needed. Make the check, money order or exact cash payment payable to the City of Vineland; fees are per unit and depend on how early you file. If the home fails, a new application and fee are needed before the reinspection. For vacant or uninhabitable homes the buyer can file a Certificate of Transfer of Title (CTT) affidavit together with the CCO application.","Fire official in the NJ state directory, updated 6/10/2025: Brian J Murray Sr · (856) 794-4000 · Bmurray@vinelandcity.org","Smoke alarm on each level and within 10 feet of sleeping areas; sealed 10-year battery units unless hardwired alarms already exist (hardwired must be kept)","Carbon monoxide alarm near bedrooms where there are fuel-burning appliances or an attached garage","Combination 10-year smoke and CO alarms recommended","Printed 'Caution Multiple Sources of Power' label at the electrical panel and meter box for homes with a generator, solar or battery storage","House numbers at least 4 inches high","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Resale inspection (CCO), per unit, filed more than 10 days before closing","amount":"$125.00"},{"label":"Resale inspection (CCO), per unit, filed 4 to 10 days before closing","amount":"$200.00"},{"label":"Re-inspection (a new application is needed before a reinspection)","amount":"$50"}]$j$::jsonb, $t$http://fire.vinelandcity.org/wp-content/uploads/2024/10/Website-CCO-App-w-watermark.pdf$t$, $t$https://fire.vinelandcity.org/selling-your-home/$t$, $j$[{"url":"https://fire.vinelandcity.org/selling-your-home/","label":"Official source (fire.vinelandcity.org)"},{"url":"https://fire.vinelandcity.org/wp-content/uploads/2025/02/RESIDENTIAL-DWELLING-RESALE-CHECKLIST-.pdf","label":"Official source (fire.vinelandcity.org)"},{"url":"https://fire.vinelandcity.org/wp-content/uploads/2025/06/NEW-2025-REAR-OF-CCO-APPLICATION-6-25.pdf","label":"Official source (fire.vinelandcity.org)"},{"url":"https://fire.vinelandcity.org/welcome-fire-marshall/","label":"Official source (fire.vinelandcity.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Inspections filed more than 10 days prior to the closing date are charged at a rate of $125.00 per unit.$t$, $t$3d42069faf90146fe6889536c407769e1d3716cec47d46419751c68e52ad187e$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0614.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0614.json$t$, true),
  ($t$1107$t$, $t$Lawrence Township$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (Property Transfer Application, Division of Housing)$t$, $j$["Issued by: Township of Lawrence Division of Housing (Housing Bureau)","Contact: Kelly Barkalow, Fire Prevention Specialist, Division of Housing · 609-844-7032 · kbarkalow@lawrencetwp.com","Apply: Apply as soon as possible after listing; the Township says the current wait for an inspection is about 3-4 weeks (its FAQ says generally within two weeks). No expediting.","How to apply: Fill out the Property Transfer Application and bring or mail it with the $80.00 fee to the Division of Housing, 2207 Lawrence Road (Lawrenceville Road), Lawrence Township, NJ 08648. Faxed or emailed applications are not accepted. Pay by check (payable to Township of Lawrence), exact cash, money order, or Visa/Mastercard credit in the office only. After the application and fee are received, the owner or agent calls the Division of Housing (609-844-7032) to schedule. An adult must be present if occupied; a vacant home with a lockbox can be inspected with the lockbox code. The certificate is typed the next business day and mailed or picked up (not emailed or faxed).","Valid for: One year from the original inspection date","Smoke alarms as required for the year the home was built (hard-wired, interconnected alarms for newer homes); battery-only alarms must be 10-year sealed units","Smoke alarms older than 10 years must be replaced","Carbon monoxide alarm within 10 feet of the bedroom doors (or one in each bedroom)","Secondary power source label (generators, solar, batteries) within 18 inches of the main electrical panel and meter, not handwritten","Fire extinguisher is checked during the housing inspection (per the Housing FAQ; the February 2026 checklist no longer lists it)","Dryer vents must be aluminum flex, not plastic","Sump pumps must discharge outdoors, not into the sewer","Private well: well test report under the NJ Private Well Testing Act sent to the Division of Housing","Septic system: NJDEP-protocol septic inspection reviewed and approved by the Health Department before the certificate is issued","A failed septic system or outstanding permits must be addressed by the current owner before closing","Life safety violations must be corrected and reinspected before anyone moves in; a buyer may assume most other violations in writing","Also: Open permits: Outstanding permits must be addressed by the current owner before closing; the application has an Outstanding Permits section. The checklist also tells buyers to verify there are no open permits (records requests go to the Municipal Clerk).","Also: Septic system: A NJDEP-protocol septic inspection (N.J.A.C. 7:9A-12.6) must be reviewed and approved by the Health Department before the Certificate of Inspection is issued; a failed septic system must be addressed by the current owner before closing.","Also: Private well test: Homes with a private well must be tested under the NJ Private Well Testing Act; the report should be sent to the Division of Housing.","Also: Buyer assumption of violations: A buyer may assume most violations with the Assumption of Violations by Buyer letter; life hazard violations must be corrected and reinspected before occupancy."]$j$::jsonb, $j$[{"label":"Certificate of Inspection for a sale (single or two family)","amount":"$80.00"},{"label":"Housing Inspection Fee (Township fee ordinance 2495-25, adopted May 20, 2025)","amount":"$80.00"}]$j$::jsonb, $t$https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Property%20Transfer%20Application$t$, $t$https://www.lawrencetwp.com/departments/division-of-housing$t$, $j$[{"url":"https://www.lawrencetwp.com/HousingFAQ","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/departments/division-of-housing","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Property%20Transfer%20Application","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Housing%20Pre%20Inspection%20Checklist","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Ordinances/2025/2495.25.pdf","label":"Official source (lawrencetwp.com)"}]$j$::jsonb, $t$If I am selling my home/condo do I need to get a Certificate of Inspection? Yes, a Certificate of Inspection is required prior to the transfer of ownership.$t$, $t$4815dd030f669958854b18900360629475f29763c514ae0ce6e5c2be617ebc89$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":19,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1107.json$t$, true),
  ($t$1107$t$, $t$Lawrence Township$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lawrence Township Fire Marshal's Office (municipal fire code enforcing agency); the resale smoke/CO check is done by the Township housing inspector (town fire bureau)","Contact: Edward Tencza, Fire Official · 609-844-7021 · ETencza@lawrencetwp.com","Apply: Part of the housing inspection (currently about 3-4 weeks wait)","How to apply: For a sale, file the Division of Housing Property Transfer Application ($80.00); the housing inspector checks smoke alarms, CO alarms and the extinguisher under the Fire Marshal's oversight. Questions: Division of Housing 609-844-7032 or Fire Marshal's Office 609-844-7018, 2207 Lawrenceville Road.","Fire official in the NJ state directory (town), updated 1/9/2026: Edward C Tencza · (609) 844-7021 · ETencza@lawrencetwp.com","No separate smoke/CO certificate for a sale: smoke alarms, CO alarms and the fire extinguisher are inspected during the Division of Housing inspection and included in the Certificate of Inspection","Battery-only smoke alarms must be 10-year sealed units; alarms over 10 years old must be replaced","Secondary power source warning label within 18 inches of the main panel and meter (homes with generators, solar or batteries)","Low-voltage monitored systems are supplemental; originally required alarms must be put back if removed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Included in the $80.00 Certificate of Inspection (no separate certificate needed for a sale)","amount":"$80.00"},{"label":"Separate Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, application received 10 or more business days before change of occupant (printed as '-10'; fee schedule in Ordinance 2495-25, not charged on a sale per the…","amount":"$45.00"},{"label":"Separate Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, application received 4-10 business days before change of occupant (Ordinance 2495-25)","amount":"$90.00"},{"label":"Separate Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, application received fewer than 4 business days before change of occupant (Ordinance 2495-25)","amount":"$161.00"}]$j$::jsonb, $t$https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Property%20Transfer%20Application$t$, $t$https://www.lawrencetwp.com/departments/firemarshal$t$, $j$[{"url":"https://www.lawrencetwp.com/HousingFAQ","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/departments/firemarshal","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Ordinances/2025/2495.25.pdf","label":"Official source (lawrencetwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Is a separate smoke alarm and carbon monoxide detector certificate required? No, a separate certificate is not required. The smoke alarms, carbon monoxide detectors, and fire extinguishers are inspected during the housing Inspection and included as part of the Certificate of Inspection$t$, $t$7f5a43424511b3d24bdc09f7ff5ad1cb8c0095ff1b0c0eeb930f2ae2bd46c0f3$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":19,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1107.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Continued Use (combined certificate of smoke alarm, carbon monoxide alarm and compliance, CSDCMAC)$t$, $j$["Issued by: Borough of Eatontown inspector (Housing Official, Code Enforcement Officer, Fire Marshal or Fire Inspector)","Contact: Ashley Yates, Housing Department contact named on the CO application sheet · 732-860-5513 · ayates@eatontownnj.com","Apply: Fees rise when the request is made 10 or fewer business days before the change of occupancy. All fees are paid with the application before any inspection.","How to apply: Apply online for a Resale inspection through the Borough's SDL Portal (https://www.sdlportal.com/towns/nj/monmouth/eatontown/requests/certificate; an account is needed), then pay online with the link on the Borough's 'Apply for a CO - Housing' sheet, or drop off a check at the Housing office on the 2nd floor of Borough Hall, 47 Broad Street. Fees are paid with the application before any inspection. The sheet and the 2026 Housing checklist are on the Borough's Applications & Forms page (Housing section). Questions: 732-860-5513 or ayates@eatontownnj.com.","Valid for: 60 days (Code §116-6B); the code also says CSDCMAC inspections are valid for six months","Inspection for fitness for habitation under Borough Code §116-8 before the home is sold","Any outstanding permit issues must be closed; Zoning Officer certifies compliance","Smoke detectors on each level and within 10 feet of sleeping quarters, working and under 10 years old; 10-year sealed battery units; AC powered units cannot be swapped for battery units","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","Monitored fire alarm systems must be made available for testing, with a certificate of inspection","Checklist items include working doors and keyless deadbolts, GFCI in bathrooms, covered electrical boxes and plates, 4-inch house numbers, handrails on stairs over four risers, unbroken operable windows, safe sidewalk/driveway/apron/foundation, heating system and flue, water heater overflow pipe, metal dryer vent, minimum 60 amp service, sump pump on a dedicated receptacle","Application states the future owner's name and address and who will allow entry","All utilities (gas, electric, water) must be on at the time of the inspection (2026 Housing checklist)","Also: Open permits and zoning: Outstanding permit issues must be closed and the Zoning Officer must certify compliance before the certificate is issued. The Building / Construction page also asks that no closings be scheduled before final building inspections on open permits."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"},{"label":"Transfer of residential properties (lawful two-family homes charged separately)","amount":"$200"},{"label":"Buyer backs out and a new buyer purchases before occupancy (updated application)","amount":"$35"}]$j$::jsonb, $t$https://files.heygov.com/eatontownnj.com/file_01m5mhcqvn8t9ebhbr91fvzv77/Apply%20for%20a%20CO%20-%20Housing.pdf$t$, $t$https://www.eatontownnj.com/departments/building-construction$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/departments/building-construction","label":"Official source (eatontownnj.com)"},{"url":"https://files.heygov.com/eatontownnj.com/file_01m5mhcqvn8t9ebhbr91fvzv77/Apply%20for%20a%20CO%20-%20Housing.pdf","label":"Official source (files.heygov.com)"},{"url":"https://files.heygov.com/eatontownnj.com/file_01m3nqvm14pzvd9zh8z76kx5j4/EATONTOWN%20HOUSING%20CHECKLIST%202026.pdf","label":"Official source (files.heygov.com)"},{"url":"https://www.eatontownnj.com/applications-forms","label":"Official source (eatontownnj.com)"},{"url":"https://www.eatontownnj.com/thinking-of-selling-your-house","label":"Official source (eatontownnj.com)"}]$j$::jsonb, $t$Eatontown Borough shall perform inspections in accordance with the New Jersey Uniform Fire Code before any one- and two-family or attached single-family structure is sold, leased, or otherwise made subject to a change of occupancy for residential purposes.$t$, $t$6d8b0dbd87c6d024f627eb0721c735b63f6b9304246f11a79de25da9f33449e5$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":23,"q_ok":15,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Eatontown Housing Division and Fire Prevention Bureau (combined certificate of occupancy and CSDCMAC) (town fire bureau)","Contact: Patrick Renaldi, Fire Marshal · 732-389-7620 · fireprev@EatontownNJ.com","Apply: Combined with the certificate of occupancy inspection; fee depends on business days before the change of occupancy.","How to apply: The smoke/CO certificate is not applied for separately: Eatontown issues one combined certificate after its Housing inspection, applied for through the SDL Portal (see resale certificate). The Bureau of Fire Safety page points to the Applications & Forms page to obtain a Local Certificate of Occupancy.","Fire official in the NJ state directory, updated 10/2/2024: Patrick Renaldi · (732) 389-7621 · prenaldi@eatontownnj.com","Smoke detectors on each level and within 10 feet of sleeping quarters, working and less than 10 years old","10-year sealed battery single station smoke alarms (ANSI/UL 217); AC powered alarms from original construction or rehabilitation stay AC powered","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","No fire extinguisher for owner sales; the code lists extinguishers for rental and apartment units only","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/departments/bureau-of-fire-safety$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/departments/bureau-of-fire-safety","label":"Official source (eatontownnj.com)"},{"url":"https://www.eatontownnj.com/departments/land-use-zoning-and-code-enforcement","label":"Official source (eatontownnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$To protect the health, safety, and wellness of all residents and first responders, the owner shall obtain a combined certificate of smoke alarm, carbon monoxide alarm, and compliance.$t$, $t$8e50a600d0bd2985d11a3241d24ced2114546109edfaeea27c82f28b58ade257$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":23,"q_ok":15,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1404$t$, $t$Chatham Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Continuing Occupancy (CCO)$t$, $j$["Issued by: Borough of Chatham, Office of the Borough Clerk (CCO inspection with the smoke/CO check)","Contact: Hillary Singer, Assistant to the Borough Clerk (handles CCO inspections) · 973-635-0674 ext.210 · clerkadmin@chathamborough.org","Apply: CCOs take about 3 weeks to process after a complete application (the Borough page says two to three weeks, not counting the inspection). Inspections are Thursdays between 11 am and 1 pm, scheduled once permits are closed and utilities are current.","How to apply: Fill in the Residential CCO Application, attach the open-permit summary, Tax Collector and Utilities Clerk sign-offs and the inspection checklist, and submit it to the Borough Clerk's Office, 54 Fairmount Avenue, with $100 by check or cash payable to Borough of Chatham. The Clerk's Office schedules the Thursday inspection and issues the CCO once the signed checklist and proof of closed permits are in.","Residential CCO application (Sale) signed by the owner or authorized agent","For a sale: proof of no open permits (a 'Permit Summary' requested from the Clerk through an OPRA request)","For a sale: Tax Collector sign-off on page 2 that Lead Line Replacement fees are paid in full","Utilities Clerk sign-off that water/sewer utilities are paid in full","Inspection checklist items: street number, smoke detectors, carbon monoxide, furnace and flues, hot water heater, electric panel, secondary power source, garage door opener, temporary wiring, cover plates, sump pump, handrails, sidewalk, general safety","Certificate from the service provider if the home is on a central station police or fire alarm system","Also: Lead water service line fees: For a sale, the Tax Collector must confirm Lead Line Replacement fees are paid in full; Borough Code §267-25 ties proof of lead service line replacement to the CCO on a sale or transfer.","Also: Utilities paid: Utilities Clerk must confirm water/sewer accounts are paid in full (973-635-0674 ext. 214).","Also: Open permits: Proof of no open permits (Permit Summary through an OPRA request) is required for a sale; all permits must be closed before the CCO is issued.","Also: Sump pump: Sump pumps may not discharge into the sanitary sewer and must have sturdy pit covers.","Also: Sidewalk: Sidewalk condition is on the CCO checklist."]$j$::jsonb, $j$[{"label":"Residential CCO application","amount":"$100"}]$j$::jsonb, $t$https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file$t$, $t$https://www.chathamborough.org/departments/zoning-engineering-construction$t$, $j$[{"url":"https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file","label":"Official source (chathamborough.org)"},{"url":"https://www.chathamborough.org/departments/zoning-engineering-construction","label":"Official source (chathamborough.org)"},{"url":"https://www.chathamborough.org/departments/clerk","label":"Official source (chathamborough.org)"},{"url":"https://ecode360.com/6792203","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/44601858","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Residential Certificate of Continuing Occupancy (CCO) Application$t$, $t$c0c7f0eaea1b4f839d3943a47243f5264342909f58776a9b10c54a73e47a9dde$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":15,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1404.json$t$, true),
  ($t$1404$t$, $t$Chatham Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Chatham (smoke/CO check on the Clerk's CCO inspection); fire code enforcing agency: Chatham Borough Bureau of Fire Safety (Code Enforcement) (town fire bureau)","Contact: Scott Loyek, Fire Marshal · 973-701-6815 · firemarshal@chathamborough.org","Apply: Same as the CCO: about 3 weeks; inspections Thursdays 11 am to 1 pm.","How to apply: Part of the Residential CCO application filed with the Borough Clerk's Office. Fire safety questions go to the Bureau of Fire Safety, 54 Fairmount Ave (hours by appointment).","Fire official in the NJ state directory (town), updated 1/13/2025: Scott Loyek · (973) 635-0674 · firemarshal@chathamborough.org","Smoke detectors with 10-year sealed batteries on each level, on the ceiling at the base of the stairs and not more than ten feet from each bedroom","Carbon monoxide detectors within ten feet of each bedroom; combination smoke/CO units allowed","Certificate from the alarm company if the home is connected to a central station alarm system","Secondary power source warning label within 18 inches of the main electrical panel and meter","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO check within the residential CCO (same fee, not an extra charge)","amount":"$100"}]$j$::jsonb, $t$https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file$t$, $t$https://www.chathamborough.org/departments/fire-prevention$t$, $j$[{"url":"https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file","label":"Official source (chathamborough.org)"},{"url":"https://www.chathamborough.org/departments/fire-prevention","label":"Official source (chathamborough.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$New Jersey Fire Code mandates the following when selling or renting your home:$t$, $t$3e9be6f32b9431cd02e586635a29fed4f304273b67881a3b9a8c0d4dda6f5ee9$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":15,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1404.json$t$, true),
  ($t$1408$t$, $t$Denville Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Denville Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Sal Poli, Construction Official · (973) 625-8300 ext. 251","How to apply: No Township resale Certificate of Occupancy. The Township says the only inspection needed to sell a house is the Fire Prevention smoke detector inspection (smoke alarms, CO alarms and kitchen fire extinguisher). Open permits should be closed before transfer.","Also: Open permits: The Township asks that all open permits be closed out before the property is transferred."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.denvillenj.gov/departments/selling_your_house.php$t$, $j$[{"url":"https://www.denvillenj.gov/departments/selling_your_house.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/departments/construction.php","label":"Official source (denvillenj.gov)"}]$j$::jsonb, $t$The only inspection required to sell your house is a$t$, $t$82f82e48f5bf8f055326631122679fb1625eb575eb6658e83558438bc7502412$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":17,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1408.json$t$, true),
  ($t$1408$t$, $t$Denville Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Denville Township Fire Prevention Bureau (town fire bureau)","Contact: Carmine Ruta, Fire Official (Fire Inspectors: Don Leyhan and Rich Yobs) · (973) 625-8300 ext. 257 · fireprevention@denvillenj.org","Apply: Fee depends on business days between the request and the change of occupant (more than 10 for the lowest fee). Office hours Wednesday to Friday 8:00 am to 4:00 pm. Inspections are good for 6 months.","How to apply: Fill out the Application For CCO Inspections (Form Center, Fire Prevention section) and email it to fireprevention@denvillenj.org or mail it to 1 St. Mary's Place, Denville NJ. Checks payable to Denville Township Fire Prevention. To schedule call (973) 625-8300 ext. 257 (office hours Wed to Fri, 8:00 am to 4:00 pm).","Fire official in the NJ state directory, updated 3/27/2026: Connor Mc Guinness · (973) 625-8300 · fireprevention@denvillenj.org","Smoke alarm on each level including basements (not attic or crawl space) and outside each separate sleeping area within 10 feet of bedrooms","10-year sealed battery smoke alarms (ANSI/UL 217) where battery alarms are used; AC alarms from construction or rehabilitation cannot be replaced with battery alarms, and AC alarms more than 10 years old must be replaced before the inspection","CO alarm in the immediate vicinity of sleeping areas (UL 2034, NFPA 720) unless the home has no fuel-burning device or attached garage","Low-voltage alarm systems: monitoring contact, account and password, plus certification from an alarm technician","Portable fire extinguisher 2A-10B:C, no more than 10 pounds, serviced and tagged within 12 months or with a recent purchase receipt; owner's manual left for the new occupant (form still lists it)","Secondary power source label (\"Caution: Multiple Sources Of Power\") within 18 inches of the main panel and the meter, if the home has a generator, solar panels or battery storage (listed in the Affidavit packet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO resale inspection, more than 10 business days before change of occupant","amount":"$35"},{"label":"4 to 10 business days before change of occupant","amount":"$70"},{"label":"Fewer than 4 business days","amount":"$125"},{"label":"Township fee schedule: more than 10 days' notice","amount":"$35.00"},{"label":"Township fee schedule: 4 to 10 days' notice","amount":"$70.00"},{"label":"Township fee schedule: less than 4 days' notice","amount":"$125.00"}]$j$::jsonb, $t$https://www.denvillenj.gov/docs/FirePrevention/Application%20For%20CCO%20Inspections.pdf$t$, $t$https://www.denvillenj.gov/departments/fire_prevention.php$t$, $j$[{"url":"https://www.denvillenj.gov/departments/fire_prevention.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/administration/fee_schedule.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/docs/FirePrevention/Application%20For%20CCO%20Inspections.pdf","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/docs/FirePrevention/Affidavit%20application%20rev2.pdf","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/departments/selling_your_house.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detector inspections are good for 6 months.$t$, $t$aac26d046c3732983636406f365bbbc9db6dd3eff15193f0f1a6b3c5f4e794ff$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":17,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1408.json$t$, true),
  ($t$1517$t$, $t$Little Egg Harbor Township$t$, $t$OCEAN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Existing Structure Certificate of Occupancy (resale)$t$, $j$["Issued by: Little Egg Harbor Township Construction Office (Construction Code Official)","Contact: Ronald Piszar, Construction Official / Fire Sub-Code Official · (609) 296-7241 ext. 618 · rpiszar@leht.com","How to apply: Download the Existing Structure Certificate of Occupancy application (residential), check 'Resale', and submit the complete packet with the fee, the signed Mechanical Certification, and any required prior approvals (open permits closed, LLC formation letter, estate Surrogate letter or POA, well water analysis if on a well). Incomplete applications are not accepted. Once accepted, the office emails an inspection date (check spam folders). The form asks for a lock box code or that someone be home. If the buyer will obtain the certificate, the seller and buyer sign the notarized acknowledgements on page 5. Construction Office, 665 Radio Road, Little Egg Harbor, NJ 08087; phone 609-294-9071, fax 609-294-9065.","House numbers permanently attached: 3 inches for homes","Deadbolts may not need a key on the inside","Smoke alarms on each floor including the basement and within 10 feet of all bedrooms; interconnected systems must stay interconnected","Carbon monoxide alarms outside of and within 10 feet of all bedrooms","Anti-tip device on all ranges","Relief valves on water heaters and boilers piped down to 2 to 6 inches from the floor, no reducers, no threads at the bottom, no plastic unless allowed by the plumbing code","Dryer exhaust of metal flex or rigid pipe, vented outside","Water on, with hot on the left and cold on the right","Plumbing in good condition with no open sewer or gas lines","Covers on all light fixtures, switches, outlets, junction boxes and panels; no gaps in breaker or fuse boxes; service mast, meter socket and panel in good condition","Fire extinguisher (2A-10B:C, mounted near the kitchen) is only required for rentals","Signed mechanical certificate that the heating unit, hot water unit and electrical systems are safe (owner, buyer, licensed contractor or home inspector)","The checklist is not all-inclusive","Also: Open permits closed: Open permit request; all permits must be closed out before the application is accepted.","Also: Well water analysis: If the property has a well, an approved water analysis from the Ocean County Board of Health is required before the certificate is issued.","Also: Mechanical certification: Signed certificate that the heating unit, hot water unit and electrical systems are safe.","Also: Estate or business owner papers: Surrogate letter or POA for estates; letter of formation for business owners."]$j$::jsonb, $j$[{"label":"Resale inspection (table row: Resale / Fee / Re-Inspection Fee)","amount":"$60.00"},{"label":"Resale reinspection","amount":"$30.00"}]$j$::jsonb, $t$https://www.leht.com/wp-content/uploads/2026/02/EXISTING-STRUCTURE-RESALE-RENTAL-APPLICATION.pdf$t$, $t$https://www.leht.com/zoning-code-enforcement/$t$, $j$[{"url":"https://www.leht.com/wp-content/uploads/2026/02/EXISTING-STRUCTURE-RESALE-RENTAL-APPLICATION.pdf","label":"Official source (leht.com)"},{"url":"https://www.leht.com/zoning-code-enforcement/","label":"Official source (leht.com)"},{"url":"https://www.leht.com/construction/","label":"Official source (leht.com)"}]$j$::jsonb, $t$Pursuant to Little Egg Harbor Township Ordinance 2001-14 and 8-10.0 all properties sold and rented shall have their heating unit, hot water unit, plumbing and electrical system inspected and certified. Then the certification has to be delivered to the construction code official before Certificate of Inspection/ Occupancy can be issued.$t$, $t$2ed30a1bda00ff424689ae7ae65812da4287a35081f05e6712041574b580ec98$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":17,"q_ok":8,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/1517.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1517.json$t$, true),
  ($t$1517$t$, $t$Little Egg Harbor Township$t$, $t$OCEAN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Little Egg Harbor Township Construction Office (smoke and CO alarms checked in the Existing Structure Certificate of Occupancy inspection) (town fire bureau)","Contact: Ronald Piszar, Construction Official / Fire Sub-Code Official · (609) 296-7241 ext. 618 · rpiszar@leht.com","How to apply: Apply for the resale Existing Structure Certificate of Occupancy (see the town certificate); its inspection checklist covers smoke and CO alarms.","Fire official in the NJ state directory (NJ DCA, state), updated 5/30/2025: Louis Kilmer · (609)633-6132","Smoke alarms on each floor including the basement and within 10 feet of all bedrooms; interconnected systems must stay interconnected","CO alarms outside of and within 10 feet of all bedrooms","Fire extinguisher only required for rentals (per the Township form revised 2/24/2026)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Resale Certificate of Occupancy inspection (same single inspection as the town certificate; not charged twice)","amount":"$60.00"}]$j$::jsonb, $t$https://www.leht.com/wp-content/uploads/2026/02/EXISTING-STRUCTURE-RESALE-RENTAL-APPLICATION.pdf$t$, $t$https://www.leht.com/construction/$t$, $j$[{"url":"https://www.leht.com/wp-content/uploads/2026/02/EXISTING-STRUCTURE-RESALE-RENTAL-APPLICATION.pdf","label":"Official source (leht.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.leht.com/construction/","label":"Official source (leht.com)"}]$j$::jsonb, $t$Smoke Detectors: are required 1 on each floor of the house (including basement); also must be within 10 feet of any/all bedroom(s). If you have an interconnected system, all must be interconnected.$t$, $t$7515c8fa3184606f3782cd0c3bfd5b27138126669ea5af51c57d822787904099$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":17,"q_ok":8,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/1517.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1517.json$t$, true),
  ($t$1533$t$, $t$Tuckerton Borough$t$, $t$OCEAN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale inspection (Residential Resale / Rental Inspection)$t$, $j$["Issued by: Construction & Code Enforcement (Code Enforcement / Housing Official)","Contact: Joe Ventresca, Code Enforcement Officer / Housing Official · 609-296-4916","Apply: Inspections are done on Fridays only","How to apply: Fill out the Borough's Rental/Resale Application packet (fillable PDF, updated 10/2026; check 'Resale Inspection', give closing date and access or lock box instructions), attach the required professional certifications, and submit it to Construction & Code Enforcement, 420 East Main Street (609-296-4916, Monday to Friday 8:30 am to 3:30 pm). Cash, check or money order only. Inspections are Fridays only.","Yard free of debris and weeds and sheds empty; waterfront lots: bulkhead in good condition, fill maintained on the landward side, no floatable debris around or under the house","Home clean and move-in ready: trash, debris and hazardous material removed; paint, flooring, siding, roofing, windows and screens in good condition","Attached garage: 1/2 inch drywall on walls next to living space and on attic ceilings; two layers of type X drywall under living space above the garage; metal or rated doors in separation walls, including attic access","Stairs with graspable handrails and closed risers; decks and landings 30 inches or more above grade need 36 inch guardrails with openings under 4 inches","Smoke detectors to code (at least one per floor level in older homes and one within 10 feet of each bedroom) and CO detector within 10 feet of all bedrooms","Anti-tip device on the range","Electrical: no exposed wires, panel labeled, all boxes covered","Plumbing: water heater relief valve piped to within 6 inches of the floor; heating equipment properly vented","House numbers at least 4 inches near the front door (not on the door) and contrasting","Chimney caps on all fireplaces","For resales: well water test by the Board of Health (if on a well), Elevation Certificate and Septic Certificate (checklist marks these 'For resales and rentals')","Bulkhead certificate if the bulkhead is in questionable repair (decided the day of inspection)","Portable fire extinguisher, minimum 2A:10B:C, 2 1/2 to 10 lb dry chemical, within 10 feet of the kitchen (form still lists it)","No sleeping space on the third floor in Tuckerton Meadows or in second-floor loft areas in Bartletts Landing","Owner signs that all checklist items were checked","Also: Professional certifications for resales: The October 2026 checklist lists a well water test by the Board of Health (if on a well), an Elevation Certificate and a Septic Certificate for resales and rentals. Chimney, woodstove, fireplace, heat and hot water and lead paint certificates are now marked for rentals only.","Also: Bulkhead certificate (waterfront): Needed only if the bulkhead is in questionable repair, decided on the day of inspection."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://tuckertonborough.com/wp-content/uploads/2026/10/Rental-and-Resale-2026-Fillable.pdf$t$, $t$https://tuckertonborough.com/government/departments/construction-and-code-enforcement/$t$, $j$[{"url":"https://tuckertonborough.com/wp-content/uploads/2026/10/Rental-and-Resale-2026-Fillable.pdf","label":"Official source (tuckertonborough.com)"},{"url":"https://tuckertonborough.com/government/departments/construction-and-code-enforcement/forms/","label":"Official source (tuckertonborough.com)"},{"url":"https://tuckertonborough.com/government/departments/construction-and-code-enforcement/","label":"Official source (tuckertonborough.com)"}]$j$::jsonb, $t$Residential Resale / Rental Inspection Checklist$t$, $t$34cccb8aa85ad62f1ed8c4463c0f8fba3fb365dadd6aa1df4651309f7a2e64c3$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":19,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1533.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1533.json$t$, true),
  ($t$1533$t$, $t$Tuckerton Borough$t$, $t$OCEAN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Tuckerton Fire Prevention (Construction & Code Enforcement office) (town fire bureau)","Contact: Phil Reed, Construction Official, Zoning Official, Fire Protection Subcode Official and Fire Protection Inspector · 609-296-4916 · PReed@TuckertonBorough.com","Apply: Apply more than 10 business days ahead for the lowest fee; inspections Fridays only; must be done before the new owners occupy","How to apply: Fill out page 1 of the Borough's Rental/Resale Application (fillable PDF, updated 10/2026: inspection address, owners, buyers, contact person, closing date) and bring it with the non-refundable fee to 420 East Main Street, Tuckerton (609-296-4916). Cash, check or money order only. Inspections are Fridays only. A failed inspection costs $50.00 to re-inspect.","Smoke detectors on each level and outside each sleeping area near the bedrooms; hardwired or interconnected alarms required by year built: 1979 to 1981 hardwired outside sleeping areas; 1981 to 1987 hardwired outside sleeping areas and in the basement; 1987 to 1991 hardwired interconnected on each level; 1991 to present hardwired interconnected with battery backup in all bedrooms, outside each sleeping area and on every level","Since January 1, 2019 battery smoke alarms must be 10-year sealed units; all non-sealed battery detectors must be replaced; hardwired alarms from original construction may not be replaced with battery alarms","Smoke detectors not within 3 feet of a kitchen or bathroom, not within 20 feet of a flame-producing device, and not within 4 inches of a corner or lower than 12 inches from the ceiling on a wall","CO alarm within 10 feet of the sleeping areas","Portable fire extinguisher still on the October 2026 Borough form: minimum 2A:10B:C, 2 1/2 to 10 lb dry chemical, within 10 feet of the kitchen","If detectors cannot be reached, provide a ladder or a notarized letter stating they are in good working condition","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Inspection done more than 10 business days after the application is received","amount":"$75.00"},{"label":"Inspection done 4 to 10 business days after the application is received","amount":"$150.00"},{"label":"Inspection done 1 to 4 business days after the application is received","amount":"$225.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://tuckertonborough.com/wp-content/uploads/2026/10/Rental-and-Resale-2026-Fillable.pdf$t$, $t$https://tuckertonborough.com/government/departments/construction-and-code-enforcement/$t$, $j$[{"url":"https://tuckertonborough.com/wp-content/uploads/2026/10/Rental-and-Resale-2026-Fillable.pdf","label":"Official source (tuckertonborough.com)"},{"url":"https://tuckertonborough.com/government/departments/construction-and-code-enforcement/","label":"Official source (tuckertonborough.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification of smoke detector, carbon monoxide alarm and portable fire extinguisher compliance$t$, $t$dbbdff1c00d12d46d4fca93cbee171f715b6b42b8be82473cc24ecf85321a64b$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":19,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1533.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1533.json$t$, true),
  ($t$1610$t$, $t$Prospect Park Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (for sale)$t$, $j$["Issued by: Borough of Prospect Park Housing Department / Building Department (Code Enforcement), under Borough Code Chapter 90-33","Contact: Emine Hani, Housing Inspector / Code Enforcement Officer · (973) 790-7902 .ext 524 · code@prospectpark.net","How to apply: Fill out the Certificate of Compliance Application for Sale (owner, buyer, rooms, signature) and file it with the Building Department at Borough Hall, 106 Brown Avenue, with payment by cash, check or money order. Call for an inspection appointment. Certificate of Occupancy inspections are held Monday 1:30 to 2:30 pm and Tuesday and Thursday 2:00 to 2:30 pm.","Working smoke alarms and carbon monoxide alarms (the Housing Department inspects for both)","Ten-year sealed battery smoke alarms on each floor, including the basement and attic, and within 10 feet of all bedrooms","Battery smoke alarms cannot replace hardwired smoke alarms; hardwired systems must work","Carbon monoxide alarm within 10 feet of all bedrooms (plug-in, battery or combination units); the Housing Department page says one per floor","Fire extinguisher (4 to 10 lb) in every kitchen, wall-mounted no higher than 5 feet above the floor (listed on the fire safety sheet bundled with the 2026 sale form)","Compliance with the Borough's unfit buildings and housing standards ordinances"]$j$::jsonb, $j$[{"label":"Certificate of Compliance inspection, 1 family house","amount":"$75.00"},{"label":"Certificate of Compliance inspection, 2 family house","amount":"$150.00"},{"label":"Certificate of Compliance inspection, 3 family house","amount":"$225.00"},{"label":"Certificate of Compliance application for sale, 1 family / 2 family / 3 family (form)","amount":"$75.00 / $150.00 / 225.00"},{"label":"State online certificate, more than 10 business days before closing (only if the State issues the certificate for Prospect Park; the portal marks the Borough smoke-certificate exempt)","amount":"$45.00"},{"label":"State online certificate, 4 to 10 business days before closing (same caveat)","amount":"$90.00"},{"label":"State online certificate, less than 4 business days before closing (same caveat)","amount":"$161.00"}]$j$::jsonb, $t$https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf$t$, $t$https://www.prospectpark.net/departments/housing_department/index.php$t$, $j$[{"url":"https://www.prospectpark.net/departments/housing_department/index.php","label":"Official source (prospectpark.net)"},{"url":"https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf","label":"Official source (prospectpark.net)"},{"url":"https://www.prospectpark.net/contacts/index.php","label":"Official source (prospectpark.net)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Compliance is required when a house or business is about to be sold. We inspect for working smoke detectors and carbon monoxide detectors. Smoke detectors work best one in every bedroom. Carbon monoxide is required one per floor.$t$, $t$be4d7468d051354f2472487280dc122bb67a641ef3a48f09f53cae1a43b73dd5$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":16,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1610.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1610.json$t$, true),
  ($t$1610$t$, $t$Prospect Park Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough: issued by Borough of Prospect Park Housing Department / Building Department (Certificate of Compliance includes the smoke and carbon monoxide alarm inspection)","Entire borough contact: Emine Hani, Housing Inspector / Code Enforcement Officer · (973) 790-7902 .ext 524 · code@prospectpark.net","Entire borough, how to apply: Covered by the Borough Certificate of Compliance for sale: file the application for sale with the Building Department and call for an inspection appointment. See the town certificate section for fees.","NJ DCA Division of Fire Safety, Bureau of Fire…: issued by NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency) (NJ DCA, state). Covers: Entire borough (State enforces the fire code; whether the State issues resale smoke certificates here is doubtful, see notes)","NJ DCA Division of Fire Safety, Bureau of Fire… contact: Louis Kilmer, Fire Official (NJ Division of Fire Safety) · (609) 633-6132","NJ DCA Division of Fire Safety, Bureau of Fire…, apply: More than 10 business days before closing for the lowest state fee","NJ DCA Division of Fire Safety, Bureau of Fire…, how to apply: For towns where the State issues the certificate, apply online on the DCA Fire Safety portal and pay by e-check or credit card. The portal data flags Prospect Park as smoke-certificate exempt, so confirm with DCA or the Borough before applying there.","Fire official in the NJ state directory (NJ DCA, state), updated 1/12/2026: Louis Kilmer · (609)633-6132","Ten-year sealed battery smoke alarms on each floor, including the basement and attic, and within 10 feet of all bedrooms (Borough sheet)","Carbon monoxide alarm within 10 feet of all bedrooms (Borough sheet)","Fire extinguisher (4 to 10 lb) mounted in the kitchen no higher than 5 feet (still listed on the Borough's 2026 sheet even though the state dropped it from the state certificate in February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"NJ DCA Division of Fire Safety, Bureau of Fire…: State certificate, request received more than 10 business days before the change of occupant (only if the State issues the certificate for Prospect Park; the portal marks the Borough smoke-certificate exempt)","amount":"$45.00"},{"label":"NJ DCA Division of Fire Safety, Bureau of Fire…: State certificate, 4 to 10 business days before the change of occupant (same caveat)","amount":"$90.00"},{"label":"NJ DCA Division of Fire Safety, Bureau of Fire…: State certificate, fewer than 4 business days before the change of occupant (same caveat)","amount":"$161.00"}]$j$::jsonb, $t$https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf$t$, $t$https://www.prospectpark.net/departments/housing_department/index.php$t$, $j$[{"url":"https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf","label":"Official source (prospectpark.net)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.prospectpark.net/contacts/index.php","label":"Official source (prospectpark.net)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Chapter 90-33 of the Borough Ordinances requires a certificate of compliance. A certificate of compliance certifying compliance with Borough Ordinances entitled “Buildings, Unfit, and Housing Standards, and inspection of smoke detector & carbon monoxide alarm compliance.$t$, $t$2341e77eea558a70b16599a092efa5ef644edd47bd51c44d55591c5530d8748f$t$, $t$2026-10-27T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-27","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":16,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1610.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-27 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1610.json$t$, true),
  ($t$1704$t$, $t$Elsinboro Township$t$, $t$SALEM$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Change in Occupancy (Certificate of Continued Occupancy)$t$, $j$["Issued by: Elsinboro Township Housing and Zoning Officer","Contact: Andy Hoglen, Zoning and Housing Official (also Construction and Building Subcode Official) · 856-935-2200 · inspector@elsinborotownship.com","How to apply: Fill out the Township's Application for Certificate of Occupancy for Change in Occupancy (property, current owner, buyer, both realtors, type of dwelling and rooms) and have the seller's realtor or owner sign it. The application is not complete until the owner or realtor calls the Housing/Zoning Officer at 935-2200 to schedule the inspection. Zoning and housing hours are Thursday 3pm to 4pm (construction hours are now Wednesday 4:30pm to 6:00pm) at the Municipal Building, 619 Salem Ft-Elfsborg Rd, Salem.","Home may not be occupied until the Housing/Zoning Officer issues a certificate of occupancy","Water test (NJDEP and federal EPA chemical, bacteriological and gross alpha limits); not needed on a public water system","Chimney certification for all fossil fuel systems","Smoke detectors (each level, including the top of the basement stairs and a heated garage) and carbon monoxide alarms near bedrooms","Electrical panel labeled, 100 amp service or more","GFCI outlets in kitchen, bathrooms, laundry, garage and outside","Handrails on basement, porch and deck steps; emergency heater switch at the top of the stairs; heater serviced and inspected","Water heater relief pipe piped down","Roof, siding, windows, doors and screens in good repair; house numbered; trash, debris and abandoned vehicles removed","Fire-resistant door and walls between an attached garage and the house","Fire extinguisher (2A:10B:C) listed on the Township instructions, which predate P.L.2025, c.19","Also: Water test: A water test (NJDEP and federal EPA chemical, bacteriological and gross alpha limits) must be provided before the certificate is issued, unless the home is on a public water system.","Also: Chimney certification: Required for all fossil fuel systems; the visual inspection can be done by a heating contractor or chimney sweep.","Also: Lead-safe or lead-free certificate (pre-1979 homes, rental rule): Township Code §145-4 says no certificate of occupancy for a home built before 1979 can be issued without a lead-safe or lead-free certificate from a state-licensed lead inspector. The section is written for rental units under P.L.2021, c.182; ask whether the Township applies it to owner-occupied sales."]$j$::jsonb, $j$[{"label":"Certificate of occupancy (change in occupancy) inspection","amount":"$30.00"},{"label":"Re-inspection","amount":"$30.00"}]$j$::jsonb, $t$https://assets.zyrosite.com/Hk1eZdfjLtvdh0WU/coapplication-M5puFZ2iiXlZcJ53.pdf$t$, $t$https://elsinborotownship.com/elsinboro-township-departments$t$, $j$[{"url":"https://assets.zyrosite.com/Hk1eZdfjLtvdh0WU/coapplication-M5puFZ2iiXlZcJ53.pdf","label":"Official source (assets.zyrosite.com)"},{"url":"https://ecode360.com/40415147","label":"Official source (ecode360.com)"},{"url":"https://elsinborotownship.com/elsinboro-township-departments","label":"Official source (elsinborotownship.com)"},{"url":"https://assets.zyrosite.com/Hk1eZdfjLtvdh0WU/reorganization-2026-min-jgjLAaapjvJQWMij.pdf","label":"Official source (assets.zyrosite.com)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF OCCUPANCY FOR CHANGE IN OCCUPANCY PURSUANT TO ORDINANCE # 77-9 & 79-3$t$, $t$9f28f54af1278f1b6f5cb73c2d35ace2ad2774fab2f7fa06b0ad550c5d6a41fb$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":8,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1704.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1704.json$t$, true),
  ($t$1704$t$, $t$Elsinboro Township$t$, $t$SALEM$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire township: issued by Elsinboro Township Housing and Zoning Officer (smoke and carbon monoxide checked in the Township certificate of occupancy inspection; not confirmed as the smoke certificate issuer)","Entire township contact: Andy Hoglen, Zoning and Housing Official · 856-935-2200 · inspector@elsinborotownship.com","Entire township, how to apply: Unconfirmed. The Township's certificate of occupancy inspection covers smoke detectors and carbon monoxide alarms; call the Township at 856-935-2200 to ask whether it also issues the state smoke and carbon monoxide certificate, or whether to apply to the NJ DCA.","Entire township (fire code enforcement): issued by NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency) (NJ DCA, state)","Entire township (fire code enforcement) contact: Louis Kilmer, State Fire Official listed for Elsinboro Township in the state fire directory (DCA Bureau of Fire Code Enforcement) · (609) 633-6132","Entire township (fire code enforcement), how to apply: Do not rely on the State's online smoke certificate application for this town: the DCA portal data marks ELSINBORO TWP-001 as smoke-certificate exempt, which means the town is not offered in the State's online application. Ask the Township who issues the certificate; the DCA Bureau of Fire Code Enforcement can confirm.","Fire official in the NJ state directory (NJ DCA, state), updated 3/9/2026: Louis Kilmer · (609)633-6132","Township certificate of occupancy checks smoke detectors on each level (including the top of the basement stairs and a heated garage) and carbon monoxide alarms near bedrooms","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://elsinborotownship.com/elsinboro-township-departments$t$, $j$[{"url":"https://assets.zyrosite.com/Hk1eZdfjLtvdh0WU/coapplication-M5puFZ2iiXlZcJ53.pdf","label":"Official source (assets.zyrosite.com)"},{"url":"https://ecode360.com/40415147","label":"Official source (ecode360.com)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Carbon Monoxide Alarms Attachment enclosed ... Smoke Detectors Attachment enclosed$t$, $t$19bb96e1f8f84f7e07b895cc55fbbf8d6c6686104eb9665c0b74d04d7ff6ece2$t$, $t$2026-10-20T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-20","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":8,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1704.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-20 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1704.json$t$, true)
